// ── Cutover-day Bison send backfill (2026-06-19 ONLY) ─────────────────────────
// On the migration day BOTH ESPs sent: PlusVibe AND EmailBison. PV's email-stats
// only knows PV's own sends, so today's totals were short by Bison's volume.
// These are Bison's FINAL per-workspace sends/bounces for 2026-06-19 (Bison no
// longer sends), ADDED on top of PV's so the day's totals are complete. Replies
// are NOT here — the portal already captures replies to both ESPs. Keyed by PV
// workspace_id; a no-op for any other date.
const BISON_CUTOVER_BACKFILL = {
  '2026-06-19': {
    '69a9db307af7ef2854f57637': { sent: 77,  bounces: 10 }, // ButterflyEco
    '6a15cdb4e4f1d4a2e6d6062a': { sent: 100, bounces: 3 },  // Shire
    '6a15cda912293dbfe5eab6c3': { sent: 4,   bounces: 0 },  // MDH
    '6a108e72b20829cbce44fa6c': { sent: 108, bounces: 2 },  // Meades
    '6a108e69cfbd57f86dbea524': { sent: 71,  bounces: 0 },  // Lending Team
    '6a0e29d0d004be93be3f33f2': { sent: 142, bounces: 1 },  // Bubble
    '6a0cc49a4a80688441614dfb': { sent: 181, bounces: 3 },  // MagnaMoney
    '69ffaf6904ca7138af16013a': { sent: 103, bounces: 0 },  // Bruud
    '69c43d1e07bf312ff0026643': { sent: 42,  bounces: 0 },  // GXI Furniture
    '69c43d1407bf312ff0026642': { sent: 12,  bounces: 0 },  // GXI
    '6a19a054d42a3f59aac110d6': { sent: 143, bounces: 0 },  // LVM
    '695259c3d6154e27d164bcf7': { sent: 124, bounces: 7 },  // Indigo
    '699714b02f0830a7148fcf3e': { sent: 83,  bounces: 4 },  // Enviro
    '695259dc8de377db7577dc45': { sent: 73,  bounces: 0 },  // PPC
    '697e20f02db8460f8ba68792': { sent: 121, bounces: 5 },  // Jumping Spider
    '69525a0eceae00718efdaeaa': { sent: 196, bounces: 0 },  // HydrationCompany
  },
};
// Add the cutover backfill to a per-(wsId,date) agg in place. Idempotent per call
// (the override is a fixed constant, added once when the agg is (re)built).
function applyCutoverBackfill(wsId, date, agg) {
  const b = BISON_CUTOVER_BACKFILL[date] && BISON_CUTOVER_BACKFILL[date][wsId];
  if (!b) return agg;
  agg.sent = (agg.sent || 0) + (b.sent || 0);
  agg.bounces = (agg.bounces || 0) + (b.bounces || 0);
  return agg;
}

// ── "Fresh start" date floor ──────────────────────────────────────────────────
// Stats date range clamp (sequencer views only — NOT finance/revenue).
let _freshStartDate = null;
let _showHistorical = false;
async function hydrateFreshStart(pgdb) {
  try {
    _freshStartDate = (await pgdb.getSetting('fresh_start_date', null)) || null;
    _showHistorical = (await pgdb.getSetting('show_historical', false)) === true;
  } catch (e) { console.warn('[fresh-start] hydrate failed:', e.message); }
}
function clampStartDate(startStr) {
  if (_showHistorical || !_freshStartDate || !startStr) return startStr;
  return startStr < _freshStartDate ? _freshStartDate : startStr;
}

// Resolve canonical workspace_id (by id or by name lookup in PV_WORKSPACES).
function canonicalWorkspaceId(wsId, name) {
  const s = String(wsId || '').trim();
  const byId = PV_WORKSPACES.find(t => t.pv === s);
  if (byId) return byId.pv;
  const n = String(name || '').trim().toLowerCase();
  if (n) {
    const byName = PV_WORKSPACES.find(t => t.name.toLowerCase() === n);
    if (byName) return byName.pv;
  }
  return s;
}

// Background blocklist: add a bounced email to ALL PlusVibe workspaces.
const _blocklistQueue = [];
let _blocklistDraining = false;
const _blocklistDone = new Set();
async function _drainBlocklistQueue() {
  if (_blocklistDraining) return;
  _blocklistDraining = true;
  try {
    while (_blocklistQueue.length) {
      const { email, wsId } = _blocklistQueue.shift();
      const key = email + '|' + wsId;
      if (_blocklistDone.has(key)) continue;
      try {
        await pvApi('/blocklist/add', { method: 'POST', wsId, body: { value: email, type: 'email' } });
        _blocklistDone.add(key);
      } catch (e) { /* best-effort */ }
    }
  } finally { _blocklistDraining = false; }
}
function blocklistEmailEverywhere(email, bouncedWsId) {
  if (!email) return;
  const global = process.env.BOUNCE_BLOCK_GLOBAL !== '0';
  const wsIds = global
    ? PV_WORKSPACES.map(t => t.pv)
    : (bouncedWsId ? [String(bouncedWsId)] : []);
  for (const wsId of wsIds) {
    const key = email + '|' + wsId;
    if (_blocklistDone.has(key)) continue;
    _blocklistQueue.push({ email, wsId });
  }
  _drainBlocklistQueue();
}

// PlusVibe workspace-leads: GET /lead/workspace-leads?workspace_id=&label=&page=&limit=
async function pvWorkspaceLeads(wsId, opts = {}) {
  const label = opts.label || 'INTERESTED';
  const limit = opts.perPage || 100;
  const page  = opts.page  || 1;
  // PlusVibe deprecated the `skip` param (now 400s: "skip is not allowed");
  // pagination is `page`-based. See the page= call sites elsewhere in this file.
  const resp = await pvApi('/lead/workspace-leads', { wsId, params: { label, limit, page } });
  const list = Array.isArray(resp) ? resp : (resp?.leads || resp?.data || []);
  return list.map(l => Object.assign({}, l, {
    _id: l._id || l.id || null,
    email: l.email || null,
  }));
}

// PlusVibe /lead/add validates each lead with a strict schema and rejects the
// WHOLE batch on the first bad one. Two known triggers: (1) email local-parts
// with apostrophes etc. — PV's regex is /^[a-z0-9...]/ and excludes them, so
// O'Sullivan-style addresses 400; (2) phone_number that isn't a string. This
// normalises a single lead in place so one bad row can't poison a 100-lead
// batch. Returns { lead, changed, reason } — `changed` flags an email rewrite
// so the caller can stamp the DB; the cleaned address should be re-verified.
const PV_EMAIL_LOCAL_OK = /^[a-z0-9._%+\-]+$/i;
function sanitizePvLead(lead) {
  const out = { ...lead };
  let changed = false;
  let reason = null;

  // phone_number must be a string — coerce null/number → string.
  if (out.phone_number != null && typeof out.phone_number !== 'string') {
    out.phone_number = String(out.phone_number);
  }

  const email = (out.email || '').trim();
  const at = email.lastIndexOf('@');
  if (at > 0) {
    const local = email.slice(0, at);
    const domain = email.slice(at + 1);
    if (!PV_EMAIL_LOCAL_OK.test(local)) {
      // Strip every char PlusVibe's regex won't accept (apostrophes, spaces…).
      const cleanedLocal = local.replace(/[^a-z0-9._%+\-]/gi, '');
      if (cleanedLocal && cleanedLocal !== local) {
        out.email = `${cleanedLocal}@${domain}`;
        changed = true;
        reason = `email local-part sanitised: "${email}" → "${out.email}"`;
      } else {
        reason = `email rejected by PlusVibe pattern, unrecoverable: "${email}"`;
      }
    }
  }
  return { lead: out, changed, reason };
}

