// ── Engine Leads ──────────────────────────────────────────
// Read-only view over ottaly_engine_leads — clean B2B leads the autonomous
// data engine promotes into prod. Table grows 24/7, so always paginate.
// Shared helper: build the WHERE clause + params from query filters so the
// list and export endpoints stay in sync.
function buildEngineLeadsFilter(q) {
  const industry    = (q.industry  || '').trim() || null;
  const region      = (q.region    || '').trim() || null;
  const platform    = (q.platform  || '').trim() || null;
  const search      = (q.search    || '').trim() || null;
  // has_products: 'true' | 'false' | anything-else => no filter (null)
  let hasProducts = null;
  if (q.has_products === 'true')  hasProducts = true;
  if (q.has_products === 'false') hasProducts = false;

  const where = `
    WHERE ($1::text IS NULL OR industry ILIKE '%'||$1||'%')
      AND ($2::text IS NULL OR region   ILIKE '%'||$2||'%')
      AND ($3::bool IS NULL OR has_products = $3)
      AND ($4::text IS NULL OR platform ILIKE '%'||$4||'%')
      AND ($5::text IS NULL OR domain ILIKE '%'||$5||'%' OR company_name ILIKE '%'||$5||'%')`;

  return { where, params: [industry, region, hasProducts, platform, search] };
}

app.get('/api/engine-leads', requireSession, async (req, res) => {
  const pgdb = req.app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });

  const limit  = Math.min(parseInt(req.query.limit || '50', 10) || 50, 200);
  const offset = Math.max(parseInt(req.query.offset || '0', 10) || 0, 0);

  const { where, params } = buildEngineLeadsFilter(req.query);

  try {
    const countRes = await pgdb.query(
      `SELECT COUNT(*)::int AS n FROM ottaly_engine_leads ${where}`,
      params
    );
    const total = countRes.rows[0].n;

    const { rows } = await pgdb.query(
      `SELECT * FROM ottaly_engine_leads ${where}
       ORDER BY promoted_at DESC NULLS LAST
       LIMIT $6 OFFSET $7`,
      [...params, limit, offset]
    );

    res.json({ total, limit, offset, count: rows.length, leads: rows });
  } catch (e) {
    console.error('[engine-leads] query failed:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/engine-leads/export', requireSession, async (req, res) => {
  const pgdb = req.app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });

  const { where, params } = buildEngineLeadsFilter(req.query);

  try {
    const { rows } = await pgdb.query(
      `SELECT domain, company_name, company_number, email_primary, emails,
              phones, director_name, address, postcode, sic_code, industry,
              region, company_size, linkedin_url, has_products, product_count,
              page_count, platform, promoted_at
       FROM ottaly_engine_leads ${where}
       ORDER BY promoted_at DESC NULLS LAST`,
      params
    );

    const cols = [
      'Domain', 'Company Name', 'Company Number', 'Email', 'All Emails',
      'Phones', 'Director', 'Address', 'Postcode', 'SIC Code', 'Industry',
      'Region', 'Company Size', 'LinkedIn', 'Has Products', 'Product Count',
      'Page Count', 'Platform', 'Promoted At',
    ];
    const arr = v => Array.isArray(v) ? v.join('; ') : (v == null ? '' : v);
    const esc = v => v == null ? '' : `"${String(v).replace(/"/g, '""')}"`;
    const csv = [cols.join(','), ...rows.map(r => [
      r.domain, r.company_name, r.company_number, r.email_primary, arr(r.emails),
      arr(r.phones), r.director_name, r.address, r.postcode, r.sic_code, r.industry,
      r.region, r.company_size, r.linkedin_url, r.has_products, r.product_count,
      r.page_count, r.platform, r.promoted_at,
    ].map(esc).join(','))].join('\n');

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="engine-leads.csv"`);
    res.send(csv);
  } catch (e) {
    console.error('[engine-leads/export] query failed:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/admin/export-missing-enrichment', requireAdmin, async (req, res) => {
  const pgdb = app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'Database not available' });
  const { rows } = await pgdb.query(`
    SELECT workspace_id, email, first_name, last_name, company_name, company_domain,
           job_title, industry, city, state, country, linkedin_url,
           num_employees, keywords
    FROM contacts
    WHERE (keywords IS NULL OR keywords = '')
       OR num_employees IS NULL
       OR (industry IS NULL OR industry = '')
       OR (city IS NULL OR city = '')
    ORDER BY workspace_id, company_domain
  `);
  const cols = ['workspace_id','email','first_name','last_name','company_name','company_domain','job_title','industry','city','state','country','linkedin_url','num_employees','keywords'];
  const escape = v => v == null ? '' : `"${String(v).replace(/"/g, '""')}"`;
  const csv = [cols.join(','), ...rows.map(r => cols.map(c => escape(r[c])).join(','))].join('\n');
  res.setHeader('Content-Type', 'text/csv');
  res.setHeader('Content-Disposition', 'attachment; filename="missing_enrichment.csv"');
  res.send(csv);
});

// ── AI Enrichment helpers ─────────────────────────────────────────────────

// Haiku pricing per million tokens
const HAIKU_PRICE = { input: 0.80, output: 4.00, cache_write: 1.00, cache_read: 0.08 };

const CH_SIZE_MAP = {
  'micro-entity': 5, 'micro': 5,
  'small': 25,
  'medium': 150,
  'full': 500, 'group': 500,
  'total-exemption-small': 25, 'total-exemption-full': 500,
  'dormant': 1,
};

// ── Companies House rate limiter ───────────────────────────────────────────
// CH allows ~600 requests / 5 min (2/sec) and 429s hard above that. The enrich
// job runs at high concurrency and each domain makes 2-3 CH calls, so without a
// GLOBAL throttle every request 429s ("no response", 0 updated). This gates ALL
// CH fetches through one shared promise-chain at a safe minimum interval,
// independent of job concurrency, and retries once on a 429 honouring Retry-After.
const CH_MIN_INTERVAL_MS = 400; // ~2.5 req/s — under CH's 2/s sustained limit with headroom
let _chChain = Promise.resolve();
let _chLastAt = 0;
// Reserve the next time-slot atomically by advancing a single shared chain.
function _chSlot() {
  const wait = () => {
    const gap = Math.max(0, CH_MIN_INTERVAL_MS - (Date.now() - _chLastAt));
    return new Promise(res => setTimeout(() => { _chLastAt = Date.now(); res(); }, gap));
  };
  const slot = _chChain.then(wait);
  _chChain = slot.catch(() => {}); // keep the chain alive even if a slot rejects
  return slot;
}
async function chFetch(url, opts) {
  // Wait for our throttle slot FIRST (this can be a long queue wait under
  // concurrency), THEN time only the actual network call — so a deep queue
  // doesn't trip the per-fetch timeout.
  await _chSlot();
  const once = () => Promise.race([
    fetch(url, opts),
    new Promise((_, rej) => setTimeout(() => rej(new Error('CH fetch timeout')), 12000)),
  ]);
  let r = await once();
  if (r.status === 429) {
    const ra = parseInt(r.headers.get('retry-after') || '5', 10);
    await new Promise(res => setTimeout(res, Math.min(Math.max(ra, 1), 30) * 1000));
    await _chSlot();
    r = await once();
  }
  return r;
}

// Clean an Apollo company_name into a CH-searchable term. These names are often
// the bare domain ("108properties.co.uk") or carry junk (©, %, ™). CH search
// returns 0 for those, but matches once the TLD/junk is stripped
// ("108properties" → "108 PROPERTIES LIMITED").
function cleanCompanyNameForCH(name) {
  if (!name) return '';
  let s = String(name).trim()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '');
  // Strip a trailing domain TLD if the name is really a domain.
  s = s.replace(/\.(co\.uk|org\.uk|ac\.uk|ltd\.uk|plc\.uk|com|co|net|org|io|uk|biz|info|me|app|dev|shop|store|agency|digital|group|tech|online|site)$/i, '');
  // Drop junk symbols but keep & and alphanumerics/spaces.
  s = s.replace(/[©®™%*]/g, ' ').replace(/\s+/g, ' ').trim();
  return s;
}
// Tokenise a company name for match comparison: lowercase, drop company
// suffixes, split into alphanumeric tokens. Keeps word structure so prefix
// checks can align on token boundaries (not mid-number).
function tokeniseCompany(s) {
  return String(s || '').toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/\b(limited|ltd|llp|plc|inc|llc|holdings|group|company|the)\b/g, ' ')
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}
// Is the CH-matched title a confident match? The names are compared as their
// full concatenations, but a prefix only counts when it ends on a TOKEN
// boundary of the other side. This accepts glommed domain-names
// ("108properties" ⇿ "108 PROPERTIES LIMITED") and genuine prefixes
// ("12sides" → "12SIDES CONSULTANCY") while rejecting mid-token coincidences
// ("100and10" must NOT match "100 AND 102 REPLINGHAM ROAD" — "10" ⊂ "102").
function isConfidentCHMatch(searchTerm, matchedTitle) {
  const aTok = tokeniseCompany(searchTerm);
  const bTok = tokeniseCompany(matchedTitle);
  const aFull = aTok.join(''), bFull = bTok.join('');
  if (!aFull || !bFull) return false;
  if (aFull === bFull) return true;
  // full string of one side must equal a token-aligned prefix of the other
  const prefixAligned = (full, toks) => {
    let acc = '';
    for (const t of toks) {
      acc += t;
      if (acc === full) return true;
      if (acc.length >= full.length) return false; // overshot a boundary
    }
    return false;
  };
  return prefixAligned(aFull, bTok) || prefixAligned(bFull, aTok);
}

async function fetchCompaniesHouse(companyName) {
  const key = process.env.COMPANIES_HOUSE_API_KEY;
  if (!key) return null;
  const cleaned = cleanCompanyNameForCH(companyName);
  if (!cleaned) return null;
  const auth = { 'Authorization': 'Basic ' + Buffer.from(key + ':').toString('base64') };
  try {
    // chFetch handles throttle + per-call timeout, so no extra deadline race here
    // (which previously fired on the QUEUE wait, not the fetch, → false "no response").
    // Step 1: search — pull top 5 candidates and pick the first CONFIDENT match,
    // so CH's fuzzy ranking can't hand us an unrelated company's SIC codes.
    const q = encodeURIComponent(cleaned.slice(0, 60));
    const sr = await chFetch(`https://api.company-information.service.gov.uk/search/companies?q=${q}&items_per_page=5`, { headers: auth });
    if (!sr.ok) return null;
    const sj = await sr.json();
    const item = (sj?.items || []).find(it => it?.company_number && isConfidentCHMatch(cleaned, it.title));
    if (!item?.company_number) return null;

    // Step 2: fetch full company profile
    const pr = await chFetch(`https://api.company-information.service.gov.uk/company/${item.company_number}`, { headers: auth });
    if (!pr.ok) return null;
    const p = await pr.json();

    const accountsType = p?.accounts?.last_accounts?.type || null;
    const num_employees = accountsType ? (CH_SIZE_MAP[accountsType] || null) : null;
    const addr = p?.registered_office_address;
    const city    = addr?.locality || addr?.address_line_2 || null;
    const country = addr?.country || 'United Kingdom';
    const sic     = p?.sic_codes?.[0] || item?.sic_codes?.[0] || null;

    const rawStatus = p?.company_status || null;
    const company_status = rawStatus ? (rawStatus === 'active' ? 'active' : 'not active') : null;

    // Fetch officer count (best-effort — failure here must not lose the SIC data)
    const or = await chFetch(`https://api.company-information.service.gov.uk/company/${item.company_number}/officers?items_per_page=1`, { headers: auth })
      .then(r => r.json()).catch(() => null);

    // Build full address string
    const addrParts = [addr?.premises, addr?.address_line_1, addr?.address_line_2, addr?.locality, addr?.region, addr?.postal_code, addr?.country].filter(Boolean);

    return {
      company_status,
      num_employees,
      city:    addr?.locality || null,
      country: addr?.country  || 'United Kingdom',
      sic,
      ch_company_number:    item.company_number,
      ch_company_type:      p?.type || null,
      ch_founded_year:      p?.date_of_creation ? parseInt(p.date_of_creation.slice(0,4), 10) : null,
      ch_postcode:          addr?.postal_code || null,
      ch_sic_codes:         (p?.sic_codes || []).join(',') || null,
      ch_jurisdiction:      p?.jurisdiction || null,
      ch_has_insolvency:    p?.has_insolvency_history ?? null,
      ch_has_charges:       p?.has_charges ?? null,
      ch_accounts_overdue:  p?.accounts?.next_accounts?.overdue ?? null,
      ch_active_officers:   or?.active_count ?? null,
      ch_resigned_officers: or?.resigned_count ?? null,
      ch_address:           addrParts.join(', ') || null,
      ch_date_of_cessation: p?.date_of_cessation || null,
      ch_last_accounts_date: p?.accounts?.last_accounts?.made_up_to || null,
      ch_year_end_month:    p?.accounts?.accounting_reference_date?.month ? parseInt(p.accounts.accounting_reference_date.month, 10) : null,
      ch_data:              p,
    };
  } catch { return null; }
}

// ── Gemini with self-healing model resolution ──────────────────────────────
// Google retires model names (gemini-2.0-flash → 404), which silently broke
// enrichment. Instead of hardcoding one name, try a candidate list and cache the
// first that works for the session. GEMINI_MODEL overrides the whole list.
let _geminiModel = null; // cached working model id for this process
let _geminiErrLogged = false; // log AI failures once per run, not per domain (avoids log spam)
const _GEMINI_CANDIDATES = [
  'gemini-2.5-flash', 'gemini-flash-latest', 'gemini-2.0-flash-001',
  'gemini-2.5-flash-lite', 'gemini-1.5-flash',
];
// Verify a domain actually exists before trusting an LLM-suggested one — Gemini
// hallucinates plausible-but-dead domains from company names. A real business
// domain resolves MX (or at least A) records; a made-up one usually resolves
// nothing. Cheap DNS lookup, ~no cost, kills fake domains before Reacher.
const _dnsp = require('dns').promises;
async function domainResolves(domain) {
  if (!domain) return false;
  try {
    const mx = await _dnsp.resolveMx(domain).catch(() => []);
    if (mx && mx.length) return true;
  } catch {}
  try {
    const a = await _dnsp.resolve4(domain).catch(() => []);
    if (a && a.length) return true;
  } catch {}
  return false;
}

// Stronger gate than DNS: does the website actually serve a page? Catches
// parked/suspended/expired domains that still have DNS but no live site. We
// only spend a (rate-limited) email verification when the site genuinely
// responds. Tries HTTPS then HTTP; a 2xx/3xx/401/403 counts as "alive" (the
// server is up even if it gates access). Cached per-process to avoid re-hitting
// the same domain within a run.
const _siteLiveCache = new Map();
async function websiteIsLive(domain) {
  if (!domain) return false;
  if (_siteLiveCache.has(domain)) return _siteLiveCache.get(domain);
  const tryUrl = async (url) => {
    try {
      const r = await Promise.race([
        fetch(url, { method: 'HEAD', redirect: 'follow' }),
        new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 6000)),
      ]);
      // HEAD sometimes 405s on servers that are clearly up — treat <500 as alive.
      return r.status < 500;
    } catch { return false; }
  };
  let live = await tryUrl(`https://${domain}`);
  if (!live) live = await tryUrl(`http://${domain}`);
  _siteLiveCache.set(domain, live);
  return live;
}

// Pull the first JSON object out of an LLM response, tolerating preamble like
// "Here is the JSON requested:" or markdown fences. Returns null on failure.
function extractJson(text) {
  if (!text) return null;
  try { return JSON.parse(text); } catch {}
  const cleaned = text.replace(/```(?:json)?/gi, '');
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) return null;
  try { return JSON.parse(cleaned.slice(start, end + 1)); } catch { return null; }
}
// ── SearXNG web-search domain finder ───────────────────────────────────────
// Self-hosted SearXNG (Easypanel) with JSON output enabled. Mojeek is the only
// reliable engine (Google/DuckDuckGo/Brave block the datacenter IP); it returns
// real indexed company sites — far better than asking an LLM to recall a small
// UK company's domain. SEARXNG_URL overrides the default host.
const SEARXNG_URL = (process.env.SEARXNG_URL || 'https://ottaly-searxng.oix3xv.easypanel.host').replace(/\/$/, '');
// Engine priority for company-URL lookup. Mojeek gives the cleanest company
// sites; bing survives the datacenter IP more often but is noisy (the token
// scorer filters its junk). Tried in order, first confident match wins. On a
// datacenter IP all engines block intermittently — when they do, we fall back
// to Gemini. (A residential proxy would fix the blocking but is deliberately
// NOT used here so SearXNG never touches Reacher's metered proxy quota.)
const SEARXNG_ENGINES = process.env.SEARXNG_ENGINES || 'mojeek,bing';

// Directory / aggregator / junk domains that are never a company's own site.
const NON_COMPANY_DOMAINS = new Set([
  'companieshouse.gov.uk', 'find-and-update.company-information.service.gov.uk',
  'gov.uk', 'endole.co.uk', 'dnb.com', 'opencorporates.com', 'companycheck.co.uk',
  'companieslist.co.uk', 'creditsafe.com', 'globaldatabase.com', 'bizdb.co.uk',
  'linkedin.com', 'facebook.com', 'twitter.com', 'x.com', 'instagram.com',
  'youtube.com', 'tiktok.com', 'pinterest.com', 'yell.com', 'yelp.com',
  'trustpilot.com', 'tripadvisor.com', 'tripadvisor.co.uk', 'glassdoor.com',
  'indeed.com', 'crunchbase.com', 'bloomberg.com', 'reuters.com', 'wikipedia.org',
  'amazon.co.uk', 'amazon.com', 'ebay.co.uk', 'booking.com', 'dailymail.co.uk',
  'skybet.com', 'companiesintheuk.co.uk', 'ukbusinessforums.co.uk',
]);
function searxRootDomain(host) {
  const h = (host || '').toLowerCase().replace(/^www\./, '');
  const labels = h.split('.');
  // keep 3 labels for *.co.uk / *.org.uk / *.ltd.uk etc., else 2
  if (/\.(co|org|ltd|plc|me|gov|ac|net)\.uk$/.test(h)) return labels.slice(-3).join('.');
  return labels.slice(-2).join('.');
}
// Tokenise a company name into meaningful words (drop LTD/LIMITED/THE/&/etc.)
function companyNameTokens(name) {
  return (name || '').toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !['ltd','limited','plc','llp','the','and','uk','group','company','co','services','holdings','international'].includes(w));
}
// Query SearXNG and return the best-matching official domain for a company, or
// null. Scores candidates by company-name tokens appearing in the domain,
// preferring .co.uk/.uk, and rejecting directory/social/aggregator domains.
async function searxLookupDomain(company) {
  const name = (typeof company === 'string') ? company : company.company_name;
  if (!name) return null;
  // Try each engine in priority order; first that returns a confident match wins.
  // On a datacenter IP engines get blocked/rate-limited unpredictably, so we
  // fall through engine-by-engine, then return null so the caller uses Gemini.
  // The token-scorer rejects junk (so Bing's noisy results can't produce a wrong
  // domain — only a real name-matching domain scores > 0).
  const tokens = companyNameTokens(name);
  const compact = tokens.join('');
  const engineList = SEARXNG_ENGINES.split(',').map(e => e.trim()).filter(Boolean);
  for (const engine of engineList) {
    try {
      const url = `${SEARXNG_URL}/search?q=${encodeURIComponent(name)}&format=json&engines=${encodeURIComponent(engine)}`;
      const r = await fetch(url, { headers: { Accept: 'application/json' }, signal: AbortSignal.timeout(8000) });
      if (!r.ok) continue;
      const j = await r.json();
      const results = Array.isArray(j?.results) ? j.results : [];
      if (!results.length) continue; // engine blocked or no hits → next engine
      const scored = [];
      const seen = new Set();
      for (let i = 0; i < results.length; i++) {
        let host;
        try { host = new URL(results[i].url).hostname.toLowerCase().replace(/^www\./, ''); } catch { continue; }
        const root = searxRootDomain(host);
        if (NON_COMPANY_DOMAINS.has(root) || NON_COMPANY_DOMAINS.has(host)) continue;
        if (seen.has(root)) continue;
        seen.add(root);
        const domainText = root.replace(/\.[a-z.]+$/, ''); // strip TLD for token matching
        let score = 0;
        for (const t of tokens) if (domainText.includes(t)) score += 3;
        if (compact && domainText.includes(compact)) score += 4; // "rentmyplaceuk" ← "Rent My Place UK"
        score += Math.max(0, 5 - i) * 0.5;                       // earlier result = small bonus
        if (/\.co\.uk$/.test(root) || /\.uk$/.test(root)) score += 1;
        if (score > 0) scored.push({ root, score, rank: i });
      }
      if (!scored.length) continue; // results were all junk → try next engine
      scored.sort((a, b) => b.score - a.score || a.rank - b.rank);
      return scored[0].root;
    } catch {
      continue; // timeout/blocked → next engine
    }
  }
  return null;
}

// Look up a company's website domain via Gemini using a strict responseSchema
// (so the model returns a typed object, not free text + preamble) and a token
// budget high enough to survive 2.5-flash's thinking tokens. Returns a bare
// domain string or null. Separate from geminiGenerate so the shared enrichment
// path keeps its tuned 250-token cap.
async function geminiLookupDomain(key, companyName) {
  const body = JSON.stringify({
    contents: [{ role: 'user', parts: [{ text: `What is the website domain (no protocol, no www) for the UK company "${companyName}"? Return null if you don't know it.` }] }],
    generationConfig: {
      maxOutputTokens: 2048,
      temperature: 0,
      responseMimeType: 'application/json',
      responseSchema: { type: 'OBJECT', properties: { website: { type: 'STRING', nullable: true } }, required: ['website'] },
    },
  });
  const candidates = [process.env.GEMINI_MODEL, _geminiModel, ..._GEMINI_CANDIDATES].filter(Boolean);
  const tried = new Set();
  for (const model of candidates) {
    if (tried.has(model)) continue; tried.add(model);
    try {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
      const r = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body });
      if (!r.ok) { if (r.status === 404) continue; return null; }
      const j = await r.json();
      const text = j?.candidates?.[0]?.content?.parts?.[0]?.text || '';
      const parsed = extractJson(text);
      if (!parsed) return null;
      const raw = (parsed.website || '').replace(/^https?:\/\//i, '').replace(/\/.*/, '').replace(/^www\./i, '').trim().toLowerCase();
      if (!raw) return null;
      // Reject hallucinated domains — only trust ones with real DNS (MX/A).
      const ok = await domainResolves(raw);
      if (!ok) { console.log(`[ch] discarded unresolvable domain "${raw}" for "${companyName}"`); return null; }
      return raw;
    } catch { continue; }
  }
  return null;
}
// Full company enrichment via Gemini with a strict responseSchema — returns
// website + richer firmographics in one call. Null fields where unknown.
async function geminiEnrichCompany(key, company) {
  const body = JSON.stringify({
    contents: [{ role: 'user', parts: [{ text:
      `Research the UK company "${company.company_name}" (type: ${company.company_type || 'unknown'}, SIC codes: ${company.sic_codes || 'unknown'}, postcode area: ${company.postcode || 'unknown'}). Provide what you can find; use null for anything you don't know. Do NOT guess a website if you're not confident it's real.` }] }],
    generationConfig: {
      maxOutputTokens: 2048,
      temperature: 0,
      responseMimeType: 'application/json',
      responseSchema: {
        type: 'OBJECT',
        properties: {
          website: { type: 'STRING', nullable: true },
          linkedin: { type: 'STRING', nullable: true },
          industry: { type: 'STRING', nullable: true },
          keywords: { type: 'STRING', nullable: true },
          description: { type: 'STRING', nullable: true },
          employees: { type: 'STRING', nullable: true },
        },
        required: ['website'],
      },
    },
  });
  const candidates = [process.env.GEMINI_MODEL, _geminiModel, ..._GEMINI_CANDIDATES].filter(Boolean);
  const tried = new Set();
  for (const model of candidates) {
    if (tried.has(model)) continue; tried.add(model);
    try {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
      const r = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body });
      if (!r.ok) { if (r.status === 404) continue; return null; }
      const j = await r.json();
      const text = j?.candidates?.[0]?.content?.parts?.[0]?.text || '';
      return extractJson(text);
    } catch { continue; }
  }
  return null;
}
async function geminiGenerate(key, systemPrompt, userPrompt) {
  const body = JSON.stringify({
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
    generationConfig: { maxOutputTokens: 250, temperature: 0, responseMimeType: 'application/json' },
  });
  const call = async (model) => {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
    let r = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body });
    if (!r.ok && (r.status === 429 || r.status >= 500)) { await new Promise(s => setTimeout(s, 2000)); r = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body }); }
    return r;
  };
  // Candidate order: explicit override → cached working model → fallback list.
  const tried = new Set();
  const candidates = [process.env.GEMINI_MODEL, _geminiModel, ..._GEMINI_CANDIDATES].filter(Boolean);
  for (const model of candidates) {
    if (tried.has(model)) continue; tried.add(model);
    let r;
    try { r = await call(model); } catch { continue; }
    if (r.ok) {
      if (_geminiModel !== model) { _geminiModel = model; console.log(`[enrich] Gemini using model: ${model}`); }
      const j = await r.json();
      const u = j?.usageMetadata || {};
      const cost = ((u.promptTokenCount || 0) * 0.10 + (u.candidatesTokenCount || 0) * 0.40) / 1_000_000;
      const tokens = (u.promptTokenCount || 0) + (u.candidatesTokenCount || 0);
      const text = (j?.candidates?.[0]?.content?.parts?.[0]?.text || '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
      return { text, cost, tokens };
    }
    // 404 = wrong/retired model name → try the next candidate. Other 4xx (bad key,
    // quota) won't be fixed by another model, so stop.
    if (r.status !== 404) {
      if (!_geminiErrLogged) { const b = await r.text().catch(() => ''); console.error(`[enrich] Gemini ${r.status} (model ${model}): ${b.slice(0, 160)}`); }
      return null;
    }
  }
  return null; // every candidate 404'd
}

async function enrichDomainFromWeb(domain, companyName, fields) {
  const cleanDomain = domain.replace(/^https?:\/\//i, '').replace(/\/.*$/, '').trim();
  const wantFields = [];
  if (fields.includes('industry'))      wantFields.push('"industry": single category e.g. "Software", "Healthcare", "Financial Services"');
  if (fields.includes('keywords'))      wantFields.push('"keywords": 5-10 comma-separated descriptive keywords about what the company does');
  if (fields.includes('num_employees')) wantFields.push('"num_employees": integer employee count estimate or null');
  const systemPrompt = 'You are a company data extractor. Use your knowledge to identify company data from the domain and name. Return only valid JSON, no explanation or markdown.';

  try {
    // CH-only fast path: a SIC/Companies-House-only backfill needs no AI at all.
    // Skip the model call entirely and just return CH data (free + faster).
    if (wantFields.length === 0) {
      const ch = await fetchCompaniesHouse(companyName);
      if (!ch) return null;
      const data = {};
      if (ch.company_status) data.company_status = ch.company_status;
      data.ch_company_number   = ch.ch_company_number;
      data.ch_company_type     = ch.ch_company_type;
      data.ch_founded_year     = ch.ch_founded_year;
      data.ch_postcode         = ch.ch_postcode;
      data.ch_sic_codes        = ch.ch_sic_codes;
      data.ch_jurisdiction     = ch.ch_jurisdiction;
      data.ch_has_insolvency   = ch.ch_has_insolvency;
      data.ch_has_charges      = ch.ch_has_charges;
      data.ch_accounts_overdue = ch.ch_accounts_overdue;
      data.ch_active_officers  = ch.ch_active_officers;
      data.ch_data             = ch.ch_data;
      return { data, cost: 0, tokens: 0 };
    }

    // Provider selection: prefer Gemini when GEMINI_API_KEY is set (cheaper for
    // this bulk task), else fall back to Claude. Either works; the prompt and
    // JSON-shape are identical so downstream parsing is unchanged.
    const geminiKey = process.env.GEMINI_API_KEY;
    const anthropicKey = process.env.ANTHROPIC_API_KEY;
    const useGemini = !!geminiKey;
    if (!geminiKey && !anthropicKey) return null;

    // Only hit Companies House when this domain actually needs CH data. A domain
    // selected purely for missing keywords (SIC already present) must NOT burn a
    // CH call — CH is throttled to 2.5/sec and is the whole job's bottleneck.
    const needsCH = fields.includes('ch_sic') || fields.includes('company_status');
    const ch = needsCH
      ? await Promise.race([fetchCompaniesHouse(companyName), new Promise(res => setTimeout(() => res(null), 12000))])
      : null;

    const userPrompt = `Company: ${companyName || cleanDomain}\nDomain: ${cleanDomain}${ch?.sic ? `\nCompanies House SIC: ${ch.sic}` : ''}${ch?.accounts_type ? `\nAccounts type: ${ch.accounts_type}` : ''}\nExtract: ${wantFields.join('; ')}.\n\nReturn JSON only: {"industry":null,"keywords":null,"num_employees":null}`;

    // The AI call is BEST-EFFORT: if it fails (model retired, rate limit, outage),
    // we must NOT discard the Companies House data — SIC backfill has to survive an
    // AI outage. A failed AI call just leaves the AI fields empty.
    let text = '', cost = 0, tokens = 0;
    try {
      if (useGemini) {
        const r = await geminiGenerate(geminiKey, systemPrompt, userPrompt);
        if (r) {
          cost = r.cost; tokens = r.tokens; text = r.text;
        } else if (!_geminiErrLogged) {
          console.error('[enrich] Gemini unavailable (all candidate models failed) — continuing with Companies House data only'); _geminiErrLogged = true;
        }
      } else {
        const model = process.env.ANTHROPIC_MODEL || 'claude-haiku-4-5-20251001';
        const claudeReq = () => fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: { 'content-type': 'application/json', 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'prompt-caching-2024-07-31' },
          body: JSON.stringify({ model, max_tokens: 250, system: [{ type: 'text', text: systemPrompt, cache_control: { type: 'ephemeral' } }], messages: [{ role: 'user', content: userPrompt }] }),
        });
        let r = await claudeReq();
        if (!r.ok && (r.status === 429 || r.status >= 500)) {
          await new Promise(res => setTimeout(res, 2000));
          r = await claudeReq();
        }
        if (r.ok) {
          const j = await r.json();
          const u = j?.usage || {};
          cost = (
            ((u.input_tokens || 0) * HAIKU_PRICE.input +
             (u.output_tokens || 0) * HAIKU_PRICE.output +
             (u.cache_creation_input_tokens || 0) * HAIKU_PRICE.cache_write +
             (u.cache_read_input_tokens || 0) * HAIKU_PRICE.cache_read) / 1_000_000
          );
          tokens = (u.input_tokens || 0) + (u.output_tokens || 0) + (u.cache_read_input_tokens || 0);
          text = (j?.content?.[0]?.text || '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
        }
      }
    } catch (e) {
      if (!_geminiErrLogged) { console.error(`[enrich] AI call failed: ${e.message} — continuing with Companies House data only`); _geminiErrLogged = true; }
    }
    // Parse AI JSON if we got any; tolerate failure (CH data still returned below).
    let data = {};
    if (text) { try { data = JSON.parse(text) || {}; } catch {} }

    // If neither AI nor CH produced anything, there's nothing to write.
    if (!ch && !Object.keys(data).length) return null;

    // Fill gaps with Companies House data directly
    if (ch) {
      if (!data.num_employees && ch.num_employees) data.num_employees  = ch.num_employees;
      if (!data.city    && ch.city)               data.city            = ch.city;
      if (!data.country && ch.country)            data.country         = ch.country;
      if (ch.company_status)                      data.company_status  = ch.company_status;
      // Store all CH fields regardless
      data.ch_company_number   = ch.ch_company_number;
      data.ch_company_type     = ch.ch_company_type;
      data.ch_founded_year     = ch.ch_founded_year;
      data.ch_postcode         = ch.ch_postcode;
      data.ch_sic_codes        = ch.ch_sic_codes;
      data.ch_jurisdiction     = ch.ch_jurisdiction;
      data.ch_has_insolvency   = ch.ch_has_insolvency;
      data.ch_has_charges      = ch.ch_has_charges;
      data.ch_accounts_overdue = ch.ch_accounts_overdue;
      data.ch_active_officers  = ch.ch_active_officers;
      data.ch_data             = ch.ch_data;
    }

    return { data, cost, tokens };
  } catch { return null; }
}

let _activeEnrichJob = null; // in-memory reference to kill running jobs
let _enrichGeneration = 0;  // increment to kill any previous loop

async function saveEnrichJob(pgdb, job) {
  const { domains, ...rest } = job;
  await pgdb.query(`INSERT INTO _enrich_job (id, state) VALUES (1, $1) ON CONFLICT (id) DO UPDATE SET state = $1, updated_at = NOW()`,
    [JSON.stringify({ ...rest, domainCount: domains?.length })]);
}

async function loadEnrichJob(pgdb) {
  try {
    const { rows } = await pgdb.query(`SELECT state FROM _enrich_job WHERE id = 1`);
    return rows[0]?.state || null;
  } catch { return null; }
}

// Fetch a company homepage and extract location signals.
// Returns { postcodes, addressCandidates } where addressCandidates are
// plain-text address strings from <address> tags and <footer> content.
// Used as a location fallback when Apollo has no address for a domain.
async function fetchWebsiteLocationData(domain) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5000);
  try {
    const urls = [`https://${domain}`, `https://www.${domain}`];
    for (const url of urls) {
      try {
        const r = await fetch(url, {
          signal: controller.signal,
          headers: { 'User-Agent': 'Mozilla/5.0 (compatible; Ottaly/1.0)' },
          redirect: 'follow',
        });
        if (!r.ok) continue;
        const html = await r.text();
        clearTimeout(timer);

        // 1. Full UK postcodes (most reliable)
        const postcodes = [...new Set(
          (html.match(/\b[A-Z]{1,2}[0-9][A-Z0-9]?\s+[0-9][A-Z]{2}\b/gi) || [])
            .map(m => m.toUpperCase().replace(/\s+/, ' '))
        )];

        // 2. Address text from <address> tags and <footer> — fallback when no
        //    full postcode is found. Strip tags, collapse whitespace.
        const stripTags = s => s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        const addressBlocks = (html.match(/<address[^>]*>[\s\S]*?<\/address>/gi) || []).map(stripTags);
        const footerBlocks  = (html.match(/<footer[^>]*>[\s\S]*?<\/footer>/gi)  || []).map(stripTags);
        const addressCandidates = [...addressBlocks, ...footerBlocks].filter(s => s.length > 5);

        return { postcodes, addressCandidates };
      } catch { /* try next URL */ }
    }
  } finally {
    clearTimeout(timer);
  }
  return { postcodes: [], addressCandidates: [] };
}

async function processDomain(pgdb, job, domain, name, effectiveFields) {
  const t0 = Date.now();
  // Per-domain fields = only what THIS domain still needs (missing mode), or all
  // ticked fields (update-all mode). Falls back to job.fields for safety.
  const fields = (effectiveFields && effectiveFields.length) ? effectiveFields : (job.fields || []);
  // 'all' mode overwrites existing values; 'missing' (default) only fills blanks.
  const overwrite = job.mode === 'all';
  try {
    // CH calls are globally throttled (~2.5/sec) so under concurrency a domain
    // can sit in the queue a while before its CH lookups run. A tight 15s cap
    // was killing those waits → "no response". Give CH-involving jobs a generous
    // window; AI-only jobs keep a shorter one.
    const usesCH = fields.some(f => f === 'ch_sic' || f === 'company_status');
    const DOMAIN_DEADLINE = usesCH ? 90000 : 20000;
    const result = await Promise.race([
      enrichDomainFromWeb(domain, name, fields),
      new Promise((_, rej) => setTimeout(() => rej(new Error('domain timeout')), DOMAIN_DEADLINE)),
    ]);
    const ms = Date.now() - t0;
    job.domain_ms.push(ms);
    if (job.domain_ms.length > 20) job.domain_ms = job.domain_ms.slice(-20);

    const data = result?.data;
    job.total_cost   += result?.cost   || 0;
    job.total_tokens += result?.tokens || 0;

    if (data) {
      let updatedCount = 0;

      // ── Query 1: AI fields. 'missing' → COALESCE + only-blank rows.
      //    'all' → overwrite every contact on the domain. ────────────────────
      const claudeSet = [], claudeVals = [], missingConditions = [];
      const col = (name, expr, missCond) => { claudeSet.push(`${name} = ${expr}`); if (missCond) missingConditions.push(missCond); };
      if (fields.includes('keywords') && data.keywords)
        col('keywords', overwrite ? `$${claudeVals.push(String(data.keywords))}` : `COALESCE(NULLIF(keywords,''), $${claudeVals.push(String(data.keywords))})`, `(keywords IS NULL OR keywords = '')`);
      if (fields.includes('industry') && data.industry)
        col('industry', overwrite ? `$${claudeVals.push(String(data.industry))}` : `COALESCE(NULLIF(industry,''), $${claudeVals.push(String(data.industry))})`, `(industry IS NULL OR industry = '')`);
      if (fields.includes('num_employees') && data.num_employees)
        { const n = parseInt(data.num_employees, 10); if (Number.isFinite(n)) col('num_employees', overwrite ? `$${claudeVals.push(n)}` : `COALESCE(num_employees, $${claudeVals.push(n)})`, `num_employees IS NULL`); }
      if (data.city)    claudeSet.push(`city = COALESCE(NULLIF(city,''), $${claudeVals.push(String(data.city))})`);
      if (data.country) claudeSet.push(`country = COALESCE(NULLIF(country,''), $${claudeVals.push(String(data.country))})`);
      if (claudeSet.length) {
        claudeVals.push(domain);
        // In overwrite mode, update all rows on the domain; else only blank ones.
        const whereExtra = (!overwrite && missingConditions.length) ? ` AND (${missingConditions.join(' OR ')})` : '';
        const r1 = await pgdb.query(`UPDATE contacts SET ${claudeSet.join(', ')}, updated_at = NOW() WHERE company_domain = $${claudeVals.length}${whereExtra}`, claudeVals);
        updatedCount += r1.rowCount || 0;
      }

      // ── Query 2: Companies House fields — always update all contacts ───────
      const chSet = [], chVals = [];
      if (data.company_status)              chSet.push(`company_status = $${chVals.push(String(data.company_status))}`);
      if (data.ch_company_number   != null) chSet.push(`ch_company_number = $${chVals.push(String(data.ch_company_number))}`);
      if (data.ch_company_type     != null) chSet.push(`ch_company_type = $${chVals.push(String(data.ch_company_type))}`);
      if (data.ch_founded_year     != null) chSet.push(`ch_founded_year = $${chVals.push(parseInt(data.ch_founded_year))}`);
      if (data.ch_postcode         != null) chSet.push(`ch_postcode = $${chVals.push(String(data.ch_postcode))}`);
      if (data.ch_sic_codes        != null) chSet.push(`ch_sic_codes = $${chVals.push(String(data.ch_sic_codes))}`);
      if (data.ch_jurisdiction     != null) chSet.push(`ch_jurisdiction = $${chVals.push(String(data.ch_jurisdiction))}`);
      if (data.ch_has_insolvency   != null) chSet.push(`ch_has_insolvency = $${chVals.push(Boolean(data.ch_has_insolvency))}`);
      if (data.ch_has_charges      != null) chSet.push(`ch_has_charges = $${chVals.push(Boolean(data.ch_has_charges))}`);
      if (data.ch_accounts_overdue != null) chSet.push(`ch_accounts_overdue = $${chVals.push(Boolean(data.ch_accounts_overdue))}`);
      if (data.ch_active_officers  != null) chSet.push(`ch_active_officers = $${chVals.push(parseInt(data.ch_active_officers))}`);
      if (data.ch_resigned_officers!= null) chSet.push(`ch_resigned_officers = $${chVals.push(parseInt(data.ch_resigned_officers))}`);
      if (data.ch_address          != null) chSet.push(`ch_address = $${chVals.push(String(data.ch_address))}`);
      if (data.ch_date_of_cessation!= null) chSet.push(`ch_date_of_cessation = $${chVals.push(String(data.ch_date_of_cessation))}`);
      if (data.ch_last_accounts_date!=null) chSet.push(`ch_last_accounts_date = $${chVals.push(String(data.ch_last_accounts_date))}`);
      if (data.ch_year_end_month   != null) chSet.push(`ch_year_end_month = $${chVals.push(parseInt(data.ch_year_end_month))}`);
      if (data.ch_data             != null) chSet.push(`ch_data = $${chVals.push(JSON.stringify(data.ch_data))}`);
      // Only write the CH update when CH actually returned data (chSet non-empty).
      // A keywords-only domain that skipped the CH call must NOT stamp enriched_at
      // or overwrite CH columns it never fetched.
      if (chSet.length) {
        chSet.push(`enriched_at = NOW()`);
        chVals.push(domain);
        const r2 = await pgdb.query(`UPDATE contacts SET ${chSet.join(', ')}, updated_at = NOW() WHERE company_domain = $${chVals.length}`, chVals);
        updatedCount = Math.max(updatedCount, r2.rowCount || 0);
      }

      // ── Query 3: Website address fallback — fills company_region for contacts
      // with no region. Fetches homepage, extracts full UK postcodes, maps via
      // geo-lookup. Single postcode → use it; multiple → flag for review.
      // Per spec: Companies House address NOT used (accountants' addresses).
      try {
        const { rows: [{ n: missing }] } = await pgdb.query(
          `SELECT COUNT(*) AS n FROM contacts WHERE company_domain = $1 AND (company_region IS NULL OR company_region = '')`,
          [domain]
        );
        if (parseInt(missing) > 0) {
          const { postcodes, addressCandidates } = await fetchWebsiteLocationData(domain);
          const geo        = require('./geo-lookup');
          const { normalize } = require('./location-normalizer');

          // Try to resolve a single unambiguous location from the website.
          // Priority: full postcode → address/footer text via normalizer.
          let resolvedLoc = null;
          let resolvedSource = 'website';

          if (postcodes.length === 1) {
            const area = geo.extractPostcodeArea(postcodes[0]);
            const loc  = area ? geo.lookupPostcodeArea(area) : null;
            if (loc) resolvedLoc = { region: loc.region, county: loc.county, town: loc.postTown };
          } else if (postcodes.length === 0 && addressCandidates.length > 0) {
            // No full postcode — try each address candidate through the normalizer.
            // Accept only if all candidates that resolve agree on the same region.
            const regions = new Set();
            let bestLoc = null;
            for (const candidate of addressCandidates.slice(0, 5)) {
              const r = normalize({ address: candidate });
              if (r.region) { regions.add(r.region); bestLoc = r; }
            }
            if (regions.size === 1 && bestLoc) {
              resolvedLoc = { region: bestLoc.region, county: bestLoc.county, town: bestLoc.town || bestLoc.city };
            }
          }

          if (resolvedLoc) {
            const r3 = await pgdb.query(`
              UPDATE contacts SET
                company_region = $1, company_county = $2, company_town = $3,
                location_source = $4, location_needs_review = false,
                location_normalized_at = NOW(), updated_at = NOW()
              WHERE company_domain = $5 AND (company_region IS NULL OR company_region = '')
            `, [resolvedLoc.region, resolvedLoc.county || null, resolvedLoc.town || null, resolvedSource, domain]);
            if (r3.rowCount > 0) {
              updatedCount = Math.max(updatedCount, r3.rowCount);
              job.log.push(`  ↳ location: ${resolvedLoc.region} via website`);
            }
          } else if (postcodes.length > 1) {
            await pgdb.query(`
              UPDATE contacts SET
                location_needs_review = true,
                location_review_reason = 'multiple_website_addresses',
                updated_at = NOW()
              WHERE company_domain = $1 AND (company_region IS NULL OR company_region = '')
            `, [domain]);
          }
        }
      } catch (locErr) {
        // Non-fatal — don't let website scraping break the main enrichment loop
      }

      if (claudeSet.length || chSet.length) {
        job.updated += updatedCount;
        job.log.push(`✓ ${domain} → ${claudeSet.length + chSet.length} field(s), ${updatedCount} contacts`);
        job.results.push({ domain, name:name||domain, status:'updated', contacts:updatedCount, industry:data.industry||null, keywords:data.keywords||null, num_employees:data.num_employees||null });
      } else {
        job.skipped++;
        job.log.push(`– ${domain} → no data found`);
        job.results.push({ domain, name:name||domain, status:'skipped', contacts:0, industry:null, keywords:null, num_employees:null });
      }
    } else {
      job.skipped++;
      job.log.push(`– ${domain} → no response`);
      job.results.push({ domain, name:name||domain, status:'failed', contacts:0, industry:null, keywords:null, num_employees:null });
    }
  } catch (err) {
    job.failed++;
    job.log.push(`✗ ${domain} → ${err.message}`);
  }
}

async function runEnrichment(pgdb, job) {
  if (!job || job.paused) return;
  _activeEnrichJob = job;
  const myGeneration = _enrichGeneration;
  job.total_cost   = job.total_cost   || 0;
  job.total_tokens = job.total_tokens || 0;
  job.domain_ms    = job.domain_ms    || [];
  const CONCURRENCY = job.concurrency || 5;

  // Build WHERE from fields — re-query from DB so we survive server restarts.
  // 'all' mode re-processes EVERY domain; 'missing' (default) only domains that
  // lack at least one ticked field. We also SELECT per-field missing flags so a
  // domain only does the work it actually needs (e.g. skip the CH call when SIC
  // is already present) — critical because CH is throttled to 2.5/sec.
  const jf = job.fields || [];
  const allMode = job.mode === 'all';
  const conditions = [];
  if (jf.includes('keywords'))       conditions.push(`(keywords IS NULL OR keywords = '')`);
  if (jf.includes('industry'))       conditions.push(`(industry IS NULL OR industry = '')`);
  if (jf.includes('num_employees'))  conditions.push(`num_employees IS NULL`);
  if (jf.includes('company_status')) conditions.push(`company_status IS NULL`);
  if (jf.includes('ch_sic'))         conditions.push(`(ch_sic_codes IS NULL OR ch_sic_codes = '')`);
  const whereConditions = allMode ? 'TRUE' : (conditions.join(' OR ') || 'TRUE');

  const { rows: allDomains } = await pgdb.query(`
    SELECT DISTINCT ON (company_domain) company_domain, company_name,
      (keywords IS NULL OR keywords = '')         AS need_keywords,
      (industry IS NULL OR industry = '')         AS need_industry,
      (num_employees IS NULL)                     AS need_employees,
      (ch_sic_codes IS NULL OR ch_sic_codes = '') AS need_ch
    FROM contacts
    WHERE company_domain IS NOT NULL AND company_domain != ''
      AND (${whereConditions})
    ORDER BY company_domain
  `);

  // Per-domain effective fields: in 'all' mode every ticked field; in 'missing'
  // mode only the ones this domain still lacks.
  const effFor = (r) => {
    if (allMode) return jf.slice();
    const f = [];
    if (jf.includes('keywords')      && r.need_keywords)  f.push('keywords');
    if (jf.includes('industry')      && r.need_industry)  f.push('industry');
    if (jf.includes('num_employees') && r.need_employees) f.push('num_employees');
    if (jf.includes('ch_sic')        && r.need_ch)        f.push('ch_sic');
    return f;
  };
  const todo = allDomains.slice(job.processed).map(r => ({ domain: r.company_domain, name: r.company_name, fields: effFor(r) }));
  console.log(`[enrich] pid=${process.pid} resuming at ${job.processed}/${allDomains.length} domains (concurrency=${CONCURRENCY}, mode=${allMode ? 'all' : 'missing'})`);

  for (let i = 0; i < todo.length; i += CONCURRENCY) {
    if (job.paused) break;
    if (_enrichGeneration !== myGeneration) break; // newer job started, stop this loop

    // Check paused state from DB every batch
    const fresh = await loadEnrichJob(pgdb).catch(() => null);
    if (fresh?.paused) { job.paused = true; break; }

    const batch = todo.slice(i, i + CONCURRENCY);
    job.current_domain = batch[0].domain;
    await saveEnrichJob(pgdb, job).catch(() => {});

    // Process batch with slight stagger to avoid Claude rate limits
    await Promise.all(batch.map(({ domain, name, fields }, i) =>
      new Promise(res => setTimeout(res, i * 200))
        .then(() => { if (job.paused) return; return processDomain(pgdb, job, domain, name, fields); })
        .then(async () => {
          job.processed++;
          if (job.log.length > 300)     job.log     = job.log.slice(-300);
          if (job.results.length > 200) job.results = job.results.slice(-200);
          await saveEnrichJob(pgdb, job).catch(() => {});
          // Check pause after each domain
          const fresh = await loadEnrichJob(pgdb).catch(() => null);
          if (fresh?.paused) job.paused = true;
        })
    ));
  }

  if (!job.paused) {
    job.status = 'completed'; job.current_domain = null;
    job.log.push(`✓ Done — ${job.updated} contacts updated, cost $${(job.total_cost||0).toFixed(4)}`);
    await saveEnrichJob(pgdb, job).catch(() => {});
  }
}

// ── AI Enrichment — state persisted in Postgres so all instances share it ──

async function enrichDbState(pgdb) {
  await pgdb.query(`CREATE TABLE IF NOT EXISTS _enrich_job (
    id INT PRIMARY KEY DEFAULT 1,
    state JSONB NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW()
  )`);
}

app.post('/api/admin/enrich/start', requireAdmin, async (req, res) => {
  const { fields = ['keywords', 'industry', 'num_employees'], limit = 0, concurrency = 5, mode = 'missing' } = req.body;
  const pgdb = req.app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'Database not available' });

  // CH-derived fields (incl. SIC backfill) are useless without a CH key — fail
  // loudly rather than churn through the whole DB returning "no response".
  if ((fields.includes('ch_sic') || fields.includes('company_status')) && !process.env.COMPANIES_HOUSE_API_KEY) {
    return res.status(400).json({ error: 'COMPANIES_HOUSE_API_KEY is not set — SIC / Companies House backfill cannot run. Add it to the server env first.' });
  }

  await enrichDbState(pgdb);
  // Kill any in-memory running job before starting fresh
  _enrichGeneration++;
  _geminiErrLogged = false; // fresh run → allow one AI-error log again
  if (_activeEnrichJob) {
    _activeEnrichJob.paused = true;
    _activeEnrichJob.status = 'stopped';
    _activeEnrichJob = null;
  }

  const allMode = mode === 'all';
  const conditions = [];
  if (fields.includes('keywords'))      conditions.push(`(keywords IS NULL OR keywords = '')`);
  if (fields.includes('industry'))      conditions.push(`(industry IS NULL OR industry = '')`);
  if (fields.includes('num_employees')) conditions.push(`num_employees IS NULL`);
  // SIC/Companies House backfill — finds rows that never got CH data (e.g. they
  // already had keywords so the keyword scan skipped them). CH fills ch_sic_codes
  // as a side-effect, so requesting this field re-runs CH on SIC-less rows.
  if (fields.includes('ch_sic'))        conditions.push(`(ch_sic_codes IS NULL OR ch_sic_codes = '')`);
  if (conditions.length === 0) return res.status(400).json({ error: 'No fields selected' });
  // 'all' mode re-processes every domain regardless of current state.
  const whereConditions = allMode ? 'TRUE' : conditions.join(' OR ');

  const limitClause = limit > 0 ? `LIMIT ${parseInt(limit, 10)}` : '';
  const { rows } = await pgdb.query(`
    SELECT DISTINCT ON (company_domain) company_domain, company_name
    FROM contacts
    WHERE company_domain IS NOT NULL AND company_domain != ''
      AND (${whereConditions})
    ORDER BY company_domain
    ${limitClause}
  `);

  const job = {
    status: 'running', fields, mode: allMode ? 'all' : 'missing',
    concurrency: Math.min(Math.max(parseInt(concurrency)||5, 1), 10),
    total: rows.length, processed: 0, updated: 0, failed: 0, skipped: 0,
    current_domain: null, log: [], results: [], started_at: new Date().toISOString(),
    paused: false,
  };

  await saveEnrichJob(pgdb, job);
  res.json({ ok: true, total: job.total });
  runEnrichment(pgdb, job).catch(err => console.error('[enrich]', err.message));
});

app.get('/api/admin/enrich/scan', requireAdmin, async (req, res) => {
  const pgdb = req.app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'Database not available' });

  const fields = (req.query.fields || 'keywords,industry,num_employees').split(',').map(f => f.trim());
  const allMode = req.query.mode === 'all';
  const conditions = [];
  if (fields.includes('keywords'))      conditions.push(`(keywords IS NULL OR keywords = '')`);
  if (fields.includes('industry'))      conditions.push(`(industry IS NULL OR industry = '')`);
  if (fields.includes('num_employees')) conditions.push(`num_employees IS NULL`);
  if (fields.includes('company_status')) conditions.push(`company_status IS NULL`);
  if (fields.includes('ch_sic'))        conditions.push(`(ch_sic_codes IS NULL OR ch_sic_codes = '')`);
  // 'all' mode counts every domain (re-process regardless of current data).
  const whereConditions = allMode ? 'TRUE' : (conditions.join(' OR ') || 'TRUE');

  const { rows } = await pgdb.query(`
    SELECT
      COUNT(DISTINCT company_domain) AS domains,
      COUNT(*) AS contacts
    FROM contacts
    WHERE company_domain IS NOT NULL AND company_domain != ''
      AND (${whereConditions})
  `);

  const domains = parseInt(rows[0].domains, 10);
  const contacts = parseInt(rows[0].contacts, 10);
  const cost_usd = +(domains * 0.00002).toFixed(4);

  res.json({ domains, contacts, cost_usd });
});

