// Liveness/readiness probe for Easypanel/uptime monitoring. No auth — 200 when
// the process is up and Postgres answers SELECT 1, else 503.
// Deploy marker — answers "is my fix actually live?" in one request.
//
// This used to be a hand-maintained string, which meant it drifted: it still
// read 'apollo-export-fix-2026-07-08e' weeks later, so it confirmed nothing.
// GIT_COMMIT/BUILT_AT are injected at BUILD time (see Dockerfile), so they
// cannot drift and cannot be forgotten.
//
// Why this matters: EasyPanel has been observed reporting a "successful" build
// that finished in ONE SECOND and shipped no new code. Debugging behaviour
// without first checking this wastes entire sessions -- it did exactly that on
// 2026-08-21. Compare against `git rev-parse --short HEAD` BEFORE diagnosing
// anything; if they differ, the fix is not running and there is nothing to
// debug. No auth, so it works from anywhere.
app.get('/api/version', (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.json({
    commit: process.env.GIT_COMMIT || 'unknown',
    builtAt: process.env.BUILT_AT || 'unknown',
    uptime: Math.round(process.uptime()),
  });
});

// Event-loop lag sampler. A timer set for 500ms that measures how late it
// actually fires: if the loop is blocked, the delay is the block duration.
// Records the WORST lag since the last /healthz read, not the instantaneous
// value -- an instantaneous reading is always ~0 by the time the loop is free
// enough to serve /healthz, which is exactly when we can observe it.
let _elLagMax = 0;
{
  const TICK = 500;
  let expected = Date.now() + TICK;
  setInterval(() => {
    const now = Date.now();
    const late = now - expected;
    if (late > _elLagMax) _elLagMax = late;
    expected = now + TICK;
  }, TICK).unref?.();
}

app.get('/healthz', async (req, res) => {
  res.set('Cache-Control', 'no-store');
  // commit is here as well as /api/version because this is the endpoint that
  // actually gets polled during an incident. Seeing the running commit next to
  // the symptoms is what prevents diagnosing a build that was never deployed.
  const health = {
    status: 'ok',
    commit: process.env.GIT_COMMIT || 'unknown',
    uptime: Math.round(process.uptime()),
    db: 'unknown',
  };
  // Rejections survived rather than killed the process. A rising count with a
  // flat uptime means background jobs are failing quietly; a reset to 0 with a
  // low uptime means the process restarted.
  try { health.unhandledRejections = req.app.locals.getCrashCount?.() ?? null; } catch (_) {}
  // Configured heap ceiling, so an OOM can be told from a crash after the fact.
  try { health.heapLimitMB = Math.round(require('v8').getHeapStatistics().heap_size_limit / 1048576); } catch (_) {}
  try {
    const pgPool = req.app.locals.pgDb;
    if (pgPool && typeof pgPool.query === 'function') {
      // Pool saturation is what made ordinary pages look like database faults:
      // a bare SELECT 1 measured 4.4-11.4s in production purely from waiting
      // for a free connection. Expose both pools so that is visible directly
      // instead of being inferred from endpoint latency.
      // waiting > 0 on web = users are queueing for a connection.
      const stat = (pool) => pool
        ? { total: pool.totalCount, idle: pool.idleCount, waiting: pool.waitingCount }
        : null;
      health.pools = { web: stat(pgPool.pool), background: stat(pgPool.bgPool) };
      // Heap + event-loop lag. The site stalls with TLS completing and zero
      // bytes returned while DB latency stays at 1-10ms, which points at the
      // event loop rather than the database. rss near the container limit with
      // heapUsed pinned high means GC thrashing; lag alone means sync work.
      const m = process.memoryUsage();
      const mb = (n) => Math.round(n / 1048576);
      health.memory = { rssMB: mb(m.rss), heapUsedMB: mb(m.heapUsed), heapTotalMB: mb(m.heapTotal) };
      // Worst block since the previous healthz call, then reset.
      health.eventLoopLagMaxMs = Math.max(0, Math.round(_elLagMax));
      _elLagMax = 0;
      const t0 = Date.now();
      await pgPool.query('SELECT 1');
      health.dbLatencyMs = Date.now() - t0;
      // Verification backlog. `due` climbing while `total` never falls means
      // the verifier is down and work is being deferred (not lost); both
      // dropping to 0 means the backlog drained on its own.
      try {
        if (pgPool.verificationQueueStats) health.verifyQueue = await pgPool.verificationQueueStats();
      } catch (_) { /* never let health reporting fail the probe */ }
      health.db = 'ok';
    } else {
      health.db = 'unconfigured';
    }
    res.json(health);
  } catch (err) {
    health.status = 'degraded';
    health.db = 'error';
    health.error = err.message;
    res.status(503).json(health);
  }
});

