// ── Revenue leads cache (refreshed every 3 min server-side) ──
const LEAD_LABELS = ['LEAD', 'MEETING_BOOKED', 'MEETING_COMPLETED', 'CLOSED', 'ADDED_TO_ZOHO', 'AWAITING_REPLY', 'NON_LEAD', 'WEAK_LEAD'];
const NON_LEAD_LABEL_RE = /(^|[_\-\s])non([_\-\s]?lead)?([_\-\s]|$)/i;
const REVENUE_EXCLUDED_WORKSPACE_IDS = new Set([
  '690ee665bcb253de4fb44538', // Ottaly
  '69ce40f616a9cc965746b1a6', // Ottaly Test Account
]);
let revenueCache = { leads: [], updatedAt: null };

// pvFetch shim — legacy callers that do pvFetch('/workspaces') or pvFetch('/...') still work.
// /workspaces → listPvWorkspaces(); everything else → pvApi().
pvFetch = async function pvFetch(path, _retries, opts) {
  opts = opts || {};
  if (path === '/workspaces') return listPvWorkspaces();
  // Strip leading /api if present (pvApi prepends nothing — path must start with /)
  const apiPath = path.startsWith('/api') ? path.slice(4) : path;
  return pvApi(apiPath, { method: opts.method || 'GET', body: opts.body });
};

// bisonSwitch stub — Bison removed, prevents ReferenceErrors in dead code paths.
async function bisonSwitch(_wsId) {
  console.warn('[bisonSwitch] STUB called — Bison removed');
}

// Build a { date: { total_*_count } } map from an email-stats response.
// PlusVibe /account/email-stats returns per-day rows ALREADY shaped as
// { date, total_sent_count, total_reply_count, ... } — pass those straight
// through. (Legacy Bison line-area-chart-stats returned label-series of
// { label, dates:[[date,count]] }; that branch is kept for any leftover
// diagnostic caller, but live stats are all PlusVibe per-date rows now.)
function pivotBisonStats(statsData) {
  var out = {};
  var rows = Array.isArray(statsData) ? statsData : (statsData && (statsData.chart || statsData.data)) || [];
  // Detect format: PV per-date rows carry total_*_count metrics (and a `date`);
  // Bison label-series rows carry a `dates` ARRAY. NOTE: PV rows ALSO have a
  // `label` (the human date e.g. "12 Jun 26"), so we must NOT key off label —
  // key off the presence of total_sent_count / absence of a dates[] array.
  var isPvRows = rows.length && rows[0] &&
    (rows[0].total_sent_count !== undefined || rows[0].total_reply_count !== undefined ||
     (rows[0].date != null && !Array.isArray(rows[0].dates)));
  if (isPvRows) {
    rows.forEach(function(row) {
      var date = String(row.date || row.day || '').slice(0, 10);
      if (!date) return;
      out[date] = {
        date: date,
        total_sent_count:      row.total_sent_count      || 0,
        total_reply_count:     row.total_reply_count     || 0,
        total_bounce_count:    row.total_bounce_count    || 0,
        total_open_count:      row.total_open_count      || 0,
        total_pos_reply_count: row.total_pos_reply_count || 0,
        total_ooo_reply_count: row.total_ooo_reply_count || 0,
        total_contacted_count: row.total_contacted_count || row.total_sent_count || 0,
      };
    });
    return out;
  }
  // Legacy Bison label-series format.
  var labelMap = { 'Sent': 'total_sent_count', 'Replied': 'total_reply_count', 'Bounced': 'total_bounce_count', 'Total Opens': 'total_open_count', 'Interested': 'total_pos_reply_count' };
  rows.forEach(function(series) {
    var field = labelMap[series.label];
    if (!field) return;
    (series.dates || []).forEach(function(pair) {
      var date = pair[0], count = pair[1];
      if (!out[date]) out[date] = { date: date, total_sent_count: 0, total_reply_count: 0, total_bounce_count: 0, total_open_count: 0, total_pos_reply_count: 0, total_ooo_reply_count: 0, total_contacted_count: 0 };
      out[date][field] = count;
    });
  });
  return out;
}

function normalizePvLabel(label) {
  return String(label || '').trim().replace(/\s+/g, '_').toUpperCase();
}

function isPvNonLeadLabel(label) {
  return NON_LEAD_LABEL_RE.test(String(label || ''));
}

function isRevenueExcludedWorkspace(value = {}) {
  const workspaceId = String(value.workspace_id || value.id || '').trim();
  const workspaceName = String(value.workspace_name || value.name || value.client_name || '').trim().toLowerCase();
  return REVENUE_EXCLUDED_WORKSPACE_IDS.has(workspaceId) || workspaceName === 'ottaly' || workspaceName.startsWith('ottaly ');
}

function stableLeadKey(workspaceId, lead) {
  return String(lead?._id || lead?.id || lead?.lead_id || `${workspaceId}:${(lead?.email || '').toLowerCase()}`);
}

function sourceLeadDate(lead) {
  return lead?.modified_at || lead?.created_at || lead?.createdAt || lead?.lead_created_at || lead?.added_at || lead?.date || null;
}

function getStableRevenueLeadDate(workspaceId, leadKey, email, sourceDate) {
  const existing = db.prepare('SELECT first_seen FROM revenue_lead_first_seen WHERE lead_key = ?').get(leadKey);
  // If PlusVibe gave us a source date (modified_at = when label was applied)
  // and it's older than what we have stored, the stored value is a stale
  // "we first saw this today" record from before we extracted modified_at.
  // Correct it so 90-day windows aren't flooded with historical leads.
  if (existing?.first_seen) {
    if (sourceDate) {
      const src = new Date(sourceDate).getTime();
      const cur = new Date(existing.first_seen).getTime();
      if (Number.isFinite(src) && Number.isFinite(cur) && src < cur) {
        db.prepare(`UPDATE revenue_lead_first_seen SET first_seen = ? WHERE lead_key = ?`)
          .run(sourceDate, leadKey);
        return sourceDate;
      }
    }
    return existing.first_seen;
  }
  const fallback = sourceDate || new Date().toISOString();
  db.prepare(`
    INSERT OR IGNORE INTO revenue_lead_first_seen (lead_key, workspace_id, email, first_seen)
    VALUES (?, ?, ?, ?)
  `).run(leadKey, workspaceId, email || '', fallback);
  return db.prepare('SELECT first_seen FROM revenue_lead_first_seen WHERE lead_key = ?').get(leadKey)?.first_seen || fallback;
}

// One-shot: wipe revenue_lead_first_seen rows where first_seen is unrealistically
// recent given when the lead was actually labeled. The next refresh will rebuild
// them with correct dates from PV's modified_at. Runs once on boot.
let _firstSeenResetDone = false;
function resetStaleFirstSeenOnce() {
  if (_firstSeenResetDone) return;
  _firstSeenResetDone = true;
  try {
    // If 90%+ of records share the same first_seen date, they were almost
    // certainly written as a batch when modified_at wasn't being read.
    const all = db.prepare('SELECT first_seen FROM revenue_lead_first_seen').all();
    if (!all.length) return;
    const dayCounts = {};
    all.forEach(r => {
      const day = String(r.first_seen).slice(0, 10);
      dayCounts[day] = (dayCounts[day] || 0) + 1;
    });
    const topDay = Object.entries(dayCounts).sort((a,b) => b[1] - a[1])[0];
    if (topDay[1] > all.length * 0.5) {
      // More than half the leads share one calendar day — clearly stale batch.
      const r = db.prepare(`DELETE FROM revenue_lead_first_seen WHERE first_seen LIKE ?`).run(topDay[0] + '%');
      console.log(`[revenue cache] reset ${r.changes} stale first_seen records all dated ${topDay[0]} — will rebuild with PV modified_at on next refresh`);
    }
  } catch (err) {
    console.warn('[revenue cache] reset stale first_seen failed:', err.message);
  }
}

// Turn portal-marked leads into revenue_leads rows. The client portal records a
// "mark as lead" by setting unibox_replies.marked_as_lead=true (with marked_at/
// marked_by). admin-legacy is the billing source of truth (revenue_leads), but had
// NO path to write new leads — so leads marked in the portal never appeared on the
// dashboard after the one-time 06-12 backfill. This reconciler upserts one
// revenue_leads row per marked reply, idempotently (lead_key = portal:<reply id>),
// priced at the client's CURRENT price_per_lead. Runs just before each revenue
// cache refresh so new leads show within the 3-min cycle. Returns count upserted.
async function reconcilePortalMarkedLeads() {
  const pgdb = app.locals?.pgDb;
  if (!pgdb) return 0;
  try {
    const { rows } = await pgdb.query(
      `SELECT id, workspace_id, bison_team_id, lead_email, matched_lead_email, subject,
              campaign_id, marked_at, received_at
         FROM unibox_replies
        WHERE marked_as_lead = true`
    );
    if (!rows.length) return 0;
    // Current per-client prices + names, keyed by canonical workspace_id.
    const clientRows = db.prepare(
      'SELECT workspace_id, workspace_name, price_per_lead, client_status FROM clients'
    ).all();
    const priceByCanon = {}, nameByCanon = {}, statusByCanon = {};
    for (const c of clientRows) {
      const canon = canonicalWorkspaceId(c.workspace_id, c.workspace_name);
      priceByCanon[canon]  = c.price_per_lead || 0;
      nameByCanon[canon]   = c.workspace_name || '';
      statusByCanon[canon] = c.client_status || 'active';
    }
    const leads = [];
    for (const r of rows) {
      // Resolve to canonical id (reply may store the Bison team_id or a mismatched id).
      const canon = canonicalWorkspaceId(r.workspace_id || r.bison_team_id, null);
      if (statusByCanon[canon] === 'inactive') continue;
      const email = (r.matched_lead_email || r.lead_email || '').toLowerCase();
      if (!email || email.includes('demo.example')) continue; // skip test rows
      const when = (r.marked_at || r.received_at);
      const dateStr = when ? new Date(when).toISOString().slice(0, 10) : '';
      leads.push({
        lead_key:       `portal:${r.id}`,           // stable & unique per marked reply
        workspace_id:   canon,
        workspace_name: nameByCanon[canon] || '',
        client_name:    nameByCanon[canon] || '',
        lead_email:     email,
        first_name:     '',
        last_name:      '',
        campaign:       r.campaign_id || '',
        lead_price:     priceByCanon[canon] || 0,
        date:           dateStr,
        label:          'LEAD',
        pv_nonlead:     false,
      });
    }
    if (!leads.length) return 0;
    const n = await pgdb.upsertRevenueLeads(leads);
    return n;
  } catch (e) {
    console.warn('[revenue] portal lead reconcile failed:', e.message);
    return 0;
  }
}

async function refreshRevenueCache() {
  resetStaleFirstSeenOnce();
  try {
    // Pull any portal-marked leads into revenue_leads BEFORE reading the table,
    // so leads marked in the portal show up on this same refresh.
    const reconciled = await reconcilePortalMarkedLeads();
    if (reconciled) console.log(`[revenue] reconciled ${reconciled} portal-marked lead(s) into revenue_leads`);
    // REVENUE = FROZEN STORAGE ONLY. The historical lead/revenue data lives in
    // the revenue_leads table (Postgres). We do NOT live-fetch leads from Bison
    // here: Bison leads have different IDs than the stored PlusVibe-era leads, so
    // merging them would double-count the same person and inflate revenue. New
    // leads enter revenue_leads via the reply webhook going forward. This keeps
    // the historical figure exact and stable. (Decision: 2026-06-14.)
    const pgdb = app.locals?.pgDb;
    const prices = db.prepare('SELECT workspace_id, workspace_name, price_per_lead, client_status FROM clients').all();
    const priceMap = {};
    const statusMap = {};
    const nameMap = {};
    prices.forEach(p => {
      priceMap[p.workspace_id]  = p.price_per_lead || 0;
      statusMap[p.workspace_id] = p.client_status || 'active';
      nameMap[p.workspace_id]   = p.workspace_name || '';
    });

    const leads = [];
    if (pgdb) {
      try {
        // Empty set → all stored leads (the method returns everything when the
        // live set is empty). This IS the revenue dataset now.
        const storedRows = await pgdb.getDeletedWorkspaceLeads(new Set());
        for (const row of storedRows) {
          if (isRevenueExcludedWorkspace({ id: row.workspace_id, name: row.client_name || row.workspace_name })) continue;
          leads.push({
            lead_key:        row.lead_key,
            client_name:     nameMap[row.workspace_id] || row.client_name || row.workspace_name || row.workspace_id,
            workspace_id:    row.workspace_id,
            campaign:        row.campaign    || '',
            first_name:      row.first_name  || '',
            last_name:       row.last_name   || '',
            lead_email:      row.lead_email  || '',
            // Use the current client price if set (>0), else the price stored with
            // the lead. `||` (not `??`) so a 0/missing client price — e.g. a client
            // not in the hardcoded price list — falls back to the stored lead_price
            // instead of zeroing the lead's revenue.
            lead_price:      (priceMap[row.workspace_id] || Number(row.lead_price)) || 0,
            label:           row.label       || '',
            date:            row.date        || '',
            client_inactive: statusMap[row.workspace_id] === 'inactive',
            pv_nonlead:      Boolean(row.pv_nonlead),
          });
        }
      } catch (err) {
        console.warn('[revenue cache] load from storage failed:', err.message);
      }
    }

    // Attach each lead's TRUE recipient provider (contacts.mx_provider) so the
    // Stats provider tabs count leads by their ACTUAL provider, not an estimate
    // apportioned from the send ratio. One batched lookup, keyed by lower(email).
    if (pgdb && leads.length) {
      try {
        const emails = [...new Set(leads.map(l => (l.lead_email || '').toLowerCase()).filter(Boolean))];
        if (emails.length) {
          const r = await pgdb.query(
            `SELECT DISTINCT ON (lower(email)) lower(email) AS email, mx_provider
             FROM contacts WHERE lower(email) = ANY($1) AND mx_provider IS NOT NULL
             ORDER BY lower(email)`,
            [emails]
          );
          const provByEmail = Object.fromEntries(r.rows.map(x => [x.email, x.mx_provider]));
          for (const l of leads) l.mx_provider = provByEmail[(l.lead_email || '').toLowerCase()] || null;
        }
      } catch (err) {
        console.warn('[revenue cache] provider attach failed:', err.message);
      }
    }

    revenueCache = { leads, updatedAt: new Date().toISOString() };
    console.log(`[revenue cache] refreshed — ${leads.length} total leads (from storage)`);

    // Lead counts in workspace_stats come from revenueCache — recompute so
    // Capacity / Audience / Health show the latest numbers right away.
    if (typeof refreshAllWorkspaceStats === 'function') {
      refreshAllWorkspaceStats().catch(() => {});
    }
  } catch (err) {
    console.error('[revenue cache] refresh failed:', err.message);
  }
}

// Refresh on startup then every 3 minutes
setTimeout(refreshRevenueCache, 5000); // slight delay so server is fully up first
setInterval(refreshRevenueCache, 3 * 60 * 1000);

// GBP→ZAR rate cached server-side — browser calls this instead of hitting frankfurter directly
let _zarRateCache = { rate: null, fetchedAt: 0 };
app.get('/api/gbp-zar-rate', requireSession, async (req, res) => {
  const now = Date.now();
  if (_zarRateCache.rate && now - _zarRateCache.fetchedAt < 30 * 60 * 1000) {
    return res.json({ rate: _zarRateCache.rate, source: 'cache' });
  }
  try {
    const controller = new AbortController();
    const t = setTimeout(() => controller.abort(), 5000);
    const r = await fetch('https://api.frankfurter.app/latest?from=GBP&to=ZAR', { signal: controller.signal });
    clearTimeout(t);
    const d = await r.json();
    const rate = d?.rates?.ZAR;
    if (rate && rate > 0) { _zarRateCache = { rate, fetchedAt: now }; return res.json({ rate, source: 'live' }); }
  } catch {}
  res.json({ rate: _zarRateCache.rate || 23.5, source: 'fallback' });
});

// All-time average lead price — drives CM per-lead bonus (uses total history, not just last month)
app.get('/api/avg-lead-price', requireSession, (req, res) => {
  const overrides = db.prepare('SELECT email, active FROM nonlead_overrides').all();
  const nonleadMap = {};
  overrides.forEach(o => { nonleadMap[o.email.toLowerCase()] = o; });

  const livePrices = db.prepare('SELECT workspace_id, price_per_lead FROM clients').all();
  const livePriceMap = {};
  livePrices.forEach(p => { livePriceMap[p.workspace_id] = p.price_per_lead || 0; });

  // All leads (no date filter) — all-time average
  const leads = (revenueCache.leads || []).filter(l => {
    if (isRevenueExcludedWorkspace(l)) return false;
    const override  = nonleadMap[(l.lead_email || '').toLowerCase()];
    const pvNonlead = Boolean(l.pv_nonlead || isPvNonLeadLabel(l.label));
    return !(override?.active || pvNonlead);
  });

  const totalRevenue = leads.reduce((s, l) => s + ((livePriceMap[l.workspace_id] || l.lead_price) || 0), 0);
  const totalLeads   = leads.length;
  const avg          = totalLeads > 0 ? totalRevenue / totalLeads : 0;

  // Managers need avg_lead_price_gbp for commission, but must NOT see
  // agency-wide revenue totals (policy: managers ≠ Revenue/Finance). Strip the
  // aggregate figures for non-admins; commission.html only reads avg_lead_price_gbp.
  const isAdmin = decodeSession(req)?.role === 'admin';
  const payload = { avg_lead_price_gbp: parseFloat(avg.toFixed(2)), period: 'all-time' };
  if (isAdmin) {
    payload.total_leads = totalLeads;
    payload.total_revenue = parseFloat(totalRevenue.toFixed(2));
  }
  res.json(payload);
});

app.get('/api/revenue/leads', requireSession, (req, res) => {
  // Apply non-lead overrides from SQLite
  const overrides = db.prepare(`SELECT email, reason, marked_at, active FROM nonlead_overrides`).all();
  const nonleadMap = {};
  overrides.forEach(o => { nonleadMap[o.email.toLowerCase()] = o; });

  // Always use current price from DB — never trust cached lead_price
  const currentPrices = db.prepare('SELECT workspace_id, price_per_lead FROM clients').all();
  const livePriceMap = {};
  currentPrices.forEach(p => { livePriceMap[p.workspace_id] = p.price_per_lead || 0; });

  const leads = (revenueCache.leads || []).filter(l => !isRevenueExcludedWorkspace(l)).map(l => {
    const o        = nonleadMap[(l.lead_email || '').toLowerCase()];
    const livePrice = (livePriceMap[l.workspace_id] || l.lead_price) || 0;
    const pvNonlead = Boolean(l.pv_nonlead || isPvNonLeadLabel(l.label));
    return {
      ...l,
      lead_price:     livePrice,
      is_nonlead:     o?.active || pvNonlead ? true : false,
      nonlead_reason: o?.active ? o.reason : (pvNonlead ? 'PlusVibe label: Non Lead' : ''),
      nonlead_date:   o?.active ? o.marked_at : (pvNonlead ? l.date : ''),
    };
  });
  res.json({ ...revenueCache, leads });
});

// Mark lead as non-lead
app.post('/api/nonlead/mark', (req, res) => {
  const { email, reason } = req.body || {};
  if (!email) return res.status(400).json({ error: 'Missing email' });
  db.prepare(`INSERT INTO nonlead_overrides (email, reason, active) VALUES (?, ?, 1)
    ON CONFLICT(email) DO UPDATE SET reason=excluded.reason, marked_at=datetime('now'), active=1`)
    .run(email.toLowerCase(), reason || '');
  res.json({ ok: true });
});

// Restore lead to active
app.post('/api/nonlead/restore', (req, res) => {
  const { email } = req.body || {};
  if (!email) return res.status(400).json({ error: 'Missing email' });
  db.prepare(`UPDATE nonlead_overrides SET active=0 WHERE email=?`).run(email.toLowerCase());
  res.json({ ok: true });
});

app.get('/api/revenue/stats-by-workspace', requireAdmin, (req, res) => {
  // Always use current price from DB so changing a price reflects immediately
  const currentPrices = db.prepare('SELECT workspace_id, price_per_lead FROM clients').all();
  const livePriceMap  = {};
  currentPrices.forEach(p => { livePriceMap[p.workspace_id] = p.price_per_lead || 0; });
  const manualNonleads = new Set(
    db.prepare(`SELECT email FROM nonlead_overrides WHERE active = 1`).all()
      .map(r => String(r.email || '').toLowerCase())
  );

  const counts = {};
  (revenueCache.leads || []).forEach(l => {
    if (isRevenueExcludedWorkspace(l)) return;
    if (manualNonleads.has(String(l.lead_email || '').toLowerCase())) return;
    if (l.pv_nonlead || isPvNonLeadLabel(l.label)) return;
    if (!counts[l.workspace_id]) counts[l.workspace_id] = { delivered: 0, revenue: 0 };
    counts[l.workspace_id].delivered++;
    counts[l.workspace_id].revenue += (livePriceMap[l.workspace_id] || l.lead_price) || 0;
  });
  res.json(counts);
});

// Per-client profitability + lifetime value (Hormozi LTGP) for the Revenue page.
//
// Cost model (per user spec — NO cost other than these two):
//   • Mailbox cost  — MONTHLY recurring. Current monthly $/client (supplier×type
//                     unit cost, same as the Finance snapshot) × months active.
//   • Domain cost   — a YEARLY registrar cost (domains_bought × domain_unit_cost),
//                     absorbed 100% in the client's FIRST revenue month.
// Both costs are stored/priced in USD and converted to GBP (revenue is GBP) using
// the current month's FX rate, matching how finance.html displays them.
//
// Gross profit (lifetime) = lifetime revenue − (months_active × monthly_mailbox)
//                                             − domain_cost
// LTV = lifetime gross profit (LTGP). Also returns a per-month gross-profit series.
app.get('/api/revenue/profit', requireAdmin, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;

    // FX (USD→GBP) for the current month — costs are USD, revenue is GBP.
    const month = new Date().toISOString().slice(0, 7);
    let fx = { GBP: 1, USD: 0.79 };
    try { fx = { ...fx, ...(await getFxRatesForMonth(month)) }; } catch {}
    const usdToGbp = fx.USD || 0.79;

    // Domain unit cost (USD) from app_settings; default $5.42/domain.
    let domainUnitCostUsd = 5.42;
    try {
      const s = pgdb ? await pgdb.getSetting('domain_unit_cost', null) : null;
      if (s != null && !isNaN(Number(s))) domainUnitCostUsd = Number(s);
    } catch {}

    // Current monthly mailbox cost per workspace (USD) — reuse Finance machinery.
    // Also count DISTINCT sending domains per workspace from PlusVibe's live
    // roster (same derivation as the client health snapshot) so the UI can
    // auto-fill domains_bought from PV.
    const costByWorkspace = {};
    const pvDomainsByWorkspace = {}; // ws → Set of domains
    try {
      const allMailboxes = _mailboxCache.mailboxes || [];
      const meta = pgdb ? await pgdb.listMailboxMeta() : [];
      const metaByEmail = new Map(meta.map(m => [m.email, m]));
      const mailboxes = mergeMailboxesWithMeta(allMailboxes, metaByEmail);
      const prices = pricingMap(pgdb ? await pgdb.listMailboxPricing() : []);
      for (const m of mailboxes) {
        const ws = m.workspace_id;
        if (!ws) continue;
        costByWorkspace[ws] = (costByWorkspace[ws] || 0) + mailboxUnitCost(m, prices);
        // Domain cost EXCLUDES 'Google Generic' mailboxes — those domains
        // aren't paid for, so they must not count toward the PV domain auto-fill.
        if (m.supplier === 'Google Generic') continue;
        const dom = (m.domain || (m.email || '').split('@')[1] || '').toLowerCase();
        if (dom) {
          if (!pvDomainsByWorkspace[ws]) pvDomainsByWorkspace[ws] = new Set();
          pvDomainsByWorkspace[ws].add(dom);
        }
      }
    } catch (e) { console.warn('[profit] mailbox cost failed:', e.message); }

    // Client meta: price, status, domains bought, mailbox cost override.
    const clientRows = db.prepare(
      'SELECT workspace_id, workspace_name, price_per_lead, client_status, domains_bought, mailbox_cost_override FROM clients'
    ).all();
    const cmeta = {};
    clientRows.forEach(c => { cmeta[c.workspace_id] = c; });

    // Non-lead exclusions — same rules as the rest of the revenue page.
    const manualNonleads = new Set(
      db.prepare(`SELECT email FROM nonlead_overrides WHERE active = 1`).all()
        .map(r => String(r.email || '').toLowerCase())
    );

    // Aggregate active leads → per-workspace revenue + first/last revenue month.
    const agg = {}; // ws → { revenue, leads, firstMonth, lastMonth }
    (revenueCache.leads || []).forEach(l => {
      if (isRevenueExcludedWorkspace(l)) return;
      if (manualNonleads.has(String(l.lead_email || '').toLowerCase())) return;
      if (l.pv_nonlead || isPvNonLeadLabel(l.label)) return;
      const ws = l.workspace_id;
      if (!ws) return;
      const price = (cmeta[ws]?.price_per_lead || l.lead_price) || 0;
      const mo = (l.date || '').slice(0, 7); // YYYY-MM
      if (!agg[ws]) agg[ws] = { revenue: 0, leads: 0, firstMonth: null, lastMonth: null, byMonth: {} };
      const a = agg[ws];
      a.revenue += price;
      a.leads += 1;
      if (/^\d{4}-\d{2}$/.test(mo)) {
        if (!a.firstMonth || mo < a.firstMonth) a.firstMonth = mo;
        if (!a.lastMonth  || mo > a.lastMonth)  a.lastMonth  = mo;
        a.byMonth[mo] = (a.byMonth[mo] || 0) + price;
      }
    });

    // Whole calendar months from first→last revenue month, inclusive.
    const monthsBetween = (from, to) => {
      if (!from || !to) return 1;
      const [fy, fm] = from.split('-').map(Number);
      const [ty, tm] = to.split('-').map(Number);
      return Math.max(1, (ty - fy) * 12 + (tm - fm) + 1);
    };

    const clients = [];
    let totRevenue = 0, totMailbox = 0, totDomain = 0, totGross = 0;

    for (const ws of Object.keys(agg)) {
      const a = agg[ws];
      const m = cmeta[ws] || {};
      const monthsActive   = monthsBetween(a.firstMonth, a.lastMonth);
      // Manual override (USD/mo) wins over the auto-computed supplier×type cost.
      const overrideUsd    = (m.mailbox_cost_override != null) ? Number(m.mailbox_cost_override) : null;
      const monthlyMailboxUsd = overrideUsd != null ? overrideUsd : (costByWorkspace[ws] || 0);
      const monthlyMailbox = monthlyMailboxUsd * usdToGbp;             // GBP/mo
      const mailboxCost    = monthlyMailbox * monthsActive;            // lifetime GBP
      // Domains for costing: manual domains_bought if set (>0), else fall back
      // to the live count of distinct sending domains on PlusVibe.
      const pvDomains      = pvDomainsByWorkspace[ws] ? pvDomainsByWorkspace[ws].size : 0;
      const domainsManual  = m.domains_bought || 0;
      const domainsBought  = domainsManual > 0 ? domainsManual : pvDomains;
      const domainsSource  = domainsManual > 0 ? 'manual' : 'pv';
      const domainCost     = domainsBought * domainUnitCostUsd * usdToGbp; // GBP, absorbed month 1
      const grossProfit    = a.revenue - mailboxCost - domainCost;       // = LTV (LTGP)
      const grossMargin    = a.revenue > 0 ? grossProfit / a.revenue : null;

      // Monthly gross-profit series: revenue that month − monthly mailbox −
      // (domain cost only in the first revenue month).
      const monthly = Object.keys(a.byMonth).sort().map(mo => ({
        month: mo,
        revenue: a.byMonth[mo],
        gross_profit: a.byMonth[mo] - monthlyMailbox - (mo === a.firstMonth ? domainCost : 0),
      }));

      totRevenue += a.revenue; totMailbox += mailboxCost;
      totDomain  += domainCost; totGross += grossProfit;

      clients.push({
        workspace_id:   ws,
        client_name:    m.workspace_name || a.client_name || ws,
        client_status:  m.client_status || 'active',
        leads:          a.leads,
        months_active:  monthsActive,
        revenue:        a.revenue,
        monthly_mailbox_cost: monthlyMailbox,
        mailbox_cost_override_usd: overrideUsd, // null = auto
        monthly_mailbox_cost_usd:  monthlyMailboxUsd,
        mailbox_cost:   mailboxCost,
        domains_bought: domainsBought,
        domains_manual: domainsManual,   // what's stored (0 = not set)
        pv_domains:     pvDomains,        // live distinct domains on PlusVibe
        domains_source: domainsSource,    // 'manual' | 'pv'
        domain_cost:    domainCost,
        gross_profit:   grossProfit,
        gross_margin:   grossMargin,
        avg_monthly_gross_profit: grossProfit / monthsActive, // lifetime GP ÷ months active
        ltv:            grossProfit, // lifetime gross profit
        monthly,
      });
    }
    clients.sort((x, y) => y.gross_profit - x.gross_profit);

    res.json({
      fx: { usd_to_gbp: usdToGbp, month },
      domain_unit_cost_usd: domainUnitCostUsd,
      totals: {
        revenue:      totRevenue,
        mailbox_cost: totMailbox,
        domain_cost:  totDomain,
        gross_profit: totGross,
        gross_margin: totRevenue > 0 ? totGross / totRevenue : null,
        client_count: clients.length,
        avg_ltv:      clients.length ? totGross / clients.length : 0,
        // Mean of each client's own monthly-average gross profit (£/client/month).
        avg_monthly_gross_profit: clients.length
          ? clients.reduce((s, c) => s + c.avg_monthly_gross_profit, 0) / clients.length
          : 0,
      },
      clients,
    });
  } catch (err) {
    console.error('[revenue/profit] failed:', err);
    res.status(500).json({ error: err.message });
  }
});

// Get / set the global domain unit cost (USD per domain) used by the profit calc.
app.get('/api/revenue/domain-cost', requireAdmin, async (req, res) => {
  const pgdb = app.locals.pgDb;
  let cost = 5.42;
  try {
    const s = pgdb ? await pgdb.getSetting('domain_unit_cost', null) : null;
    if (s != null && !isNaN(Number(s))) cost = Number(s);
  } catch {}
  res.json({ domain_unit_cost_usd: cost });
});

app.post('/api/revenue/domain-cost', requireAdmin, async (req, res) => {
  const v = Number(req.body?.domain_unit_cost_usd);
  if (isNaN(v) || v < 0) return res.status(400).json({ error: 'Invalid cost' });
  try { await app.locals.pgDb?.setSetting('domain_unit_cost', v); }
  catch (e) { return res.status(500).json({ error: e.message }); }
  res.json({ ok: true, domain_unit_cost_usd: v });
});

// Set domains_bought for one client (by workspace_id) — inline edit from the
// Revenue page's Client Performance table.
app.post('/api/revenue/domains-bought', requireAdmin, (req, res) => {
  const { workspace_id, domains_bought } = req.body || {};
  if (!workspace_id) return res.status(400).json({ error: 'Missing workspace_id' });
  const n = parseInt(domains_bought);
  if (isNaN(n) || n < 0) return res.status(400).json({ error: 'Invalid domains_bought' });
  db.prepare('UPDATE clients SET domains_bought = ? WHERE workspace_id = ?').run(n, workspace_id);
  res.json({ ok: true });
});

// Manually override a client's MONTHLY mailbox cost (USD). Send null/empty to
// clear the override and fall back to the auto-computed supplier×type cost.
app.post('/api/revenue/mailbox-cost', requireAdmin, (req, res) => {
  const { workspace_id } = req.body || {};
  if (!workspace_id) return res.status(400).json({ error: 'Missing workspace_id' });
  const raw = req.body?.mailbox_cost_override_usd;
  let val = null;
  if (raw !== null && raw !== undefined && String(raw).trim() !== '') {
    val = Number(raw);
    if (isNaN(val) || val < 0) return res.status(400).json({ error: 'Invalid cost' });
  }
  db.prepare('UPDATE clients SET mailbox_cost_override = ? WHERE workspace_id = ?').run(val, workspace_id);
  res.json({ ok: true, mailbox_cost_override_usd: val });
});

// ── Performance cache (kept warm so filter changes are fast) ──
const performanceCache = {
  dailyStats: new Map(),
  labeledLeads: new Map(),
  warming: false,
  updatedAt: null,
  version: 0,
  lastStartedAt: null,
};
const PERF_TODAY_TTL_MS = 2 * 60 * 1000;   // today refreshes every ~2 min (live Bison)
const PERF_OLD_TTL_MS = 12 * 60 * 60 * 1000;
const PERF_LEADS_TTL_MS = 15 * 60 * 1000;
const PERF_WARM_INTERVAL_MS = 2 * 60 * 1000;
const EMPTY_PERF_AGG = { sent: 0, replies: 0, oooReplies: 0, posReplies: 0, bounces: 0, contacted: 0 };
let performanceWarmPromise = null;

function serverDateString(date) {
  return date.getFullYear() + '-' +
    String(date.getMonth() + 1).padStart(2, '0') + '-' +
    String(date.getDate()).padStart(2, '0');
}

function serverDateList(startStr, endStr) {
  const out = [];
  const cur = new Date(`${startStr}T00:00:00`);
  const end = new Date(`${endStr}T00:00:00`);
  while (cur <= end) {
    out.push(serverDateString(cur));
    cur.setDate(cur.getDate() + 1);
  }
  return out;
}

function lastNDates(n) {
  const today = new Date();
  const start = new Date(today);
  start.setDate(start.getDate() - (n - 1));
  return serverDateList(serverDateString(start), serverDateString(today));
}

function aggPvEmailStats(stats) {
  // Always use chart (daily rows) — header is cumulative all-time totals, not per-day
  const rows = (Array.isArray(stats) ? stats : (stats?.chart || []));
  return rows.reduce((a, r) => ({
    sent:       a.sent       + (r.total_sent_count               || 0),
    replies:    a.replies    + (r.total_reply_count              || 0),
    oooReplies: a.oooReplies + (r.total_ooo_reply_count          || 0),
    posReplies: a.posReplies + (r.total_pos_reply_count          || 0),
    bounces:    a.bounces    + (r.total_bounce_count             || 0),
    contacted:  a.contacted  + (r.total_contacted_count || r.total_sent_count || 0),
  }), { sent: 0, replies: 0, oooReplies: 0, posReplies: 0, bounces: 0, contacted: 0 });
}

async function activePerformanceWorkspaces() {
  let clientRows = [];
  try { clientRows = db.prepare(`SELECT workspace_id, client_status FROM clients`).all(); } catch {}
  const [wsRaw] = await Promise.all([pvFetch('/workspaces')]);
  const inactiveIds = new Set(clientRows.filter(r => r.client_status === 'inactive').map(r => r.workspace_id));
  const workspaces = Array.isArray(wsRaw) ? wsRaw : (wsRaw?.workspaces || wsRaw?.data || []);
  return workspaces.filter(ws => !inactiveIds.has(ws.id));
}

// Reply data is sourced from the client-portal's CLASSIFIED unibox_replies table
// (reviewed, so warm-up/auto noise is excluded) instead of Bison's raw
// total_reply_count. We override the reply fields on the daily-stats aggregate for
// dates ON/AFTER the fresh-start cutover; before the cutover we keep the frozen
// historic (PlusVibe-era) numbers. sent/bounce/contacted always stay from Bison —
// the portal doesn't track sends. Leads are unchanged (revenueCache/esp_leads).
//
//   replies    = ALL replies except warmup (human + OOO + auto_reply + bounces etc.)
//   oooReplies = ooo_auto_reply (subset of replies, for breakdown display)
//   posReplies = interested  (the "positive reply" the RTL view keys on)
//   warmup is EXCLUDED entirely (Bison warmup tag only).
//
// One batched query for all needed (wsId,date) pairs (keyed off received_at::date),
// so there's no per-day N+1. Returns Map "wsId|date" -> {replies,oooReplies,posReplies}.
async function fetchPortalReplyCounts(wsIds, dates) {
  const out = new Map();
  const pgdb = app.locals.pgDb;
  if (!pgdb || !wsIds.length || !dates.length) return out;
  // Only override dates at/after the cutover; before it, historic numbers stand.
  const cutover = _freshStartDate; // 'YYYY-MM-DD' or null
  const targetDates = cutover ? dates.filter(d => d >= cutover) : dates;
  if (!targetDates.length) return out;
  const minDate = targetDates.reduce((m, d) => (d < m ? d : m), targetDates[0]);
  const maxDate = targetDates.reduce((m, d) => (d > m ? d : m), targetDates[0]);
  try {
    const { rows } = await pgdb.query(
      `SELECT workspace_id AS ws,
              to_char(received_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') AS date,
              COUNT(*) FILTER (WHERE COALESCE(admin_label, category) NOT IN ('warmup','warm_up','other')
                               AND folder = 'inbox')::int AS replies,
              COUNT(*) FILTER (WHERE COALESCE(admin_label, category) = 'ooo_auto_reply')::int AS ooo,
              COUNT(*) FILTER (WHERE COALESCE(admin_label, category) = 'interested')::int AS pos
         FROM unibox_replies
        WHERE workspace_id = ANY($1)
          AND received_at >= $2::date
          AND received_at <  ($3::date + interval '1 day')
        GROUP BY workspace_id, 2`,
      [wsIds, minDate, maxDate]
    );
    for (const r of rows) {
      out.set(`${r.ws}|${r.date}`, { replies: r.replies, oooReplies: r.ooo, posReplies: r.pos });
    }
  } catch (e) {
    console.warn('[performance cache] portal reply override query failed:', e.message);
  }
  return out;
}

async function ensurePerformanceDailyStats(wsIds, dates, dailyStats = performanceCache.dailyStats, forceDates = new Set()) {
  const today = serverDateString(new Date());
  if (!dates.length) return dailyStats;
  // Which workspaces have ANY stale/missing/forced day in this window? Only those
  // get re-fetched — but each is fetched as ONE RANGE call (not per-day). PlusVibe
  // /account/email-stats returns a per-day `chart` for the whole range in a single
  // call, so we never fire wsIds×dates requests (the per-day pattern throttled PV
  // and undercounted — see project_perfcache_range_fetch). PV DOES include today
  // in a range response, so no single-day workaround is needed.
  const sorted = [...dates].sort();
  const rangeStart = sorted[0];
  const rangeEnd = sorted[sorted.length - 1];
  const dateSet = new Set(dates);
  const wsNeeding = wsIds.filter(wsId =>
    dates.some(date => {
      const cached = dailyStats.get(`${wsId}|${date}`);
      const ttl = date === today ? PERF_TODAY_TTL_MS : PERF_OLD_TTL_MS;
      return forceDates.has(date) || !cached || Date.now() - cached.savedAt > ttl;
    })
  );
  const CONC = 6;
  for (let i = 0; i < wsNeeding.length; i += CONC) {
    await Promise.allSettled(wsNeeding.slice(i, i + CONC).map(async (wsId) => {
      try {
        const pvStatsResp = await pvApi('/account/email-stats', { wsId, params: { start_date: rangeStart, end_date: rangeEnd } });
        const chart = Array.isArray(pvStatsResp) ? pvStatsResp : (pvStatsResp?.chart || pvStatsResp?.data || []);
        const pivot = pivotBisonStats(chart);
        const seen = new Set();
        for (const date of dates) {
          const row = pivot[date];
          const hasBackfill = !!(BISON_CUTOVER_BACKFILL[date] && BISON_CUTOVER_BACKFILL[date][wsId]);
          if (!row && !hasBackfill) continue;
          const agg = aggPvEmailStats(row ? [row] : []);
          applyCutoverBackfill(wsId, date, agg); // + Bison cutover-day sends/bounces
          // Don't let a transient empty/0 today overwrite a known-good today value.
          if (date === today && agg.sent === 0) {
            const prev = dailyStats.get(`${wsId}|${date}`);
            if (prev && prev.data && prev.data.sent > 0) { seen.add(date); continue; }
          }
          dailyStats.set(`${wsId}|${date}`, { savedAt: Date.now(), data: agg });
          seen.add(date);
        }
        // A day absent from a SUCCESSFUL chart response genuinely had 0 activity —
        // cache a real zero so it isn't retried forever (never overwrite non-zero).
        for (const date of dates) {
          if (seen.has(date) || date > today) continue;
          const key = `${wsId}|${date}`;
          const prev = dailyStats.get(key);
          if (prev && prev.data && (prev.data.sent > 0 || prev.data.replies > 0)) continue;
          dailyStats.set(key, { savedAt: Date.now(), data: { ...EMPTY_PERF_AGG } });
        }
      } catch {
        // Fetch FAILED — never poison with a trusted 0. Keep prior values; for any
        // missing day store zeros marked stale (savedAt:0) so the next pass retries.
        for (const date of dates) {
          const key = `${wsId}|${date}`;
          if (!dailyStats.has(key)) dailyStats.set(key, { savedAt: 0, data: { ...EMPTY_PERF_AGG } });
        }
      }
    }));
  }
  // Override reply fields with the portal's classified counts (post-cutover dates
  // only). sent/bounce/contacted stay from Bison. A missing portal entry for a
  // post-cutover (wsId,date) means zero real replies that day → set 0, don't keep
  // the raw Bison reply number (which would include warm-up/auto noise).
  try {
    const portal = await fetchPortalReplyCounts(wsIds, dates);
    const cutover = _freshStartDate;
    for (const wsId of wsIds) for (const date of dates) {
      if (cutover && date < cutover) continue; // historic: leave frozen
      const key = `${wsId}|${date}`;
      const entry = dailyStats.get(key);
      if (!entry || !entry.data) continue;
      const p = portal.get(key) || { replies: 0, oooReplies: 0, posReplies: 0 };
      entry.data = { ...entry.data, replies: p.replies, oooReplies: p.oooReplies, posReplies: p.posReplies };
    }
  } catch (e) {
    console.warn('[performance cache] portal reply override failed:', e.message);
  }
  const out = {};
  for (const wsId of wsIds) for (const date of dates) {
    const key = `${wsId}|${date}`;
    out[key] = dailyStats.get(key)?.data;
  }
  return out;
}

function performanceLeadDate(wsId, lead) {
  const leadKey = stableLeadKey(wsId, lead);
  const email = lead?.email || lead?.lead_email || '';
  return getStableRevenueLeadDate(wsId, leadKey, email, sourceLeadDate(lead));
}

function normalizePerformanceLead(wsId, lead, label) {
  return {
    ...lead,
    _pv_lead_date: performanceLeadDate(wsId, lead),
    _pv_nonlead: isPvNonLeadLabel(label) || isPvNonLeadLabel(lead?.label),
  };
}

async function fetchPerformanceLabeledLeads(wsId) {
  const leads = [];
  const seenIds = new Set();
  for (const label of LEAD_LABELS) {
    for (let page = 1; page <= 20; page++) {
      let batch = [];
      try {
        const raw_b = await pvApi('/lead/workspace-leads', { wsId: wsId, params: { label: label, page: page, limit: 100 } });
        batch = (Array.isArray(raw_b) ? raw_b : (raw_b?.data || [])).map(function(l) { return Object.assign({}, l, { _id: String(l.id || l._id || ''), id: String(l.id || l._id || ''), company_name: l.company_name || l.company, job_title: l.job_title || l.title, label: l.label || (l.interested ? 'INTERESTED' : (l.status || '')) }); });
      } catch { break; }
      if (!batch.length) break;
      batch.forEach(l => {
        const id = l._id || l.id || l.email;
        if (seenIds.has(id)) {
          const existing = leads.find(x => (x._id || x.id || x.email) === id);
          if (existing) {
            existing._pv_lead_date = existing._pv_lead_date || performanceLeadDate(wsId, l);
            if (isPvNonLeadLabel(label) || isPvNonLeadLabel(l.label)) existing._pv_nonlead = true;
          }
          return;
        }
        seenIds.add(id);
        leads.push(normalizePerformanceLead(wsId, l, label));
      });
      if (batch.length < 100) break;
    }
  }
  return leads;
}

async function ensurePerformanceLabeledLeads(wsIds, labeledLeads = performanceCache.labeledLeads, force = false) {
  // Fetch leads for 2 workspaces concurrently. Higher values trigger
  // PlusVibe 429s (8 labels × concurrent workspaces = too many requests).
  const needed = wsIds.filter(wsId => {
    const cached = labeledLeads.get(wsId);
    return force || !cached || Date.now() - cached.savedAt > PERF_LEADS_TTL_MS;
  });
  const CONC = 2;
  for (let i = 0; i < needed.length; i += CONC) {
    await Promise.allSettled(needed.slice(i, i + CONC).map(async wsId => {
      try {
        const data = await fetchPerformanceLabeledLeads(wsId);
        labeledLeads.set(wsId, { savedAt: Date.now(), data });
      } catch {
        labeledLeads.set(wsId, { savedAt: Date.now(), data: [] });
      }
    }));
  }
  const out = {};
  for (const wsId of wsIds) out[wsId] = labeledLeads.get(wsId)?.data || [];
  return out;
}

async function loadPerfCacheFromDb() {
  const pgdb = app.locals.pgDb;
  if (!pgdb) return;
  try {
    const [dailyRows, leadsRows] = await Promise.all([
      pgdb.loadPerfCacheDaily(),
      pgdb.loadPerfCacheLeads(),
    ]);
    for (const row of dailyRows) {
      performanceCache.dailyStats.set(`${row.ws_id}|${row.date}`, {
        savedAt: Number(row.saved_at),
        data: row.data,
      });
    }
    for (const row of leadsRows) {
      performanceCache.labeledLeads.set(row.ws_id, {
        savedAt: Number(row.saved_at),
        data: row.data,
      });
    }
    if (dailyRows.length || leadsRows.length) {
      performanceCache.version++;
      console.log(`[performance cache] loaded ${dailyRows.length} daily + ${leadsRows.length} lead entries from DB`);
    }
  } catch (err) {
    console.warn('[performance cache] DB load failed (will fetch fresh):', err.message);
  }
}

async function savePerfCacheToDb() {
  const pgdb = app.locals.pgDb;
  if (!pgdb) return;
  try {
    const dailyEntries = [];
    for (const [key, val] of performanceCache.dailyStats) {
      const [wsId, date] = key.split('|');
      dailyEntries.push({ wsId, date, data: val.data, savedAt: val.savedAt });
    }
    const leadsEntries = [];
    for (const [wsId, val] of performanceCache.labeledLeads) {
      leadsEntries.push({ wsId, data: val.data, savedAt: val.savedAt });
    }
    // Batch in chunks of 500 to avoid huge queries
    for (let i = 0; i < dailyEntries.length; i += 500)
      await pgdb.savePerfCacheDaily(dailyEntries.slice(i, i + 500));
    for (let i = 0; i < leadsEntries.length; i += 100)
      await pgdb.savePerfCacheLeads(leadsEntries.slice(i, i + 100));
  } catch (err) {
    console.warn('[performance cache] DB save failed:', err.message);
  }
}

async function warmPerformanceCache() {
  if (performanceWarmPromise) return performanceWarmPromise;
  performanceCache.warming = true;
  performanceCache.lastStartedAt = new Date().toISOString();
  performanceWarmPromise = (async () => {
    try {
      const workspaces = await activePerformanceWorkspaces();
      const wsIds = workspaces.map(ws => ws.id);
      const today = serverDateString(new Date());
      const fullWarmDates = [...new Set([
        ...lastNDates(30),
        ...serverDateList(`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}-01`, today),
      ])].sort();

      // Phase 1 — last 7 days only. Commit immediately so the Stats page
      // (default "7 Days" view) unblocks without waiting for the full 30-day fetch.
      const nextDailyStats = new Map(performanceCache.dailyStats);
      await ensurePerformanceDailyStats(wsIds, lastNDates(7), nextDailyStats);
      performanceCache.dailyStats = nextDailyStats;
      performanceCache.updatedAt = new Date().toISOString();
      console.log(`[performance cache] phase-1 ready (7d) — ${wsIds.length} workspaces`);

      // Phase 2 — remaining dates + labeled leads. nextDailyStats is the same
      // map reference now live in performanceCache, so entries appear as they arrive.
      await ensurePerformanceDailyStats(wsIds, fullWarmDates, nextDailyStats);
      performanceCache.updatedAt = new Date().toISOString();

      // Labeled leads — slowest fetch, only needed for Performance page.
      const nextLabeledLeads = new Map(performanceCache.labeledLeads);
      await ensurePerformanceLabeledLeads(wsIds, nextLabeledLeads);
      performanceCache.labeledLeads = nextLabeledLeads;
      performanceCache.version++;
      console.log(`[performance cache] version ${performanceCache.version} ready — ${wsIds.length} workspaces`);
      // Persist to DB so next restart loads instantly.
      // DISABLED by default: admin-new is now the SOLE writer of
      // perf_cache_daily (shared PK ws_id,date). Legacy aggregates from PV's
      // `chart` array (aggPvEmailStats) while admin-new reads `header` — for a
      // single day these DIFFER (e.g. Enviro chart-sum 74 vs header 18), so the
      // two writers flip-flopped the row and corrupted Stats. Legacy keeps its
      // in-memory cache for its own pages but must NOT write the shared row.
      if (process.env.LEGACY_PERSIST_PERF_CACHE === '1') savePerfCacheToDb().catch(() => {});
    } catch (err) {
      console.error('[performance cache] warm failed:', err.message);
    } finally {
      performanceCache.warming = false;
      performanceWarmPromise = null;
    }
  })();
  return performanceWarmPromise;
}

// Load persisted cache from DB first so pages show data instantly on restart
setTimeout(async () => {
  await loadPerfCacheFromDb();
  // Then schedule the first warm to refresh today's data + fill any gaps
  setTimeout(warmPerformanceCache, 30000);
}, 10000);
// Keep warming every 2 min after that
setInterval(warmPerformanceCache, PERF_WARM_INTERVAL_MS);

// ── Contacts filter-dropdown warm ───────────────────────────────────────────
// getDistinctValues() is now cache-only, so this pass is the ONLY thing that
// fills it — same trade as the combo cache: the background pass owns the cache
// and the request path never pays for a scan. Serial, on a raised
// statement_timeout, because the slow fields (job_title ~62s) exceed the pool
// default and could never complete on a request.
//
// 30 min, not 2: these are full scans of the contacts table and the values
// change on import, not minute to minute. First pass is delayed to let boot
// settle — a cold dropdown for the first minute is fine, a scan competing with
// startup is not.
const DISTINCT_WARM_INTERVAL_MS = 30 * 60 * 1000;
const runDistinctWarm = () => {
  // pgDb is attached to app.locals during async startup, so it may not exist
  // yet on the first tick — skip and catch the next one.
  const db = app.locals.pgDb;
  if (!db) return;
  db.warmDistinctValues('ottaly-global')
    .catch(e => console.error('[distinct-warm] pass failed:', e.message));
};
// Seed the dropdowns from contacts_distinct_cache FIRST. getDistinctValues is
// cache-only (returns [] on a miss) and the cache is in-memory, so before this
// existed every deploy left the location filters reading "No results" until the
// 45s-delayed warm walked all 16 fields serially at ~1.3s each. Seeding is 16
// indexed reads of a precomputed table, so the filters are usable within
// seconds of boot; the warm then refreshes them with live values as before.
const seedDistinctFromDb = (attempt = 0) => {
  const db = app.locals.pgDb;
  // pgDb is attached during async startup — retry briefly rather than losing
  // the seed entirely if we land before it is ready.
  if (!db) {
    if (attempt < 10) setTimeout(() => seedDistinctFromDb(attempt + 1), 3000);
    return;
  }
  db.seedDistinctCacheFromDb('ottaly-global')
    .catch(e => console.error('[distinct-seed] failed:', e.message));
};
setTimeout(() => seedDistinctFromDb(), 3000);

setTimeout(runDistinctWarm, 45000);
setInterval(runDistinctWarm, DISTINCT_WARM_INTERVAL_MS);

// ── Verification retry drain ───────────────────────────────────────────────
// Re-checks addresses whose verification failed for an INFRASTRUCTURE reason
// (timeout / refused / 5xx), never a genuine SMTP verdict. Before this queue
// existed those addresses were written 'unknown' and forgotten, so a verifier
// outage silently destroyed the work and the only recovery was a human
// restarting the container. Now the backlog drains by itself.
//
// Deliberately small and slow: this is recovery work, not throughput. It must
// never compete with the interactive push-verify path for the finder's 5
// concurrent Reacher slots, so it runs a small batch on a long interval and
// stops early the moment the verifier still looks unhealthy.
const VERIFY_DRAIN_INTERVAL_MS = 5 * 60 * 1000;
const VERIFY_DRAIN_BATCH = 50;
const VERIFY_DRAIN_CONCURRENCY = 3;
let _verifyDrainRunning = false;

async function runVerificationDrain() {
  const db = app.locals.pgDb;
  if (!db || !db.claimVerificationBatch || _verifyDrainRunning) return;
  _verifyDrainRunning = true;
  try {
    const batch = await db.claimVerificationBatch(VERIFY_DRAIN_BATCH);
    if (!batch.length) return;

    const port = EMAIL_FINDER_INTERNAL_PORT;
    const settled = [];   // got a real verdict -> leave the queue
    const failed  = [];   // still broken -> back off and stay queued
    let lastErr = '';

    // Sequential-ish with a small concurrency cap; see note above.
    for (let i = 0; i < batch.length; i += VERIFY_DRAIN_CONCURRENCY) {
      // If the verifier is still down, stop the whole pass rather than burn
      // every queued row's attempt counter on the same outage.
      if (failed.length >= VERIFY_DRAIN_CONCURRENCY * 2 && settled.length === 0) break;
      const slice = batch.slice(i, i + VERIFY_DRAIN_CONCURRENCY);
      await Promise.all(slice.map(async (row) => {
        try {
          const r = await fetch(`http://127.0.0.1:${port}/api/verify-email`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email: row.email, verifier: 'reacher' }),
            signal: AbortSignal.timeout(20000),
          });
          if (!r.ok) throw new Error(`finder HTTP ${r.status}`);
          const d = await r.json();
          const smtp = d.result?.raw?.smtp || d.result?.smtp || {};
          const reason = d.result?.reason || '';
          const catchAll = smtp.is_catch_all === true || /catch_all=yes/i.test(reason);
          const rea = (d.result?.status || d.result?.is_reachable || 'unknown').toLowerCase();
          const status = catchAll || rea === 'risky' ? 'risky'
            : rea === 'safe' || rea === 'valid' ? 'safe'
            : rea === 'invalid' ? 'invalid'
            : 'unknown';
          // 'unknown' from the finder is a real SMTP-level answer, not an
          // outage -- accept it and stop retrying, or we would loop forever
          // on addresses that genuinely cannot be resolved.
          await db.query(
            `UPDATE contacts SET email_status = $2, email_verified_at = NOW()::text WHERE id = $1`,
            [row.contact_id, status], { background: true }
          );
          settled.push(row.contact_id);
        } catch (e) {
          lastErr = e && e.message || String(e);
          failed.push(row);
        }
      }));
    }

    if (settled.length) await db.dequeueVerification(settled);
    if (failed.length)  await db.enqueueVerification(failed, lastErr);
    if (settled.length || failed.length) {
      console.log(`[verify-drain] ${settled.length} settled, ${failed.length} deferred${lastErr ? ` (${lastErr.slice(0, 80)})` : ''}`);
    }
  } catch (err) {
    console.error('[verify-drain] pass failed:', err.message);
  } finally {
    _verifyDrainRunning = false;
  }
}
setTimeout(() => { runVerificationDrain().catch(() => {}); }, 120000);
setInterval(() => { runVerificationDrain().catch(() => {}); }, VERIFY_DRAIN_INTERVAL_MS);

function readReadyPerformanceCache(wsIds, dates) {
  const daily = {};
  const leads = {};
  for (const wsId of wsIds) {
    leads[wsId] = performanceCache.labeledLeads.get(wsId)?.data || [];
    for (const date of dates) {
      const key = `${wsId}|${date}`;
      daily[key] = performanceCache.dailyStats.get(key)?.data || { ...EMPTY_PERF_AGG };
    }
  }
  return { daily, leads };
}

async function buildRequestedPerformanceCache(wsIds, dates, forceLeads = false, forceDates = new Set()) {
  const nextDailyStats = new Map(performanceCache.dailyStats);
  const nextLabeledLeads = new Map(performanceCache.labeledLeads);
  await ensurePerformanceLabeledLeads(wsIds, nextLabeledLeads, forceLeads);
  await ensurePerformanceDailyStats(wsIds, dates, nextDailyStats, forceDates);
  performanceCache.dailyStats = nextDailyStats;
  performanceCache.labeledLeads = nextLabeledLeads;
  performanceCache.updatedAt = new Date().toISOString();
  performanceCache.version++;
  console.log(`[performance cache] version ${performanceCache.version} ready on demand — ${wsIds.length} workspaces`);
}

function hasReadyPerformanceCache(wsIds, dates) {
  if (performanceCache.version === 0) return false;
  return wsIds.every(wsId => performanceCache.labeledLeads.has(wsId))
    && wsIds.every(wsId => dates.every(date => performanceCache.dailyStats.has(`${wsId}|${date}`)));
}

async function ensureInitialPerformanceVersion(wsIds, dates) {
  if (performanceCache.version > 0) return;
  if (performanceWarmPromise) await performanceWarmPromise;
  if (performanceCache.version === 0) await buildRequestedPerformanceCache(wsIds, dates);
}

app.get('/api/performance/agency-cache', requireSession, async (req, res) => {
  const wsIds = String(req.query.workspace_ids || '').split(',').map(s => s.trim()).filter(Boolean);
  const start = clampStartDate(String(req.query.start || ''));
  const end = String(req.query.end || '');
  if (!wsIds.length || !start || !end) return res.status(400).json({ error: 'Missing workspace_ids, start, or end' });
  try {
    const dates = serverDateList(start, end);
    if (!hasReadyPerformanceCache(wsIds, dates)) {
      // Race: either the cache becomes ready within 12 seconds, or we
      // return whatever's there so far. The client will retry (or show
      // the partial data) rather than hanging indefinitely.
      await Promise.race([
        buildRequestedPerformanceCache(wsIds, dates),
        new Promise(resolve => setTimeout(resolve, 12000))
      ]);
    }
    const { daily, leads } = readReadyPerformanceCache(wsIds, dates);
    if (!performanceCache.warming) setTimeout(warmPerformanceCache, 0);
    res.json({
      daily,
      leads,
      updatedAt: performanceCache.updatedAt,
      version: performanceCache.version,
      warming: performanceCache.warming,
      partial: !hasReadyPerformanceCache(wsIds, dates),
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Stats page endpoint ──────────────────────────────────────
// Returns per-workspace daily stats + leads for the requested date range.
app.post('/api/stats/refresh', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    if (pgdb) await pgdb.clearPerfCache();
    performanceCache.dailyStats.clear();
    performanceCache.labeledLeads.clear();
    performanceCache.version = 0;
    performanceWarmPromise = null;
    warmPerformanceCache().catch(() => {});
    res.json({ ok: true, message: 'Cache cleared — refreshing from PlusVibe' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Reuses the existing performance cache infrastructure so data is always
// warm and consistent with the Performance page.
// Per-workspace sent/replies/bounces/leads for a date range, computed from the
// SAME authoritative sources as the Stats page:
//   • sent / replies / bounces ← performanceCache.dailyStats (deduped PlusVibe email-stats)
//   • leads                    ← revenueCache.leads (with nonlead overrides + exclusions)
// Any page that needs these numbers (Stats summary, CM Performance) MUST use this
// so the totals always agree. Returns a map keyed by workspace_id.
function computeWorkspaceStatsForRange(wsIds, start, end) {
  const dates = serverDateList(start, end);
  const nonleadEmails = new Set(
    db.prepare(`SELECT email FROM nonlead_overrides WHERE active = 1`).all()
      .map(o => o.email.toLowerCase())
  );
  const out = {};
  for (const wsId of wsIds) {
    const wsLeads = (revenueCache.leads || []).filter(l => {
      // Match on the canonical id so leads stored under a mismatched workspace_id
      // (e.g. Bubble's webhook id) still attach to the right client. Cheap: most
      // leads already equal wsId and short-circuit on the first check.
      if (l.workspace_id !== wsId && canonicalWorkspaceId(l.workspace_id, l.workspace_name || l.client_name) !== wsId) return false;
      if (isRevenueExcludedWorkspace(l)) return false;
      if (nonleadEmails.has((l.lead_email || '').toLowerCase())) return false;
      if (l.pv_nonlead || isPvNonLeadLabel(l.label)) return false;
      const d = (l.date || '').slice(0, 10);
      return d >= start && d <= end;
    });
    const totals = { sent: 0, replies: 0, posReplies: 0, oooReplies: 0, bounces: 0, leads: wsLeads.length };
    const series = dates.map(date => {
      const d = performanceCache.dailyStats.get(`${wsId}|${date}`)?.data || { ...EMPTY_PERF_AGG };
      const dayLeads = wsLeads.filter(l => (l.date || '').slice(0,10) === date).length;
      totals.sent       += d.sent;
      totals.replies    += d.replies;
      totals.posReplies += d.posReplies;
      totals.oooReplies += d.oooReplies;
      totals.bounces    += d.bounces;
      return { date, sent: d.sent, replies: d.replies, posReplies: d.posReplies, oooReplies: d.oooReplies, bounces: d.bounces, leads: dayLeads };
    });
    const replyRate  = totals.sent    > 0 ? totals.replies / totals.sent    : 0;
    const bounceRate = totals.sent    > 0 ? totals.bounces / totals.sent    : 0;
    const rtl        = totals.replies > 0 ? totals.leads   / totals.replies : 0;
    const sendsPerDay   = dates.length > 0 ? totals.sent    / dates.length : 0;
    const repliesPerDay = dates.length > 0 ? totals.replies / dates.length : 0;
    // EXACT leads per provider (from each lead's real mx_provider), so the
    // provider tabs show the true lead count, not a send-ratio estimate.
    const leadsByProvider = { email_google: 0, email_outlook: 0, email_other: 0, unknown: 0 };
    for (const l of wsLeads) {
      const p = l.mx_provider;
      if (p === 'email_google' || p === 'email_outlook' || p === 'email_other') leadsByProvider[p]++;
      else leadsByProvider.unknown++;
    }
    out[wsId] = { totals: { ...totals, replyRate, bounceRate, rtl, sendsPerDay, repliesPerDay }, series, leadsByProvider };
  }
  return out;
}

// Per-workspace recipient-provider SEND SHARE from captured email_events.
// Returns { wsId: { google, outlook, other, coverage } } where the three
// shares sum to 1 (unclassified 'workspace' folded into other), and coverage
// is the fraction of captured sent-events that were classifiable. Workspaces
// with no captured 'sent' events in range are omitted (→ page shows 'syncing').
async function buildProviderMixForRange(pgdb, wsIds, start, end) {
  if (!pgdb || !wsIds.length) return {};
  // Provider per send = TRUE MX from contacts.mx_provider (dense — populated by
  // the verify scan) joined on lead_email; fall back to the sparser
  // email_events.provider_bucket only when the contact isn't classified. This
  // is the same source the combo-analysis 'to_type' uses, and it means a
  // workspace with ANY sends gets a non-empty mix (no "loading forever").
  // workspace_id may be the pv id OR the Bison team_id depending on era; we fold
  // each stored id back to its CANONICAL id below so they merge per client.
  // SOURCE = contacts.emailed_workspaces (NOT email_events). email_events only
  // has 'sent' rows for ~8 of 22 clients (Bison doesn't emit per-message sent
  // webhooks for most), so an event-based mix left 14 clients blank forever.
  // emailed_workspaces is a JSONB on every contact recording which workspaces
  // emailed it (it's how the cooldown works) — populated for ALL clients. We
  // explode it to (workspace_id, mx_provider) per contact, so every workspace
  // that has emailed anyone gets a real Google/Microsoft/Other split. This is a
  // per-recipient ratio (not per-send), which is exactly what a provider SPLIT
  // needs. The `start`/`end` args are unused here (the field has no per-day
  // granularity); the ratio is applied to whatever totals the page holds.
  const { rows } = await pgdb.query(`
    SELECT ws AS workspace_id,
           COUNT(*) FILTER (WHERE mx_provider = 'email_google')  ::int AS google,
           COUNT(*) FILTER (WHERE mx_provider = 'email_outlook') ::int AS outlook,
           COUNT(*) FILTER (WHERE mx_provider = 'email_other')   ::int AS other,
           COUNT(*) FILTER (WHERE mx_provider IS NULL)           ::int AS unclassified,
           COUNT(*)                                               ::int AS total
    FROM contacts c,
         LATERAL jsonb_object_keys(COALESCE(c.emailed_workspaces, '{}'::jsonb)) AS ws
    WHERE c.emailed_workspaces IS NOT NULL
      AND c.emailed_workspaces <> '{}'::jsonb
    GROUP BY ws
  `, []);
  // Key by canonical id AND raw id (dual-key) so the page's lookup hits whatever
  // form it holds. With the contact-keyed query above, most rows now already use
  // the page's id directly.
  const acc = {};       // canonical id -> counts
  const rawToCanon = {}; // raw stored id -> canonical id (for dual-keying)
  for (const r of rows) {
    if (!r.workspace_id) continue;
    const canon = canonicalWorkspaceId(r.workspace_id, null);
    rawToCanon[r.workspace_id] = canon;
    const a = acc[canon] || (acc[canon] = { google: 0, outlook: 0, other: 0, unclassified: 0, total: 0 });
    a.google += r.google; a.outlook += r.outlook; a.other += r.other;
    a.unclassified += r.unclassified; a.total += r.total;
  }

  const out = {};
  for (const [canon, a] of Object.entries(acc)) {
    // Classified sends only drive the ratio; unclassified is folded into 'other'
    // so the three shares always cover 100% of captured sends.
    const g = a.google, o = a.outlook, oth = a.other + a.unclassified;
    const denom = g + o + oth;
    if (denom <= 0) continue;
    out[canon] = {
      // Ratios (for apportioning replies/bounces/leads, which aren't per-provider).
      google:   g   / denom,
      outlook:  o   / denom,
      other:    oth / denom,
      // RAW captured send counts per provider — used directly as the sent split
      // so the provider tabs aren't zero when the Bison daily total is missing.
      gSent: g, oSent: o, othSent: oth,
      coverage: a.total ? (a.google + a.outlook + a.other) / a.total : 0,
    };
  }
  // Expose each mix under EVERY id variant a caller might hold: the canonical id,
  // every raw stored id that folded to it, AND — for any BISON_TEAMS match — both
  // the pv id and the team_id. The page's client rows are keyed by
  // canonicalWorkspaceId(clients.workspace_id,…), which can differ from the
  // email_events workspace_id (pv vs team_id), so we alias all of them to the
  // same mix. This is what finally makes every sending client resolve.
  for (const [raw, canon] of Object.entries(rawToCanon)) {
    const mix = out[canon];
    if (!mix) continue;
    out[raw] = mix;
    // Map across the pv <-> team_id pair from BISON_TEAMS.
    const team = BISON_TEAMS.find(t => t.pv === raw || String(t.team_id) === raw
                                     || t.pv === canon || String(t.team_id) === canon);
    if (team) {
      if (team.pv) out[team.pv] = mix;
      if (team.team_id != null) out[String(team.team_id)] = mix;
    }
  }
  return out;
}

app.get('/api/stats/summary', requireSession, async (req, res) => {
  const start = clampStartDate(String(req.query.start || ''));
  const end   = String(req.query.end   || '');
  if (!start || !end) return res.status(400).json({ error: 'start and end required (YYYY-MM-DD)' });
  try {
    // Use SQLite clients table — no PlusVibe API call needed.
    const clientRows = db.prepare(
      `SELECT workspace_id, workspace_name, client_status FROM clients WHERE workspace_id IS NOT NULL AND workspace_id != ''`
    ).all();
    const filterIds = req.query.workspace_ids ? String(req.query.workspace_ids).split(',').filter(Boolean) : null;
    const activeClients = clientRows.filter(c => {
      if (c.client_status === 'inactive') return false;
      if (filterIds) return filterIds.includes(c.workspace_id);
      return true;
    });
    // Key everything by the CANONICAL workspace_id (the id the perf cache is keyed
    // by). For most clients this equals clients.workspace_id; for rows whose stored
    // id doesn't match the cache (e.g. Bubble) it resolves via BISON_TEAMS so their
    // data is found instead of reading an empty bucket and being filtered out.
    const wsIds   = [...new Set(activeClients.map(c => canonicalWorkspaceId(c.workspace_id, c.workspace_name)))];
    const wsNames = Object.fromEntries(activeClients.map(c => [canonicalWorkspaceId(c.workspace_id, c.workspace_name), c.workspace_name]));
    const dates   = serverDateList(start, end);

    // Read whatever daily stats are already in the performance cache — no blocking PlusVibe fetch.
    // Stale or missing dates get back-filled in the background; the client retries on partial=true.
    const today = serverDateString(new Date());
    const daily = {};
    for (const wsId of wsIds) for (const date of dates) {
      const key = `${wsId}|${date}`;
      daily[key] = performanceCache.dailyStats.get(key)?.data || { ...EMPTY_PERF_AGG };
    }

    // partial = the page should keep its spinner because data is genuinely
    // MISSING (not merely stale). A present-but-old entry still renders fine and
    // refreshes in the background — only a total absence of data should block.
    //
    // A workspace with zero entries across the whole window is a non-PlusVibe
    // client (33 in SQLite vs ~30 fetched) — those never get data, so they must
    // not count toward "missing" or the spinner would hang forever.
    const wsHasAnyData = {};
    for (const wsId of wsIds) {
      wsHasAnyData[wsId] = dates.some(d => performanceCache.dailyStats.has(`${wsId}|${d}`));
    }
    const anyDataAtAll = performanceCache.dailyStats.size > 0;
    // Missing = a workspace that DOES have some data in range but is missing a
    // specific day. If nothing has loaded yet at all, treat as missing (spinner).
    const missing = !anyDataAtAll || wsIds.some(wsId =>
      wsHasAnyData[wsId] && dates.some(date => !performanceCache.dailyStats.has(`${wsId}|${date}`))
    );
    // Stale (present but past TTL) — refresh in the background, do NOT block.
    const anyStale = wsIds.some(wsId =>
      wsHasAnyData[wsId] && dates.some(date => {
        const cached = performanceCache.dailyStats.get(`${wsId}|${date}`);
        const ttl = date === today ? PERF_TODAY_TTL_MS : PERF_OLD_TTL_MS;
        return cached && Date.now() - cached.savedAt > ttl;
      })
    );
    const partial = missing;
    if ((missing || anyStale) && !performanceCache.warming) {
      // Background refresh; warmPerformanceCache fetches daily stats first.
      warmPerformanceCache().catch(() => {});
    }

    // Build per-workspace aggregated stats + per-day series from the shared
    // helper so Stats and CM Performance always agree.
    const wsStats = computeWorkspaceStatsForRange(wsIds, start, end);

    // Recipient-provider split per workspace. Bison gives no provider dimension,
    // so we derive the Google/Microsoft/Other RATIO from the email_events we
    // captured in the window (provider_bucket), then apportion each workspace's
    // authoritative Bison totals (sent/replies/bounces/leads) by that ratio.
    // 'workspace' = bucket not yet classified → folded into 'other' for display.
    // Returns {} on error so the page still renders 'All' (byProvider just stays
    // absent for that ws, same as before).
    const providerMix = await buildProviderMixForRange(app.locals.pgDb, wsIds, start, end).catch(() => ({}));

    const workspaces = wsIds.map(wsId => {
      const t = wsStats[wsId].totals;
      // Look up the mix by the wsId directly; the mix is dual-keyed (canonical +
      // raw event ids) in buildProviderMixForRange, so this hits regardless of
      // which id form this client uses.
      const mix = providerMix[wsId];
      let byProvider;
      if (mix) {
        // Split each integer total across [google, outlook, other] by the mix
        // ratio using LARGEST-REMAINDER rounding, so the three parts ALWAYS sum
        // back to the workspace total exactly (independent Math.round made the
        // parts add up to more/less than the whole — e.g. 2 leads showing as
        // 1/1/1). shares are normalised first in case they don't sum to 1.
        const shares = [mix.google || 0, mix.outlook || 0, mix.other || 0];
        const sSum = shares[0] + shares[1] + shares[2];
        const norm = sSum > 0 ? shares.map(s => s / sSum) : [0, 0, 0];
        const apportion = (totalN) => {
          const T = Math.max(0, Math.round(totalN || 0));
          if (T === 0 || sSum === 0) return [0, 0, 0];
          const raw = norm.map(s => s * T);
          const floor = raw.map(Math.floor);
          let rem = T - floor.reduce((a, b) => a + b, 0);
          // Hand out the remaining units to the largest fractional remainders.
          const order = raw.map((v, i) => [v - floor[i], i]).sort((a, b) => b[0] - a[0]);
          for (let k = 0; k < order.length && rem > 0; k++, rem--) floor[order[k][1]]++;
          return floor;
        };
        // SENT: use Bison total when present; else the raw email_events counts.
        const sentParts = (t.sent || 0) > 0
          ? apportion(t.sent)
          : [mix.gSent || 0, mix.oSent || 0, mix.othSent || 0];
        const replyParts  = apportion(t.replies);
        const oooParts    = apportion(t.oooReplies);   // needed so Reply Rate ≠ Human RR per provider
        const posParts    = apportion(t.posReplies);
        const bounceParts = apportion(t.bounces);
        // LEADS: use the EXACT per-provider counts (each lead's real mx_provider),
        // not an estimate — leads are few and we know each one's true provider.
        // Leads whose provider is unknown are apportioned by the send ratio so the
        // parts still sum to the lead total.
        const lbp = wsStats[wsId].leadsByProvider || { email_google:0, email_outlook:0, email_other:0, unknown:0 };
        const leadParts = [lbp.email_google || 0, lbp.email_outlook || 0, lbp.email_other || 0];
        if (lbp.unknown > 0) {
          const extra = apportion(lbp.unknown);
          for (let i = 0; i < 3; i++) leadParts[i] += extra[i];
        }
        const pack = i => ({ sent: sentParts[i], replies: replyParts[i], oooReplies: oooParts[i], posReplies: posParts[i], bounces: bounceParts[i], leads: leadParts[i] });
        byProvider = { google: pack(0), outlook: pack(1), other: pack(2), coverage: mix.coverage };
      }
      return {
        workspace_id: wsId,
        name: wsNames[wsId] || wsId,
        totals: t,
        series: wsStats[wsId].series,
        byProvider, // undefined if no captured events → page shows it as syncing
      };
    }).filter(w => w.totals.sent > 0 || w.totals.leads > 0);

    workspaces.sort((a, b) => b.totals.replies - a.totals.replies);

    const payload = {
      workspaces,
      dates,
      start,
      end,
      partial,
      updatedAt: performanceCache.updatedAt,
    };
    // ?debug=1 — surface why the provider split may be empty: how many wsIds got
    // a mix, and a sample of mix keys vs wsIds, so we can see id mismatches.
    if (req.query.debug === '1') {
      const mixKeys = Object.keys(providerMix);
      const matched = wsIds.filter(id => providerMix[id]);
      payload._providerDebug = {
        wsIdCount: wsIds.length,
        mixKeyCount: mixKeys.length,
        matchedCount: matched.length,
        sampleWsIds: wsIds.slice(0, 5),
        sampleMixKeys: mixKeys.slice(0, 5),
        sampleMatched: matched.slice(0, 5).map(id => ({ id, mix: providerMix[id] })),
        unmatchedWsIds: wsIds.filter(id => !providerMix[id]).slice(0, 10),
      };
    }
    res.json(payload);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Verification-split analytics (safe vs catch-all performance) ──────────────
app.get('/api/verify-split', requireSession, async (req, res) => {
  const start = clampStartDate(String(req.query.start || ''));
  const end   = String(req.query.end   || '');
  if (!start || !end) return res.status(400).json({ error: 'start and end required (YYYY-MM-DD)' });
  try {
    const pgdb = app.locals.pgDb;

    // Primary source: contacts table. Filter to contacts last-emailed in the
    // period so we see who was actually sent to. email_count = all-time sends
    // to this contact; replies/bounces/leads are filtered to the same window.
    const summaryQ = `
      SELECT
        COALESCE(email_status, 'unknown')                                       AS email_status,
        COUNT(*)::int                                                            AS unique_contacts,
        SUM(COALESCE(email_count, 0))::bigint                                   AS sent,
        COUNT(*) FILTER (WHERE last_reply_at >= $1)::int                        AS replies,
        COUNT(*) FILTER (WHERE bounced_at    >= $1)::int                        AS bounces,
        COUNT(*) FILTER (WHERE marked_as_lead_at >= $1
                            OR (status = 'interested' AND last_reply_at >= $1))::int AS leads
      FROM contacts
      WHERE last_emailed_at >= $1
        AND last_emailed_at < ($2::date + interval '1 day')
      GROUP BY COALESCE(email_status, 'unknown')
      ORDER BY sent DESC
    `;

    // Daily trend: contacts first emailed each day, split by verification type
    const dailyQ = `
      SELECT
        last_emailed_at::date                                                    AS day,
        COALESCE(email_status, 'unknown')                                       AS email_status,
        COUNT(*)::int                                                            AS contacts,
        SUM(COALESCE(email_count, 0))::bigint                                   AS sent,
        COUNT(*) FILTER (WHERE last_reply_at >= last_emailed_at)::int           AS replies,
        COUNT(*) FILTER (WHERE bounced_at    >= last_emailed_at)::int           AS bounces
      FROM contacts
      WHERE last_emailed_at >= $1
        AND last_emailed_at < ($2::date + interval '1 day')
        AND email_status IN ('safe', 'safe_catchall')
      GROUP BY 1, 2
      ORDER BY 1, 2
    `;

    const [{ rows: summary }, { rows: daily }] = await Promise.all([
      pgdb.query(summaryQ, [start, end]),
      pgdb.query(dailyQ,   [start, end]),
    ]);

    res.json({ summary, daily, start, end });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

