// ─────────────────────────────────────────────────────────────────────
// Gateway deliverability — reply/lead/bounce per inbound email gateway
// (Mimecast, Proofpoint, Barracuda, Cisco, Google, Microsoft, ...).
//
// The gateway is NOT stored: contacts.mx_provider only buckets to
// google/outlook/other. scripts/gateway-analysis.js re-resolves MX into the
// gateway_mx_cache table; this endpoint joins that cache to live contact facts.
//   - sent  = contacts.emailed_workspaces <> '{}'  (NOT email_events 'sent',
//             whose webhook coverage is incomplete)
//   - reply = email_events by lead_email, counted DISTINCT (rows are dup'd)
//   - OOO   = email_events.raw->>'label' OUT_OF_OFFICE/AUTOMATIC_REPLY
app.get('/api/gateway-analysis', requireSession, async (req, res) => {
  try {
    const pgdb = req.app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const { rows } = await pgdb.query(`
      WITH sent AS (
        SELECT c.id,
               lower(split_part(c.email,'@',2)) AS domain,
               lower(c.email)                   AS email,
               c.bounced_at
        FROM contacts c
        WHERE COALESCE(c.emailed_workspaces,'{}'::jsonb) <> '{}'::jsonb
          AND c.email LIKE '%@%'
      ),
      ev AS (
        SELECT lower(lead_email) AS email,
               bool_or(event_type IN ('reply','positive_reply','all_email_replies')) AS replied,
               bool_or(event_type IN ('reply','positive_reply','all_email_replies')
                       AND COALESCE(raw->>'label','') NOT IN ('OUT_OF_OFFICE','AUTOMATIC_REPLY')) AS replied_substantive,
               bool_or(event_type = 'lead'
                       OR raw->>'label' IN ('LEAD','INTERESTED_NONLEAD'))            AS is_lead,
               -- Bounce class — regex runs ONLY on bounce rows (the inner guard
               -- short-circuits for replies/leads, so the costly regex isn't run
               -- on the 49k+ reply rows). block > hard precedence handled below.
               bool_or(event_type = 'bounce' AND raw->>'msg' IS NOT NULL
                       AND lower(raw->>'msg') ~ '${BOUNCE_HARD_RE}'
                       AND NOT lower(raw->>'msg') ~ '${BOUNCE_BLOCK_RE}') AS bounce_hard,
               bool_or(event_type = 'bounce' AND raw->>'msg' IS NOT NULL
                       AND lower(raw->>'msg') ~ '${BOUNCE_BLOCK_RE}') AS bounce_block,
               bool_or(event_type = 'bounce' AND raw->>'msg' IS NOT NULL
                       AND lower(raw->>'msg') ~ '${BOUNCE_SOFT_RE}'
                       AND NOT lower(raw->>'msg') ~ '${BOUNCE_BLOCK_RE}') AS bounce_soft
        FROM email_events
        WHERE event_type <> 'sent'
        GROUP BY 1
      ),
      -- Pre-resolve each emailed contact to a gateway FIRST (cheap index join),
      -- so the heavy ev LEFT JOIN only runs against gateway-matched contacts —
      -- not the full ~1M emailed set. This is what keeps it under the timeout.
      sent_gw AS (
        SELECT s.email, s.domain, g.gateway
        FROM sent s
        JOIN gateway_mx_cache g ON g.domain = s.domain
      ),
      per_contact AS (
        SELECT COALESCE(sg.gateway,'NO MX / unresolved') AS gateway,
               sg.domain,
               e.replied,
               e.replied_substantive,
               e.is_lead,
               e.bounce_hard,
               (e.bounce_block AND NOT e.bounce_hard)                       AS bounce_block,
               (e.bounce_soft AND NOT e.bounce_hard AND NOT e.bounce_block) AS bounce_soft
        FROM sent_gw sg
        LEFT JOIN ev e ON e.email = sg.email
      )
      SELECT gateway,
             count(DISTINCT domain)                  AS domains,
             count(*)                                 AS sent,
             count(*) FILTER (WHERE replied)          AS replied,
             count(*) FILTER (WHERE replied_substantive) AS replied_no_ooo,
             count(*) FILTER (WHERE is_lead)          AS leads,
             count(*) FILTER (WHERE bounce_hard)      AS bounced_hard,
             count(*) FILTER (WHERE bounce_block)     AS bounced_block,
             count(*) FILTER (WHERE bounce_soft)      AS bounced_soft
      FROM per_contact
      GROUP BY gateway
      ORDER BY sent DESC`);

    const gateways = rows.map(r => {
      const sent = Number(r.sent);
      const replied = Number(r.replied);
      const repliedNoOoo = Number(r.replied_no_ooo);
      const leads = Number(r.leads);
      const hard = Number(r.bounced_hard);
      const block = Number(r.bounced_block);
      const soft = Number(r.bounced_soft);
      return {
        gateway: r.gateway,
        domains: Number(r.domains),
        sent,
        replyRate:      sent ? (100 * replied) / sent : 0,
        replyRateNoOoo: sent ? (100 * repliedNoOoo) / sent : 0,
        leadRate:       sent ? (100 * leads) / sent : 0,
        rtl:            sent ? (1000 * leads) / sent : 0,  // leads per 1,000 sent
        // 3-way bounce split: hard=dead address, block=gateway rejected sender, soft=temporary
        hardRate:       sent ? (100 * hard) / sent : 0,
        blockRate:      sent ? (100 * block) / sent : 0,
        softRate:       sent ? (100 * soft) / sent : 0,
        replied, leads,
      };
    });

    // Coverage = of the domains we've SENT to, how many are resolved. (The cache
    // also holds never-emailed domains from the full-DB scan, so counting the
    // whole cache would exceed 100%.)
    const cov = await pgdb.query(`
      WITH sent_domains AS (
        SELECT DISTINCT lower(split_part(email,'@',2)) AS domain
        FROM contacts
        WHERE COALESCE(emailed_workspaces,'{}'::jsonb) <> '{}'::jsonb
          AND email LIKE '%@%'
      )
      SELECT
        (SELECT count(*) FROM sent_domains s JOIN gateway_mx_cache g ON g.domain = s.domain) AS resolved,
        (SELECT count(*) FROM sent_domains) AS total`);

    // Diagnostic: how the cache is classified overall (so we can tell "empty
    // page" = nothing resolved vs = read-join mismatch). Cheap GROUP BY.
    let cacheBreakdown = [];
    try {
      const cb = await pgdb.query(`SELECT gateway, count(*)::int AS n FROM gateway_mx_cache GROUP BY gateway ORDER BY n DESC LIMIT 20`);
      cacheBreakdown = cb.rows;
    } catch {}

    res.json({
      gateways,
      coverage: {
        resolved: Number(cov.rows[0] && cov.rows[0].resolved || 0),
        total:    Number(cov.rows[0] && cov.rows[0].total || 0),
      },
      cacheBreakdown,
    });
  } catch (err) {
    console.error('[gateway-analysis]', err.message);
    res.status(500).json({ error: 'Database error' });
  }
});

app.get('/gateway-analysis',      (req, res) => res.sendFile(path.join(__dirname, 'gateway-analysis.html')));
app.get('/gateway-analysis.html', (req, res) => res.sendFile(path.join(__dirname, 'gateway-analysis.html')));

// Classify an MX host list into a gateway name (Mimecast/Proofpoint/Barracuda/…)
// — same patterns as scripts/gateway-analysis.js, kept here so the API can
// populate gateway_mx_cache without the CLI (which needs `dig`, absent in prod).
const GATEWAY_PATTERNS = [
  ['Mimecast',           [/\.mimecast\./, /mimecast\.com$/, /mimecast\.co\.za/]],
  ['Proofpoint',         [/pphosted\.com$/, /ppe-hosted\.com$/, /\.pphosted\./]],
  ['Barracuda',          [/barracudanetworks\.com$/, /barracuda\.com$/, /\.ess\.barracuda/]],
  ['Cisco Ironport',     [/iphmx\.com$/, /\.cisco\.com$/, /ironport/]],
  ['Forcepoint/Mailcontrol', [/mailcontrol\.com$/, /forcepoint/]],
  ['Sophos',             [/sophos\.com$/, /\.hydra\.sophos/]],
  ['Trend Micro',        [/trendmicro\.com$/, /\.tmes\.trendmicro/]],
  ['FortiMail',          [/fortimail/, /fortinet\.com$/]],
  ['Microsoft 365',      [/\.mail\.protection\.outlook\.com$/, /\.olc\.protection\.outlook\.com$/, /outlook\.com$/, /\.protection\.outlook/]],
  ['Google Workspace',   [/\.google\.com$/, /googlemail\.com$/, /aspmx\.l\.google/, /\.googlemail\./, /psmtp\.com$/]],
  ['Zoho',               [/zoho\.com$/, /zohomail/]],
  ['Fastmail',           [/messagingengine\.com$/, /fastmail/]],
];
function classifyGatewayHosts(mxHosts) {
  if (!mxHosts || !mxHosts.length) return 'NO MX / unresolved';
  const lower = mxHosts.map(h => String(h).toLowerCase());
  const joined = lower.join(' ');
  for (const [name, patterns] of GATEWAY_PATTERNS) {
    if (patterns.some(p => lower.some(h => p.test(h)) || p.test(joined))) return name;
  }
  return 'Other / self-hosted';
}

// Populate gateway_mx_cache by resolving MX (via Node DNS, no `dig`) for the
// domains we actually send to. ?blocksOnly=1 prioritises domains that have
// BLOCK-bounced us (the "who's rejecting us" view). ?max=N caps the run.
// Idempotent — re-run to fill in more. This is what the Gateway page needs to
// stop showing "No gateway data yet".
app.post('/api/gateway-analysis/resolve', requireAdmin, async (req, res) => {
  const pgdb = app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
  const max        = Math.max(1, Math.min(20000, parseInt(req.query.max, 10) || 5000));
  const blocksOnly = req.query.blocksOnly === '1';
  const { isBlock } = bounceClassExprs("raw->>'msg'");
  try {
    await pgdb.query(`CREATE TABLE IF NOT EXISTS gateway_mx_cache (
      domain TEXT PRIMARY KEY, mx_hosts TEXT[], gateway TEXT, resolved_at TIMESTAMP DEFAULT NOW())`);

    // Domains to resolve. Skip ones ALREADY classified (gateway known), but DO
    // re-resolve ones missing or stuck on 'NO MX / unresolved' (an old CLI run
    // may have inserted them unclassified — excluding those gave "0 domains").
    const resolvedSet = `(SELECT domain FROM gateway_mx_cache WHERE gateway IS NOT NULL AND gateway NOT IN ('NO MX / unresolved',''))`;
    const domQ = blocksOnly
      ? `SELECT DISTINCT lower(split_part(lead_email,'@',2)) AS domain
           FROM email_events
          WHERE event_type='bounce' AND lead_email LIKE '%@%' AND (${isBlock})
            AND lower(split_part(lead_email,'@',2)) NOT IN ${resolvedSet}
          LIMIT $1`
      : `SELECT DISTINCT lower(split_part(email,'@',2)) AS domain
           FROM contacts
          WHERE COALESCE(emailed_workspaces,'{}'::jsonb) <> '{}'::jsonb AND email LIKE '%@%'
            AND lower(split_part(email,'@',2)) NOT IN ${resolvedSet}
          LIMIT $1`;
    const { rows } = await pgdb.query(domQ, [max]);
    const domains = rows.map(r => r.domain).filter(Boolean);

    const dnsP = require('dns').promises;
    let resolved = 0, failed = 0;
    const byGateway = {};
    const CONC = 20;
    let cursor = 0;
    const worker = async () => {
      while (cursor < domains.length) {
        const domain = domains[cursor++];
        let hosts = [];
        try { const recs = await dnsP.resolveMx(domain); hosts = recs.sort((a,b)=>a.priority-b.priority).map(r=>r.exchange).filter(Boolean); }
        catch { hosts = []; }
        const gw = classifyGatewayHosts(hosts);
        if (hosts.length) resolved++; else failed++;
        byGateway[gw] = (byGateway[gw] || 0) + 1;
        try {
          await pgdb.query(
            `INSERT INTO gateway_mx_cache (domain, mx_hosts, gateway, resolved_at)
             VALUES ($1,$2,$3,NOW())
             ON CONFLICT (domain) DO UPDATE SET mx_hosts=EXCLUDED.mx_hosts, gateway=EXCLUDED.gateway, resolved_at=NOW()`,
            [domain, hosts, gw]
          );
        } catch { /* per-row, non-fatal */ }
      }
    };
    await Promise.all(Array.from({ length: CONC }, worker));
    res.json({ ok: true, attempted: domains.length, resolved, failed, byGateway, blocksOnly });
  } catch (err) {
    console.error('[gateway-resolve]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// workspace_id -> display name. There is no `clients` table in Postgres; the
// only pg source that carries workspace_name is domain_health (1 row/domain).
// Pick the most recent non-empty name per workspace. Returns {} on any error
// (callers fall back to the raw workspace_id), so a name miss never 500s.
async function workspaceNameMap(pgdb) {
  if (!pgdb) return {};
  try {
    const { rows } = await pgdb.query(`
      SELECT DISTINCT ON (workspace_id) workspace_id, workspace_name
      FROM domain_health
      WHERE workspace_id IS NOT NULL AND workspace_id <> ''
        AND COALESCE(workspace_name,'') <> ''
      ORDER BY workspace_id, last_checked DESC NULLS LAST`);
    return Object.fromEntries(rows.map(r => [r.workspace_id, r.workspace_name]));
  } catch (e) {
    console.warn('[workspaceNameMap]', e.message);
    return {};
  }
}

// ─────────────────────────────────────────────────────────────────────
// Bounce Analyzer — detect list-quality + sender-reputation issues sooner
// ─────────────────────────────────────────────────────────────────────
// Every bounce in email_events is classified 3-way (hard / block / soft) via
// the shared bounce-classify.js helper — the SAME regexes /api/gateway-analysis
// uses. This endpoint slices those bounces the ways the analyzer page needs:
//   - summary    : 3-way totals + this-week-vs-last-week deltas (early warning)
//   - byClient   : bounce rate + 3-way split per workspace (who has a problem)
//   - byCampaign : same, per campaign
//   - hardDomains/hardAddresses : list-quality triage (suppression candidates)
//   - senderHealth : BLOCK bounces grouped by sender_email (which of OUR
//                    mailboxes are being filtered) + the rejecting pattern
//   - series     : daily hard/block/soft for the trend chart
//   - explorer   : paginated raw bounce rows (recipient/sender/campaign/msg)
//
// COVERAGE CAVEAT: email_events bounce rows are webhook-partial, so absolute
// counts under-represent reality. The classification (the *ratio* of hard:block:
// soft) is the reliable signal — treat totals as directional. The page also
// pulls Bison's bounced totals separately (see /api/bounce-analysis/reconcile)
// to show how much we're missing.
//
// `days` query param (default 30, max 180) bounds the window via event_at.
app.get('/api/bounce-analysis', requireSession, async (req, res) => {
  try {
    const pgdb = req.app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const days = Math.min(180, Math.max(1, parseInt(req.query.days, 10) || 30));
    // Classify ONCE inside the CTE (selecting from email_events, so bare `raw`,
    // NOT be.raw — be doesn't exist yet while it's being defined). Every outer
    // query then filters on the resulting `klass` column instead of re-running
    // regexes with a be.-prefix that would fail "missing FROM-clause entry".
    const classCase = bounceClassCase("raw->>'msg'");

    // Base CTE: every bounce event in the window, pre-classified once.
    // Domain is derived straight from lead_email (recipient_domain is an
    // ALTER-added column we avoid relying on here).
    const base = `
      WITH be AS (
        SELECT workspace_id, campaign_id, campaign_name, sender_email,
               lower(lead_email) AS lead_email,
               lower(split_part(lead_email,'@',2)) AS domain,
               event_at, raw,
               ${classCase} AS klass
        FROM email_events
        WHERE event_type = 'bounce'
          AND event_at >= NOW() - ($1 || ' days')::interval
      )`;

    // Outer queries filter on the pre-computed klass (hard|block|soft|unclassified).
    const isHard  = `klass = 'hard'`;
    const isBlock = `klass = 'block'`;
    const isSoft  = `klass = 'soft'`;

    // Helper SELECT pieces for the 3-way FILTER counts (reused across queries).
    const counts = `
      count(*)::int                                  AS total,
      count(*) FILTER (WHERE ${isHard})::int         AS hard,
      count(*) FILTER (WHERE ${isBlock})::int        AS block,
      count(*) FILTER (WHERE ${isSoft})::int         AS soft,
      count(*) FILTER (WHERE klass = 'unclassified')::int AS unclassified`;

    const param = [String(days)];

    // ── Summary: window totals + this-week vs last-week deltas ──
    const summaryQ = pgdb.query(`${base}
      SELECT ${counts},
             count(DISTINCT lead_email)::int AS addresses,
             count(DISTINCT domain)::int     AS domains,
             count(*) FILTER (WHERE event_at >= NOW() - interval '7 days')::int                                AS last7_total,
             count(*) FILTER (WHERE event_at >= NOW() - interval '7 days' AND ${isHard})::int                  AS last7_hard,
             count(*) FILTER (WHERE event_at <  NOW() - interval '7 days' AND event_at >= NOW() - interval '14 days')::int                AS prev7_total,
             count(*) FILTER (WHERE event_at <  NOW() - interval '7 days' AND event_at >= NOW() - interval '14 days' AND ${isHard})::int  AS prev7_hard
      FROM be`, param);

    // ── Daily series (for the trend chart) ──
    const seriesQ = pgdb.query(`${base}
      SELECT to_char(event_at::date,'YYYY-MM-DD') AS date,
             ${counts}
      FROM be GROUP BY 1 ORDER BY 1`, param);

    // ── Per-client split (names resolved in JS — no `clients` table in pg) ──
    const byClientQ = pgdb.query(`${base}
      SELECT be.workspace_id,
             ${counts}
      FROM be
      GROUP BY be.workspace_id
      ORDER BY total DESC`, param);

    // ── Per-campaign split ──
    const byCampaignQ = pgdb.query(`${base}
      SELECT be.workspace_id,
             COALESCE(NULLIF(be.campaign_name,''), be.campaign_id, '(unknown)') AS campaign,
             ${counts}
      FROM be
      GROUP BY be.workspace_id, be.campaign_name, be.campaign_id
      ORDER BY hard DESC, total DESC
      LIMIT 100`, param);

    // ── List-quality triage: top HARD-bounce domains + addresses ──
    const hardDomainsQ = pgdb.query(`${base}
      SELECT domain, count(*)::int AS hard
      FROM be WHERE ${isHard} AND domain <> ''
      GROUP BY domain ORDER BY hard DESC LIMIT 25`, param);

    const hardAddressesQ = pgdb.query(`${base}
      SELECT lead_email AS email,
             max(be.campaign_name) AS campaign,
             max(be.raw->>'msg')   AS msg
      FROM be WHERE ${isHard} AND lead_email <> ''
      GROUP BY lead_email ORDER BY max(event_at) DESC LIMIT 100`, param);

    // ── Sender/infra health: BLOCK bounces per sending mailbox ──
    const senderHealthQ = pgdb.query(`${base}
      SELECT COALESCE(NULLIF(sender_email,''),'(unknown sender)') AS sender,
             count(*) FILTER (WHERE ${isBlock})::int AS block,
             count(*) FILTER (WHERE ${isHard})::int  AS hard,
             count(*)::int                            AS total,
             max(be.raw->>'msg') FILTER (WHERE ${isBlock}) AS sample_msg
      FROM be
      GROUP BY sender
      HAVING count(*) FILTER (WHERE ${isBlock}) > 0
      ORDER BY block DESC LIMIT 50`, param);

    const [summary, series, byClient, byCampaign, hardDomains, hardAddresses, senderHealth, nameOf] =
      await Promise.all([summaryQ, seriesQ, byClientQ, byCampaignQ, hardDomainsQ, hardAddressesQ, senderHealthQ, workspaceNameMap(pgdb)]);

    const named = (r) => ({ ...r, client: nameOf[r.workspace_id] || r.workspace_id });
    const s = summary.rows[0] || {};
    const wow = (cur, prev) => prev > 0 ? (100 * (cur - prev) / prev) : (cur > 0 ? null : 0); // null = "new, no baseline"

    res.json({
      days,
      summary: {
        total: s.total||0, hard: s.hard||0, block: s.block||0, soft: s.soft||0, unclassified: s.unclassified||0,
        addresses: s.addresses||0, domains: s.domains||0,
        last7:  { total: s.last7_total||0, hard: s.last7_hard||0 },
        prev7:  { total: s.prev7_total||0, hard: s.prev7_hard||0 },
        wowTotal: wow(s.last7_total||0, s.prev7_total||0),
        wowHard:  wow(s.last7_hard||0,  s.prev7_hard||0),
      },
      series:        series.rows,
      byClient:      byClient.rows.map(named),
      byCampaign:    byCampaign.rows.map(named),
      hardDomains:   hardDomains.rows,
      hardAddresses: hardAddresses.rows,
      senderHealth:  senderHealth.rows,
    });
  } catch (err) {
    console.error('[bounce-analysis]', err.message);
    res.status(500).json({ error: 'Database error' });
  }
});

// Raw bounce explorer — paginated, searchable. Separate endpoint so the table
// can page/filter without re-running the whole analyzer aggregation.
//   ?days=30&q=<substring on email/sender/msg>&klass=hard|block|soft&page=1
app.get('/api/bounce-analysis/explorer', requireSession, async (req, res) => {
  try {
    const pgdb = req.app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const days  = Math.min(180, Math.max(1, parseInt(req.query.days, 10) || 30));
    const page  = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit = 50;
    const q     = (req.query.q || '').toString().trim().toLowerCase();
    const klass = ['hard','block','soft','unclassified'].includes(req.query.klass) ? req.query.klass : null;
    const classCase = bounceClassCase("raw->>'msg'");

    const where = [`event_type = 'bounce'`, `event_at >= NOW() - ($1 || ' days')::interval`];
    const params = [String(days)];
    if (q) {
      params.push('%' + q + '%');
      where.push(`(lower(lead_email) LIKE $${params.length} OR lower(COALESCE(sender_email,'')) LIKE $${params.length} OR lower(COALESCE(raw->>'msg','')) LIKE $${params.length})`);
    }
    if (klass) {
      params.push(klass);
      where.push(`(${classCase}) = $${params.length}`);
    }
    const whereSql = where.join(' AND ');

    const total = await pgdb.query(`SELECT count(*)::int AS n FROM email_events WHERE ${whereSql}`, params);
    const rows = await pgdb.query(`
      SELECT to_char(event_at,'YYYY-MM-DD HH24:MI') AS at,
             lower(lead_email) AS email,
             sender_email AS sender,
             COALESCE(NULLIF(campaign_name,''), campaign_id) AS campaign,
             (${classCase}) AS klass,
             raw->>'msg' AS msg
      FROM email_events
      WHERE ${whereSql}
      ORDER BY event_at DESC
      LIMIT ${limit} OFFSET ${(page-1)*limit}`, params);

    res.json({ page, limit, total: total.rows[0]?.n || 0, rows: rows.rows });
  } catch (err) {
    console.error('[bounce-explorer]', err.message);
    res.status(500).json({ error: 'Database error' });
  }
});

app.get('/bounce-analysis',      (req, res) => res.sendFile(path.join(__dirname, 'bounce-analysis.html')));
app.get('/bounce-analysis.html', (req, res) => res.sendFile(path.join(__dirname, 'bounce-analysis.html')));

// One-time (re-runnable) sweep: retire every address that has ALREADY hard-
// bounced. The live webhook now auto-suppresses NEW hard bounces, but legacy
// dead contacts already sitting in active campaigns keep sending until swept.
// This finds them in email_events (validated classifier), marks the contact
// invalid + do_not_contact, and pushes each to BISON's blocklist so the live
// campaign stops too. Idempotent — safe to run repeatedly.
//   ?dry=1            → count only, change nothing
//   ?days=365         → window (default all-time)
//   ?skipBison=1      → DB suppression only, don't touch Bison blocklist
app.post('/api/admin/suppress-bounced', requireAdmin, async (req, res) => {
  const pgdb = req.app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
  const dry      = req.query.dry === '1' || req.query.dry === 'true';
  const skipBison= req.query.skipBison === '1';
  const days     = parseInt(req.query.days, 10) || 0; // 0 = all-time
  const { isHard } = bounceClassExprs("raw->>'msg'");

  try {
    const windowSql = days > 0 ? `AND event_at >= NOW() - (${days} || ' days')::interval` : '';
    // Distinct hard-bounced (email, workspace_id) pairs. Keep workspace so we can
    // blocklist on the right Bison team.
    const { rows } = await pgdb.query(`
      SELECT DISTINCT lower(lead_email) AS email, workspace_id
      FROM email_events
      WHERE event_type = 'bounce' AND lead_email <> '' ${windowSql}
        AND (${isHard})
    `);
    const emails = [...new Set(rows.map(r => r.email))];

    if (dry) {
      // How many of these are not yet suppressed?
      let notYet = 0;
      if (emails.length) {
        const r = await pgdb.query(
          `SELECT count(*)::int AS n FROM contacts
           WHERE lower(email) = ANY($1) AND COALESCE(do_not_contact,false) = false`,
          [emails]
        );
        notYet = r.rows[0]?.n || 0;
      }
      return res.json({ dry: true, hardBouncedAddresses: emails.length, notYetSuppressed: notYet, wouldBlocklistOnBison: !skipBison });
    }

    // 1) Suppress in our DB (batched ANY()).
    let suppressed = 0;
    if (emails.length) {
      const r = await pgdb.query(
        `UPDATE contacts
           SET email_status='invalid', bounce_type='hard',
               bounced_at = COALESCE(bounced_at, CURRENT_TIMESTAMP),
               do_not_contact = true, updated_at = CURRENT_TIMESTAMP
         WHERE lower(email) = ANY($1) AND COALESCE(do_not_contact,false) = false`,
        [emails]
      );
      suppressed = r.rowCount || 0;
    }

    // 2) Push to Bison blocklist. A dead address is dead for EVERY client, so by
    // default we blocklist each bounced email in EVERY workspace (?allWorkspaces=0
    // to only block the workspace it bounced in). Bison's token is stateful +
    // serialized, so this runs as one controlled off-line pass (not on the live
    // webhook path) — that's why the sweep is the right place for the fan-out.
    let blocklisted = 0, pvErrors = 0;
    if (!skipBison) {
      const allWorkspaces = req.query.allWorkspaces !== '0';
      const targets = allWorkspaces ? PV_WORKSPACES.map(t => t.pv) : null;
      if (allWorkspaces) {
        const seen = new Set();
        for (const email of emails) {
          for (const wsId of targets) {
            const k = email + '|' + wsId;
            if (seen.has(k)) continue; seen.add(k);
            try { await pvApi('/blocklist/add', { method: 'POST', wsId, body: { value: email, type: 'email' } }); blocklisted++; }
            catch { pvErrors++; }
          }
        }
      } else {
        const seen = new Set();
        for (const r of rows) {
          const k = r.email + '|' + r.workspace_id;
          if (seen.has(k) || !r.workspace_id) continue; seen.add(k);
          try { await pvApi('/blocklist/add', { method: 'POST', wsId: r.workspace_id, body: { value: r.email, type: 'email' } }); blocklisted++; }
          catch { pvErrors++; }
        }
      }
    }

    res.json({ ok: true, hardBouncedAddresses: emails.length, suppressed, blocklisted, pvErrors, skipBison, allWorkspaces: req.query.allWorkspaces !== '0' });
  } catch (err) {
    console.error('[suppress-bounced]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Post a plain-text message to the ops Slack channel via the bot token.
// Best-effort: resolves with {ok} and never throws to the caller.
function postBounceAlertToSlack(text) {
  return new Promise((resolve) => {
    const token = process.env.SLACK_BOT_TOKEN;
    const channel = process.env.SLACK_ALERT_CHANNEL_ID || process.env.SLACK_CHANNEL_ID;
    if (!token || !channel) return resolve({ ok: false, skipped: 'no SLACK_BOT_TOKEN/CHANNEL' });
    const https = require('https');
    const data = JSON.stringify({ channel, text, unfurl_links: false });
    const req = https.request({
      hostname: 'slack.com', path: '/api/chat.postMessage', method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) },
    }, r => { let b=''; r.on('data',d=>b+=d); r.on('end',()=>{ try { resolve(JSON.parse(b)); } catch { resolve({ ok:false }); } }); });
    req.on('error', () => resolve({ ok: false }));
    req.write(data); req.end();
  });
}

// Early-warning bounce alert — the "detect issues sooner" payoff. Computes each
// client's HARD-bounce rate (dead-address signal) over a recent window and flags
// clients that are BOTH above an absolute floor AND rising vs their prior
// baseline, so a degrading list is caught before deliverability tanks.
//
// Designed to run from cron (cron-job.org) like the needs-reply backfill:
//   GET /api/cron/bounce-alert?secret=$CRON_SECRET
// Guarded by CRON_SECRET when set; also callable by an admin session for manual
// runs / dashboard "test alert". Params (all optional):
//   recent=3   baseline=14   minHard=10   floorRate=0.02   risePct=50   dry=1
// dry=1 computes + returns flagged clients WITHOUT posting to Slack.
app.get('/api/cron/bounce-alert', async (req, res) => {
  // Auth: CRON_SECRET (if configured) OR an admin/manager session (manual run).
  const secret = process.env.CRON_SECRET;
  const s = decodeSession(req);
  const okSession = s?.role === 'admin' || s?.role === 'manager' || req.headers['x-admin-key'] === ADMIN_KEY;
  const okSecret = secret && req.query.secret === secret;
  if (!okSecret && !okSession) return res.status(403).json({ error: 'forbidden (CRON_SECRET or sign in)' });

  try {
    const pgdb = req.app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const recent    = Math.min(30, Math.max(1, parseInt(req.query.recent, 10)   || 3));
    const baseline  = Math.min(90, Math.max(recent + 1, parseInt(req.query.baseline, 10) || 14));
    const minHard   = Math.max(1, parseInt(req.query.minHard, 10) || 10);
    const floorRate = Math.max(0, parseFloat(req.query.floorRate) || 0.02);
    const risePct   = Math.max(0, parseFloat(req.query.risePct)   || 50);
    const dry       = req.query.dry === '1' || req.query.dry === 'true';
    const { isHard } = bounceClassExprs("raw->>'msg'");

    // Per-workspace hard counts + total bounces in the recent window and the
    // prior baseline window. We don't have reliable per-day SENT in email_events
    // for every client, so the "rate" here is hard / total-bounces (the share of
    // bounces that are dead addresses) — a clean, sent-independent list-quality
    // signal. Combined with an absolute hard-count floor (minHard) it avoids
    // firing on tiny samples.
    const { rows } = await pgdb.query(`
      WITH b AS (
        SELECT workspace_id,
               (event_at >= NOW() - ($1 || ' days')::interval) AS is_recent,
               (event_at <  NOW() - ($1 || ' days')::interval
                AND event_at >= NOW() - ($2 || ' days')::interval) AS is_base,
               (${isHard}) AS hard
        FROM email_events
        WHERE event_type = 'bounce'
          AND event_at >= NOW() - ($2 || ' days')::interval
      )
      SELECT workspace_id,
             count(*) FILTER (WHERE is_recent)              ::int AS recent_total,
             count(*) FILTER (WHERE is_recent AND hard)     ::int AS recent_hard,
             count(*) FILTER (WHERE is_base)                ::int AS base_total,
             count(*) FILTER (WHERE is_base AND hard)       ::int AS base_hard
      FROM b GROUP BY workspace_id`, [String(recent), String(baseline)]);

    // Resolve names. There is no `clients` table in Postgres — names live in
    // domain_health (one row per domain, carries workspace_name). Pick the most
    // recent non-empty name per workspace; fall back to the id where unknown.
    const nameOf = await workspaceNameMap(pgdb);

    const flagged = [];
    for (const r of rows) {
      const recentRate = r.recent_total ? r.recent_hard / r.recent_total : 0;
      const baseRate   = r.base_total   ? r.base_hard   / r.base_total   : 0;
      const rise = baseRate > 0 ? (100 * (recentRate - baseRate) / baseRate) : (recentRate > 0 ? Infinity : 0);
      if (r.recent_hard >= minHard && recentRate >= floorRate && rise >= risePct) {
        flagged.push({
          workspace_id: r.workspace_id,
          client: nameOf[r.workspace_id] || r.workspace_id,
          recentHard: r.recent_hard, recentTotal: r.recent_total,
          recentRate: +(recentRate * 100).toFixed(1),
          baseRate: +(baseRate * 100).toFixed(1),
          risePct: rise === Infinity ? null : Math.round(rise),
        });
      }
    }
    flagged.sort((a, b) => b.recentHard - a.recentHard);

    let posted = null;
    if (flagged.length && !dry) {
      const lines = flagged.slice(0, 15).map(f =>
        `• *${f.client}* — ${f.recentHard} hard bounces (${f.recentRate}% of bounces, was ${f.baseRate}%${f.risePct!=null?`, +${f.risePct}%`:', new'}) in last ${recent}d`);
      const text = `:warning: *Bounce early-warning* — ${flagged.length} client(s) with rising hard-bounce (dead-address) rates:\n${lines.join('\n')}\n_Hard bounces signal a degrading list. Review in the Bounce Analyzer._`;
      posted = await postBounceAlertToSlack(text);
    }

    res.json({ window: { recent, baseline }, thresholds: { minHard, floorRate, risePct }, flagged, posted, dry });
  } catch (err) {
    console.error('[bounce-alert]', err.message);
    res.status(500).json({ error: 'Database error' });
  }
});

// Daily hard/block/soft bounce breakdown per workspace, for the Stats + Mailboxes
// overlays. ADDITIVE: the authoritative total bounce count on Stats still comes
// from Bison (performanceCache.dailyStats); this only adds the *split* from our
// email_events classification, which the page layers on top. A missing entry
// just means no overlay for that day/workspace — it never alters existing stats.
//   ?start=YYYY-MM-DD&end=YYYY-MM-DD  (defaults to last 30 days)
// Returns { byWorkspace: { wsId: { 'YYYY-MM-DD': {hard,block,soft,total} } },
//           all: { 'YYYY-MM-DD': {...} } }
app.get('/api/stats/bounce-breakdown', requireSession, async (req, res) => {
  try {
    const pgdb = req.app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const start = /^\d{4}-\d{2}-\d{2}$/.test(req.query.start || '') ? req.query.start : null;
    const end   = /^\d{4}-\d{2}-\d{2}$/.test(req.query.end || '')   ? req.query.end   : null;
    const { isHard, isBlock, isSoft } = bounceClassExprs("raw->>'msg'");

    const where = [`event_type = 'bounce'`];
    const params = [];
    if (start) { params.push(start); where.push(`event_at::date >= $${params.length}`); }
    if (end)   { params.push(end);   where.push(`event_at::date <= $${params.length}`); }
    if (!start && !end) where.push(`event_at >= NOW() - interval '30 days'`);

    const { rows } = await pgdb.query(`
      SELECT workspace_id,
             to_char(event_at::date,'YYYY-MM-DD') AS date,
             count(*) FILTER (WHERE ${isHard})::int  AS hard,
             count(*) FILTER (WHERE ${isBlock})::int AS block,
             count(*) FILTER (WHERE ${isSoft})::int  AS soft,
             count(*)::int                            AS total
      FROM email_events
      WHERE ${where.join(' AND ')}
      GROUP BY workspace_id, event_at::date
      ORDER BY date`, params);

    const byWorkspace = {}, all = {};
    for (const r of rows) {
      const cell = { hard: r.hard, block: r.block, soft: r.soft, total: r.total };
      (byWorkspace[r.workspace_id] = byWorkspace[r.workspace_id] || {})[r.date] = cell;
      const a = all[r.date] = all[r.date] || { hard: 0, block: 0, soft: 0, total: 0 };
      a.hard += r.hard; a.block += r.block; a.soft += r.soft; a.total += r.total;
    }
    res.json({ byWorkspace, all });
  } catch (err) {
    console.error('[stats-bounce-breakdown]', err.message);
    res.status(500).json({ error: 'Database error' });
  }
});

// Returns three domain sets for the stats page mailbox-set filter:
//   blacklisted  — domains with at least one DBL hit in domain_health
//   clean        — domains in domain_health with no DBL hit
//   winnr        — hardcoded Winnr client sending domains
// Workspaces on the stats page are bucketed client-side by matching
// their sender_email domains against these sets.
app.get('/api/stats/domain-sets', requireSession, async (req, res) => {
  try {
    const pgdb = req.app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const { rows } = await pgdb.query(
      `SELECT domain, workspace_id,
              (blacklists IS NOT NULL AND jsonb_array_length(blacklists::jsonb) > 0) AS is_blacklisted
       FROM domain_health
       WHERE ignored_at IS NULL
       ORDER BY domain`
    );
    const blacklisted = rows.filter(r => r.is_blacklisted).map(r => r.domain);
    const clean       = rows.filter(r => !r.is_blacklisted).map(r => r.domain);
    // Map domain → workspace_id for client-side bucketing
    const domainWs    = Object.fromEntries(rows.map(r => [r.domain, r.workspace_id]));
    // Root domains from winnr_bison_export.csv — all 34 unique root domains.
    // Match mailboxes in _mailboxCache by root domain → derive winnrWsIds.
    const WINNR_ROOT_DOMAINS = new Set([
      'azurianstudio.biz','consultantscenter.org','consultantssystems.com','consultantstech.org',
      'findsolarsupportdept.net','getmktresearch.com','getprovenreports.com','getsolarsupportdept.com',
      'getsumterreports.com','gohoponstage.biz','goprovenresearch.com','juriscales.com',
      'juriscales.net','juriscales.org','marketresearchtech.org','mktanalyze.com','mktstudy.com',
      'nelsonrecords.com','radcliffeinquiry.com','radclifferesearchcenter.com','radcliffestudy.com',
      'realsolarsupportdept.net','redwoodcomplianceadvisor.com','redwoodcomplianceadvisors.com',
      'redwoodcomplianceconsultant.com','redwoodcompliancegroup.com','redwoodcomplianceservices.com',
      'saleslytalents.biz','saleslytalents.org','sokinfinancial.org','springavenue.org',
      'springdrivepro.com','springdrives.net','thereportspro.com',
    ]);
    function rootDomainOf(host) {
      const h = (host || '').toLowerCase();
      const labels = h.split('.');
      return h.endsWith('.co.uk') ? labels.slice(-3).join('.') : labels.slice(-2).join('.');
    }
    const winnrWsIds = new Set();
    for (const m of (_mailboxCache.mailboxes || [])) {
      // m.domain = full host e.g. "hq.azurianstudio.biz"; extract root to match CSV
      const root = rootDomainOf(m.domain || (m.email || '').split('@')[1]);
      if (root && m.workspace_id && WINNR_ROOT_DOMAINS.has(root)) {
        winnrWsIds.add(m.workspace_id);
      }
    }
    res.json({ blacklisted, clean, winnrWsIds: [...winnrWsIds], domainWs });
  } catch (err) {
    console.error('[stats-domain-sets]', err.message);
    res.status(500).json({ error: 'Database error' });
  }
});

// ─────────────────────────────────────────────────────────────────────
// Google Postmaster Tools — daily domain + IP reputation, spam rate
// ─────────────────────────────────────────────────────────────────────
// Set GOOGLE_POSTMASTER_KEY_JSON (inline JSON) or GOOGLE_POSTMASTER_KEY_FILE
// (path to a service account key file) to enable. The service account must
// be added as a user in Postmaster Tools (postmaster.google.com → Settings).

let _postmasterRunning = false;
let _postmasterLastRun = null;

function getPostmasterAuth() {
  const keyJson = process.env.GOOGLE_POSTMASTER_KEY_JSON;
  const keyFile = process.env.GOOGLE_POSTMASTER_KEY_FILE;
  if (!keyJson && !keyFile) return null;
  const opts = { scopes: ['https://www.googleapis.com/auth/postmaster.readonly'] };
  try {
    if (keyJson) opts.credentials = JSON.parse(keyJson);
    else opts.keyFile = keyFile;
  } catch (e) {
    console.error('[postmaster] Failed to parse credentials:', e.message);
    return null;
  }
  return new google.auth.GoogleAuth(opts);
}

// Returns the worst (lowest) reputation tier present in the ipReputations array.
// Ordering: BAD < LOW < MEDIUM < HIGH.
function _worstIpRep(ipReputations) {
  if (!Array.isArray(ipReputations) || !ipReputations.length) return null;
  for (const rep of ['BAD', 'LOW', 'MEDIUM', 'HIGH']) {
    if (ipReputations.some(r => r.reputation === rep && parseInt(r.numIps || 0) > 0)) return rep;
  }
  return ipReputations[0]?.reputation || null;
}

async function _postmasterGet(auth, path) {
  const client = await auth.getClient();
  const token = await client.getAccessToken();
  const url = `https://gmailpostmastertools.googleapis.com/v1/${path}`;
  const r = await new Promise((resolve, reject) => {
    const https = require('https');
    const urlObj = new URL(url);
    const options = {
      hostname: urlObj.hostname,
      path: urlObj.pathname + urlObj.search,
      method: 'GET',
      headers: { Authorization: `Bearer ${token.token}` },
    };
    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', d => { body += d; });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(body);
          if (res.statusCode >= 400) reject(new Error(`HTTP ${res.statusCode}: ${parsed.error?.message || body}`));
          else resolve(parsed);
        } catch (e) { reject(new Error('Invalid JSON response')); }
      });
    });
    req.on('error', reject);
    req.end();
  });
  return r;
}

async function refreshPostmasterData() {
  if (_postmasterRunning) return;
  _postmasterRunning = true;
  const t0 = Date.now();
  try {
    const auth = getPostmasterAuth();
    if (!auth) {
      console.log('[postmaster] No credentials — set GOOGLE_POSTMASTER_KEY_JSON or GOOGLE_POSTMASTER_KEY_FILE');
      return;
    }
    const pgdb = app.locals.pgDb;
    if (!pgdb) return;

    const { domains = [] } = await _postmasterGet(auth, 'domains');
    console.log(`[postmaster] ${domains.length} domain(s) registered in Postmaster Tools`);

    for (const d of domains) {
      const domName = (d.name || '').replace(/^domains\//, '');
      if (!domName) continue;
      try {
        // Fetch last 7 days of stats; pageSize=7 is enough for daily alerting
        const { trafficStats = [] } = await _postmasterGet(auth, `${d.name}/trafficStats?pageSize=7`);
        for (const stat of trafficStats) {
          // stat.name = "domains/example.com/trafficStats/2024/01/15"
          const parts = (stat.name || '').split('/');
          const date = parts.slice(-3).join('-'); // "2024-01-15"
          const spamRate = stat.userReportedSpamRatio ?? null;
          await pgdb.upsertPostmasterData(domName, date, {
            domain_reputation: stat.domainReputation === 'REPUTATION_CATEGORY_UNSPECIFIED' ? null : (stat.domainReputation || null),
            ip_reputation: _worstIpRep(stat.ipReputations),
            spam_rate: spamRate,
            spf_pass_rate: stat.spfSuccessRatio ?? null,
            dkim_pass_rate: stat.dkimSuccessRatio ?? null,
            dmarc_pass_rate: stat.dmarcSuccessRatio ?? null,
            ip_reputations: stat.ipReputations || [],
            raw_data: stat,
          });
        }
        if (trafficStats.length) console.log(`[postmaster] ${domName}: ${trafficStats.length} day(s) stored`);
      } catch (err) {
        console.warn(`[postmaster] ${domName} failed:`, err.message);
      }
    }
    _postmasterLastRun = new Date().toISOString();
    console.log(`[postmaster] done in ${Math.round((Date.now() - t0) / 1000)}s`);
  } catch (err) {
    console.error('[postmaster] refresh error:', err.message);
  } finally {
    _postmasterRunning = false;
  }
}

// Run once at startup (after 2 min) then every 24 h.
setTimeout(() => { if (getPostmasterAuth()) refreshPostmasterData().catch(() => {}); }, 2 * 60 * 1000);
setInterval(() => { if (getPostmasterAuth()) refreshPostmasterData().catch(() => {}); }, 24 * 60 * 60 * 1000);

