function mergeMailboxesWithMeta(mailboxes, metaByEmail) {
  return mailboxes.map(m => {
    const meta = metaByEmail.get(m.email) || {};
    return {
      ...m,
      // Auto-detected type from PlusVibe, overridden by manual tag if set.
      type_auto: detectMailboxType(m.provider),
      type:      meta.mailbox_type || detectMailboxType(m.provider) || 'smtp',
      supplier:           meta.supplier || null,
      notes:              meta.notes || null,
      billing_start_date: meta.billing_start_date || null,
      billing_day:        meta.billing_day || null,
      ignored_at:         meta.ignored_at || null,
    };
  });
}

// Build a campaign-id → aggregated stats map from the existing campaign
// cache. We use it to *attribute* a share of each campaign's sent/replies/
// bounces back to each mailbox attached to that campaign (PlusVibe rotates
// load across attached mailboxes, so an even share is a fair approximation).
// dbBounceByCampaign: optional Map<campaign_id, number> from our email_events
// table. Where present these override PlusVibe's bounced_count, which
// misclassifies OOO auto-replies as bounces.
function buildCampaignIndex(dbBounceByCampaign) {
  const idx = new Map(); // campaign_id → { sent, replies, bounces, mailbox_count }
  for (const ws of (campaignCache.workspaces || [])) {
    for (const c of (ws.campaigns || [])) {
      if (!c.id) continue;
      const dbBounces = dbBounceByCampaign?.get(c.id);
      idx.set(c.id, {
        sent: c.sent || 0,
        replies: c.replies || 0,
        bounces: dbBounces != null ? dbBounces : (c.bounces || 0),
        mailbox_count: 0,
      });
    }
  }
  return idx;
}

// Query email_events for actual per-mailbox sent/reply/bounce counts.
// Returns Map<sender_email, {sent, replies, bounces}>.
// Query email_events for per-mailbox sent and bounce counts.
// Real per-mailbox HUMAN reply counts from the client-portal's classified
// unibox_replies. mailbox_email = the address that received the reply (our sending
// mailbox, from Bison's primary_to_email_address). This gives a TRUE per-mailbox
// reply count instead of the old campaign-rate × mailbox-sent estimate. Human =
// interested/not_interested/question/unsubscribe (excludes warm-up + OOO). Returns
// Map(lower(mailbox_email) -> count). Best-effort: returns empty Map on any error
// (e.g. column not present yet) so the mailbox page never breaks.
async function buildPortalRepliesByMailbox(pgdb, days = 0) {
  if (!pgdb) return new Map();
  // MUST share the SAME window as the sent/bounce counts (buildMailboxStats
  // FromEvents) — otherwise reply_rate = all-time-replies / windowed-sent, which
  // is garbage (and zero on Today when a mailbox has no sends but old replies).
  const params = [];
  let windowSql = '';
  if (days > 0) { params.push(String(days)); windowSql = `AND received_at >= NOW() - ($1 || ' days')::interval`; }
  try {
    const { rows } = await pgdb.query(`
      SELECT lower(mailbox_email) AS mbx, COUNT(*)::int AS replies
      FROM unibox_replies
      WHERE mailbox_email IS NOT NULL
        AND COALESCE(admin_label, category)
            IN ('interested','not_interested','question','unsubscribe')
        ${windowSql}
      GROUP BY lower(mailbox_email)
    `, params);
    return new Map(rows.map(r => [r.mbx, parseInt(r.replies, 10) || 0]));
  } catch (e) {
    console.warn('[mailboxes] portal reply count query failed:', e.message);
    return new Map();
  }
}

// PlusVibe reply webhooks never include sender_email so replies are excluded —
// reply rates are computed by scaling the campaign reply rate to the mailbox's
// actual send volume instead.
// Accurate per-PROVIDER and per-SUPPLIER sending performance, attributed by the
// ACTUAL sending mailbox (email_events.sender_email → mailbox → provider/supplier).
// This replaces the old workspace-name-matching approach (loadProviderCharts),
// which broke in the PlusVibe→Bison cutover because it guessed a workspace's
// provider by name and summed the WHOLE workspace under it. Here every sent/
// reply/bounce is tied to the mailbox that actually sent it, then rolled up by
// that mailbox's provider (google/microsoft/smtp) AND supplier (Winnr/…).
//   ?days=0  → lifetime (Bison sender-emails api_* totals)
//   ?days=N  → last N days, read from mailbox_daily_stats (Bison breakdownOf-
//              EventsByDate, synced into a local table). Replies ALWAYS come
//              from the client portal (unibox_replies), windowed to match.
app.get('/api/mailboxes/provider-stats', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const days = Math.max(0, Math.min(365, parseInt(req.query.days, 10) || 0));
    const lifetime = days === 0;

    // sender_email → { provider, supplier } from the live mailbox roster + meta.
    const meta = await pgdb.listMailboxMeta().catch(() => []);
    const supplierByEmail = new Map((meta || []).map(m => [(m.email || '').toLowerCase(), m.supplier || null]));
    const senderInfo = new Map();
    for (const m of (_mailboxCache.mailboxes || [])) {
      const email = (m.email || '').toLowerCase();
      if (!email) continue;
      senderInfo.set(email, {
        provider: detectMailboxType(m.provider) || 'smtp',
        supplier: supplierByEmail.get(email) || null,
      });
    }

    const blank = () => ({ mailboxes: 0, sent: 0, replies: 0, bounces: 0, bounces_hard: 0, bounces_block: 0, bounces_soft: 0 });
    const byProvider = {}, bySupplier = {};
    let unmatched = blank();
    const provKey = p => p || 'smtp';
    const suppKey = s => s || '(unassigned)';

    // Mailbox COUNTS per provider/supplier come from the live roster either way
    // (so a card shows "· N mailboxes" even if some sent nothing this period).
    const mbxByProvider = {}, mbxBySupplier = {};
    for (const info of senderInfo.values()) {
      mbxByProvider[provKey(info.provider)] = (mbxByProvider[provKey(info.provider)] || 0) + 1;
      mbxBySupplier[suppKey(info.supplier)] = (mbxBySupplier[suppKey(info.supplier)] || 0) + 1;
    }

    // ── Bounce hard/block/soft proportions per provider+supplier from still-alive
    //    bounce events (bounce webhooks DO still fire). Scaled to the bounce total.
    const { isHard, isBlock } = bounceClassExprs("raw->>'msg'");
    let bClassByProvider = new Map(), bClassBySupplier = new Map();
    try {
      const bparams = [];
      let bwin = '';
      if (!lifetime) { bparams.push(days); bwin = `AND event_at >= (CURRENT_DATE - ($1::int - 1))`; }
      const bc = await pgdb.query(`
        SELECT lower(sender_email) AS sender,
               COUNT(*)::int AS n,
               COUNT(*) FILTER (WHERE ${isHard})::int  AS hard,
               COUNT(*) FILTER (WHERE ${isBlock})::int AS block
        FROM email_events
        WHERE event_type='bounce' AND sender_email IS NOT NULL AND sender_email <> ''
          ${bwin}
        GROUP BY lower(sender_email)
      `, bparams);
      for (const r of bc.rows) {
        const info = senderInfo.get(r.sender); if (!info) continue;
        const pk = provKey(info.provider), sk = suppKey(info.supplier);
        const accP = bClassByProvider.get(pk) || { n:0, hard:0, block:0 }; accP.n+=r.n; accP.hard+=r.hard; accP.block+=r.block; bClassByProvider.set(pk, accP);
        const accS = bClassBySupplier.get(sk) || { n:0, hard:0, block:0 }; accS.n+=r.n; accS.hard+=r.hard; accS.block+=r.block; bClassBySupplier.set(sk, accS);
      }
    } catch (e) {
      console.warn('[mailbox provider-stats] bounce-class query failed (non-fatal):', e.message);
    }
    const splitBounces = (bucket, total) => {
      if (!bucket || !bucket.n || !total) return { h:0, bl: total, sf:0 };
      const hp = bucket.hard/bucket.n, bp = bucket.block/bucket.n;
      const h = Math.round(total*hp), bl = Math.round(total*bp);
      return { h, bl, sf: Math.max(0, total - h - bl) };
    };

    // ── SENT + BOUNCE: lifetime ← cache api_*, grouped here; period ← the synced
    //    mailbox_daily_stats table (already at provider/supplier grain).
    if (lifetime) {
      for (const m of (_mailboxCache.mailboxes || [])) {
        const email = (m.email || '').toLowerCase(); if (!email) continue;
        const info = senderInfo.get(email) || { provider:'smtp', supplier:null };
        const sent = Number(m.api_sent)||0, bounces = Number(m.api_bounced)||0;
        if (!sent && !bounces) continue;
        const p = byProvider[provKey(info.provider)] = byProvider[provKey(info.provider)] || blank();
        const s = bySupplier[suppKey(info.supplier)] = bySupplier[suppKey(info.supplier)] || blank();
        p.sent += sent; p.bounces += bounces;
        s.sent += sent; s.bounces += bounces;
      }
    } else {
      try {
        const ds = await pgdb.query(`
          SELECT provider, supplier, SUM(sent)::int AS sent, SUM(bounced)::int AS bounces
          FROM mailbox_daily_stats
          WHERE date >= (CURRENT_DATE - ($1::int - 1))
          GROUP BY provider, supplier
        `, [days]);
        for (const r of ds.rows) {
          const p = byProvider[provKey(r.provider)] = byProvider[provKey(r.provider)] || blank();
          const s = bySupplier[suppKey(r.supplier)] = bySupplier[suppKey(r.supplier)] || blank();
          p.sent += r.sent||0; p.bounces += r.bounces||0;
          s.sent += r.sent||0; s.bounces += r.bounces||0;
        }
      } catch (e) {
        console.warn('[mailbox provider-stats] daily-stats query failed (non-fatal):', e.message);
      }
    }

    // ── REPLIES from the client portal (unibox_replies) — the canonical source.
    //    Aggregated to provider/supplier via senderInfo. Windowed to match.
    try {
      const rparams = [];
      let rwin = '';
      if (!lifetime) { rparams.push(days); rwin = `AND received_at >= (CURRENT_DATE - ($1::int - 1))`; }
      const rr = await pgdb.query(`
        SELECT lower(mailbox_email) AS sender,
               COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('interested','not_interested','question','unsubscribe'))::int AS replies,
               COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('ooo_auto_reply','auto_reply'))::int AS ooo_replies
        FROM unibox_replies
        WHERE mailbox_email IS NOT NULL AND mailbox_email <> ''
          ${rwin}
        GROUP BY lower(mailbox_email)
      `, rparams);
      for (const r of rr.rows) {
        const info = senderInfo.get(r.sender);
        if (!info) { unmatched.replies += r.replies||0; continue; }
        const p = byProvider[provKey(info.provider)] = byProvider[provKey(info.provider)] || blank();
        const s = bySupplier[suppKey(info.supplier)] = bySupplier[suppKey(info.supplier)] || blank();
        p.replies += r.replies||0; s.replies += r.replies||0;
        p.replies_ooo = (p.replies_ooo||0) + (r.ooo_replies||0);
        s.replies_ooo = (s.replies_ooo||0) + (r.ooo_replies||0);
      }
    } catch (e) {
      console.warn('[mailbox provider-stats] reply query failed (non-fatal):', e.message);
    }

    // Apply mailbox counts + bounce splits to each bucket.
    for (const [k, b] of Object.entries(byProvider)) { b.mailboxes = mbxByProvider[k] || 0; const x = splitBounces(bClassByProvider.get(k), b.bounces); b.bounces_hard=x.h; b.bounces_block=x.bl; b.bounces_soft=x.sf; }
    for (const [k, b] of Object.entries(bySupplier)) { b.mailboxes = mbxBySupplier[k] || 0; const x = splitBounces(bClassBySupplier.get(k), b.bounces); b.bounces_hard=x.h; b.bounces_block=x.bl; b.bounces_soft=x.sf; }

    const withRates = (map) => Object.fromEntries(Object.entries(map).map(([k, b]) => [k, {
      ...b,
      reply_rate:  b.sent > 0 ? b.replies / b.sent : 0,
      bounce_rate: b.sent > 0 ? b.bounces / b.sent : 0,
    }]));

    res.json({ days, lifetime, syncedAt: _dailySyncState.lastRun, byProvider: withRates(byProvider), bySupplier: withRates(bySupplier), unmatched: { ...unmatched, reply_rate: unmatched.sent>0?unmatched.replies/unmatched.sent:0, bounce_rate: unmatched.sent>0?unmatched.bounces/unmatched.sent:0 } });
  } catch (err) {
    console.error('[mailbox provider-stats]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Winnr Generic stats — lifetime sent/bounce from mailbox cache, human replies +
// OOO from unibox_replies, bounce breakdown from email_events bounce webhooks.
// Filtered to the 34 root domains from the Winnr batch CSV.
const WINNR_GENERIC_ROOTS = new Set([
  'azurianstudio.biz','consultantscenter.org','consultantssystems.com','consultantstech.org',
  'findsolarsupportdept.net','getmktresearch.com','getprovenreports.com','getsolarsupportdept.com',
  'getsumterreports.com','gohoponstage.biz','goprovenresearch.com','juriscales.com',
  'juriscales.net','juriscales.org','marketresearchtech.org','mktanalyze.com','mktstudy.com',
  'nelsonrecords.com','radcliffeinquiry.com','radclifferesearchcenter.com','radcliffestudy.com',
  'realsolarsupportdept.net','redwoodcomplianceadvisor.com','redwoodcomplianceadvisors.com',
  'redwoodcomplianceconsultant.com','redwoodcompliancegroup.com','redwoodcomplianceservices.com',
  'saleslytalents.biz','saleslytalents.org','sokinfinancial.org','springavenue.org',
  'springdrivepro.com','springdrives.net','thereportspro.com',
]);
function winnrRootOf(host) {
  const h = (host || '').toLowerCase();
  const labels = h.split('.');
  return h.endsWith('.co.uk') ? labels.slice(-3).join('.') : labels.slice(-2).join('.');
}
app.get('/api/mailboxes/winnr-generic-stats', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    const days = parseInt(req.query.days, 10) || 0;
    const lifetime = days === 0;

    // Supplier per mailbox, so we can size each workspace's full Winnr cohort for
    // the apportionment fallback below.
    const meta = await pgdb.listMailboxMeta().catch(() => []);
    const supplierByEmail = new Map((meta || []).map(m => [(m.email || '').toLowerCase(), (m.supplier || '').toLowerCase()]));

    // Walk the cache once: collect the Winnr Generic mailbox emails, and — keyed by
    // the canonical workspace_id (the SAME key mailbox_daily_stats uses) — the count
    // of generic mailboxes vs the count of ALL Winnr mailboxes in that workspace.
    // That ratio lets us carve the 773 generic boxes out of the workspace Winnr
    // total, which is the only per-day sent source that actually has data.
    const genericEmails = new Set();
    const genericWsIds  = new Set();
    const winnrCountByWs   = new Map(); // workspace_id -> total Winnr-supplier mailboxes
    const genericCountByWs = new Map(); // workspace_id -> generic mailboxes
    for (const m of (_mailboxCache.mailboxes || [])) {
      const email = (m.email || '').toLowerCase();
      if (!email) continue;
      const ws = String(m.workspace_id || '');
      const host = m.domain || email.split('@')[1] || '';
      const isGeneric = WINNR_GENERIC_ROOTS.has(winnrRootOf(host));
      // The generic domains belong to Winnr; count them toward the Winnr cohort
      // even when meta has no explicit supplier row yet.
      const isWinnr = isGeneric || supplierByEmail.get(email) === 'winnr';
      if (ws && isWinnr) winnrCountByWs.set(ws, (winnrCountByWs.get(ws) || 0) + 1);
      if (!isGeneric) continue;
      genericEmails.add(email);
      if (ws) { genericWsIds.add(ws); genericCountByWs.set(ws, (genericCountByWs.get(ws) || 0) + 1); }
    }
    const emailArr = [...genericEmails];
    const wsArr    = [...genericWsIds];
    const mailboxCount = emailArr.length;

    // ?list=replies → dump the actual reply rows for the generic mailboxes so the
    // numbers on the card can be eyeballed/audited (windowed to the same period).
    if (req.query.list === 'replies') {
      if (!emailArr.length) return res.json({ mailboxes: 0, replies: [] });
      const rparams = [emailArr];
      let rwin = '';
      if (!lifetime) { rparams.push(days); rwin = `AND received_at >= (CURRENT_DATE - ($2::int - 1))`; }
      const rl = await pgdb.query(`
        SELECT received_at, lower(mailbox_email) AS mailbox, lower(sender_email) AS sender,
               COALESCE(admin_label, category) AS category, folder, marked_as_lead,
               LEFT(COALESCE(subject,''), 80) AS subject,
               LEFT(COALESCE(body_preview, raw->>'text_body', ''), 160) AS snippet
        FROM unibox_replies
        WHERE lower(mailbox_email) = ANY($1) ${rwin}
          AND COALESCE(admin_label, category) NOT IN ('warmup','warm_up')
          AND folder NOT IN ('warmup','sent','bounced','spam')
        ORDER BY received_at DESC
      `, rparams);
      const byCat = {};
      for (const r of rl.rows) byCat[r.category || 'null'] = (byCat[r.category || 'null'] || 0) + 1;
      return res.json({
        mailboxes: mailboxCount,
        period: lifetime ? 'lifetime' : `${days}d`,
        total_replies: rl.rowCount,
        by_category: byCat,
        replies: rl.rows,
      });
    }

    // ── SENT + BOUNCED ────────────────────────────────────────────────────────
    // Bison has NO working per-mailbox sent source (sender-emails api_sent is 0,
    // campaign-events/stats returns zeros, the email_events webhook died ~06-15).
    // The only per-day sent figure that exists is the workspace Winnr-supplier
    // total in mailbox_daily_stats. So we carve the 773 generic boxes out of it by
    // their share of the workspace's Winnr mailboxes — an estimate, but the same
    // apportionment every other card on this page already uses. Keyed by
    // workspace_id to match the table exactly (no team remapping → no zero-share).
    let sent = 0, bounced = 0;
    const source = 'apportioned-daily-stats';
    const sentByDate = new Map();
    if (wsArr.length) {
      const win = lifetime ? '' : `AND date >= (CURRENT_DATE - ($2::int - 1))`;
      const params = lifetime ? [wsArr] : [wsArr, days];
      const ds = await pgdb.query(`
        SELECT workspace_id, date::text AS date, SUM(sent)::int AS sent, SUM(bounced)::int AS bounced
        FROM mailbox_daily_stats
        WHERE workspace_id = ANY($1) AND LOWER(supplier) = 'winnr' ${win}
        GROUP BY workspace_id, date ORDER BY date
      `, params);
      for (const r of ds.rows) {
        const ws = String(r.workspace_id);
        const gc = genericCountByWs.get(ws) || 0;
        const wc = winnrCountByWs.get(ws)   || 0;
        const share = wc > 0 ? gc / wc : 0;
        const s = Math.round((r.sent || 0) * share);
        sent    += s;
        bounced += Math.round((r.bounced || 0) * share);
        sentByDate.set(r.date, (sentByDate.get(r.date) || 0) + s);
      }
    }

    const dailySeries = [...sentByDate.entries()].map(([date, sent]) => ({ date, sent }));

    // Human replies + OOO from unibox_replies, windowed to period
    let humanReplies = 0, oooReplies = 0;
    const replyByDate = new Map(); // date → {replies, ooo} for the chart
    if (emailArr.length) {
      const rparams = [emailArr];
      let rwin = '';
      if (!lifetime) { rparams.push(days); rwin = `AND received_at >= (CURRENT_DATE - ($2::int - 1))`; }
      const rr = await pgdb.query(`
        SELECT
          COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('interested','not_interested','question','unsubscribe'))::int AS human,
          COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('ooo_auto_reply','auto_reply'))::int AS ooo
        FROM unibox_replies
        WHERE lower(mailbox_email) = ANY($1) ${rwin}
      `, rparams);
      humanReplies = Number(rr.rows[0]?.human) || 0;
      oooReplies   = Number(rr.rows[0]?.ooo)   || 0;

      // per-day replies for the chart (period only)
      if (!lifetime) {
        const rd = await pgdb.query(`
          SELECT (received_at AT TIME ZONE 'UTC')::date::text AS date,
                 COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('interested','not_interested','question','unsubscribe'))::int AS replies,
                 COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('ooo_auto_reply','auto_reply'))::int AS ooo
          FROM unibox_replies
          WHERE lower(mailbox_email) = ANY($1) AND received_at >= (CURRENT_DATE - ($2::int - 1))
          GROUP BY 1
        `, [emailArr, days]);
        for (const r of rd.rows) replyByDate.set(r.date, { replies: r.replies||0, ooo: r.ooo||0 });
      }
    }

    // Build continuous daily series for the chart (period only)
    let series = [], chartDates = [];
    if (!lifetime) {
      const sentByDate = new Map(dailySeries.map(r => [r.date, r.sent||0]));
      for (let i = days - 1; i >= 0; i--) {
        const d = serverDateString(new Date(Date.now() - i * 86400000));
        chartDates.push(d);
        const rep = replyByDate.get(d) || { replies:0, ooo:0 };
        series.push({ sent: sentByDate.get(d) || 0, replies: rep.replies, ooo: rep.ooo });
      }
    }

    // Bounce breakdown (hard/block/soft) from email_events bounce webhooks, windowed to period
    let bouncesHard = 0, bouncesBlock = 0, bouncesSoft = 0;
    if (emailArr.length) {
      const { isHard, isBlock } = bounceClassExprs("raw->>'msg'");
      const bparams = [emailArr];
      let bwin = '';
      if (!lifetime) { bparams.push(days); bwin = `AND event_at >= (CURRENT_DATE - ($2::int - 1))`; }
      const bc = await pgdb.query(`
        SELECT
          COUNT(*)::int AS n,
          COUNT(*) FILTER (WHERE ${isHard})::int  AS hard,
          COUNT(*) FILTER (WHERE ${isBlock})::int AS block
        FROM email_events
        WHERE event_type='bounce' AND lower(sender_email) = ANY($1) ${bwin}
      `, bparams);
      const bn  = Number(bc.rows[0]?.n)    || 0;
      const bh  = Number(bc.rows[0]?.hard)  || 0;
      const bbl = Number(bc.rows[0]?.block) || 0;
      bouncesHard  = bh;
      bouncesBlock = bbl;
      bouncesSoft  = Math.max(0, bn - bh - bbl);
    }

    res.json({
      mailboxes:        mailboxCount,
      sent,
      bounced,
      bounces_hard:     bouncesHard,
      bounces_block:    bouncesBlock,
      bounces_soft:     bouncesSoft,
      human_replies:    humanReplies,
      ooo_replies:      oooReplies,
      replies_with_ooo: humanReplies + oooReplies,
      series,
      dates: chartDates,
      _source: source,
    });
  } catch (err) {
    console.error('[winnr-generic-stats]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Per-DAY trend over the window — so the page can chart whether sends/replies/
// bounces are trending up or down. Four series per day:
//   sent, bounces ← mailbox_daily_stats (synced from Bison)
//   replies (human), repliesOoo (human + OOO) ← client portal unibox_replies
// Only meaningful for a period (days>0); lifetime has no per-day store.
//   ?days=N  (default 7)
app.get('/api/mailboxes/daily-trend', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const days = Math.max(1, Math.min(365, parseInt(req.query.days, 10) || 7));

    // sent + bounces per day — total and per-provider/supplier
    const [sb, sbSplit] = await Promise.all([
      pgdb.query(`
        SELECT date::text AS date, SUM(sent)::int AS sent, SUM(bounced)::int AS bounces
        FROM mailbox_daily_stats
        WHERE date >= (CURRENT_DATE - ($1::int - 1))
        GROUP BY date ORDER BY date
      `, [days]),
      pgdb.query(`
        SELECT date::text AS date, provider, supplier,
               SUM(sent)::int AS sent, SUM(bounced)::int AS bounces
        FROM mailbox_daily_stats
        WHERE date >= (CURRENT_DATE - ($1::int - 1))
        GROUP BY date, provider, supplier ORDER BY date
      `, [days]),
    ]);

    // human replies + OOO per day — total and per provider/supplier via senderInfo join.
    // Build the SAME way provider-stats does: provider ALWAYS via detectMailboxType
    // (the live cache), supplier from meta. Earlier this used meta.provider RAW
    // (e.g. 'GOOGLE') as the bucket key, which never matched the 'google' bucket
    // that sent lives under — so per-provider reply lines rendered flat-zero.
    const metaForTrend = pgdb ? await pgdb.listMailboxMeta() : [];
    const supplierByEmailTrend = new Map((metaForTrend||[]).map(m => [(m.email||'').toLowerCase(), m.supplier||null]));
    const senderInfoTrend = new Map();
    for (const m of (_mailboxCache.mailboxes||[])) {
      const e = (m.email||'').toLowerCase(); if (!e) continue;
      senderInfoTrend.set(e, {
        provider: detectMailboxType(m.provider) || 'smtp',
        supplier: supplierByEmailTrend.get(e) || null,
      });
    }

    const [rp, rpSplit] = await Promise.all([
      pgdb.query(`
        SELECT (received_at AT TIME ZONE 'UTC')::date::text AS date,
               COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('interested','not_interested','question','unsubscribe'))::int AS replies,
               COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('ooo_auto_reply','auto_reply'))::int AS ooo
        FROM unibox_replies
        WHERE mailbox_email IS NOT NULL AND mailbox_email <> ''
          AND received_at >= (CURRENT_DATE - ($1::int - 1))
        GROUP BY 1 ORDER BY 1
      `, [days]),
      pgdb.query(`
        SELECT (received_at AT TIME ZONE 'UTC')::date::text AS date,
               lower(mailbox_email) AS email,
               COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('interested','not_interested','question','unsubscribe'))::int AS replies,
               COUNT(*) FILTER (WHERE COALESCE(admin_label, category) IN ('ooo_auto_reply','auto_reply'))::int AS ooo
        FROM unibox_replies
        WHERE mailbox_email IS NOT NULL AND mailbox_email <> ''
          AND received_at >= (CURRENT_DATE - ($1::int - 1))
        GROUP BY 1, 2
      `, [days]),
    ]);

    const sbBy = new Map(sb.rows.map(r => [r.date, r]));
    const rpBy = new Map(rp.rows.map(r => [r.date, r]));

    // per-provider and per-supplier daily sent+replies: { google: { '2026-06-01': {sent,replies,ooo}, ... } }
    const provDays = {}, suppDays = {};
    const provKey = p => p || 'smtp';
    const suppKey = s => s || '(unassigned)';
    for (const r of sbSplit.rows) {
      const pk = provKey(r.provider), sk = suppKey(r.supplier);
      if (!provDays[pk]) provDays[pk] = {};
      if (!suppDays[sk]) suppDays[sk] = {};
      const pd = provDays[pk][r.date] = provDays[pk][r.date] || { sent:0, replies:0, ooo:0 };
      const sd = suppDays[sk][r.date] = suppDays[sk][r.date] || { sent:0, replies:0, ooo:0 };
      pd.sent += r.sent || 0; sd.sent += r.sent || 0;
    }
    // join per-mailbox replies to provider/supplier
    for (const r of rpSplit.rows) {
      const info = senderInfoTrend.get(r.email) || {};
      const pk = provKey(info.provider), sk = suppKey(info.supplier);
      if (!provDays[pk]) provDays[pk] = {};
      if (!suppDays[sk]) suppDays[sk] = {};
      const pd = provDays[pk][r.date] = provDays[pk][r.date] || { sent:0, replies:0, ooo:0 };
      const sd = suppDays[sk][r.date] = suppDays[sk][r.date] || { sent:0, replies:0, ooo:0 };
      pd.replies += r.replies||0; pd.ooo += r.ooo||0;
      sd.replies += r.replies||0; sd.ooo += r.ooo||0;
    }

    // build a continuous date axis so flat/zero days still show on the chart.
    const dates = [];
    for (let i = days - 1; i >= 0; i--) dates.push(serverDateString(new Date(Date.now() - i * 86400000)));

    const series = dates.map(d => {
      const s = sbBy.get(d) || {}; const r = rpBy.get(d) || {};
      const sent = s.sent || 0, bounces = s.bounces || 0;
      const replies = r.replies || 0, ooo = r.ooo || 0;
      return { date: d, sent, bounces, replies, repliesOoo: replies + ooo };
    });

    // convert per-provider/supplier date maps to ordered arrays matching `dates`
    const toSeries = dayMap => Object.fromEntries(
      Object.entries(dayMap).map(([k, dm]) => [k, dates.map(d => dm[d] || { sent:0, replies:0, ooo:0 })])
    );

    res.json({ days, syncedAt: _dailySyncState.lastRun, series, byProvider: toSeries(provDays), bySupplier: toSeries(suppDays), dates });
  } catch (err) {
    console.error('[mailbox daily-trend]', err.message);
    res.status(500).json({ error: err.message });
  }
});

async function buildMailboxStatsFromEvents(pgdb, days = 0) {
  if (!pgdb) return new Map();
  // 3-way bounce split per mailbox from the shared classifier — so the
  // Mailboxes page can tell a mailbox sending to a bad list (high hard) from
  // one whose reputation is getting it filtered (high block).
  // `days` bounds the window so the per-mailbox Sent/Reply/Bounce match the
  // period the user picked on the page (0 = all-time).
  const { isHard, isBlock, isSoft } = bounceClassExprs("raw->>'msg'");
  const params = [];
  let windowSql = '';
  if (days > 0) { params.push(String(days)); windowSql = `AND event_at >= NOW() - ($1 || ' days')::interval`; }
  try {
    const { rows } = await pgdb.query(`
      SELECT
        sender_email,
        COUNT(*) FILTER (WHERE event_type = 'sent')    AS sent,
        COUNT(*) FILTER (WHERE event_type = 'bounce')  AS bounces,
        COUNT(*) FILTER (WHERE event_type = 'bounce' AND ${isHard})  AS bounces_hard,
        COUNT(*) FILTER (WHERE event_type = 'bounce' AND ${isBlock}) AS bounces_block,
        COUNT(*) FILTER (WHERE event_type = 'bounce' AND ${isSoft})  AS bounces_soft
      FROM email_events
      WHERE sender_email IS NOT NULL ${windowSql}
      GROUP BY sender_email
    `, params);
    return new Map(rows.map(r => [r.sender_email, {
      sent:          parseInt(r.sent,          10) || 0,
      bounces:       parseInt(r.bounces,       10) || 0,
      bounces_hard:  parseInt(r.bounces_hard,  10) || 0,
      bounces_block: parseInt(r.bounces_block, 10) || 0,
      bounces_soft:  parseInt(r.bounces_soft,  10) || 0,
    }]));
  } catch {
    return new Map();
  }
}

// Walk the mailboxes and attach per-mailbox performance stats.
// Uses real sent/bounce counts from email_events where available.
// Reply rate is computed as (campaign reply rate × mailbox sent count) because
// PlusVibe reply webhooks don't include the sending mailbox.
// Falls back to even-split for mailboxes with no webhook history.
function attachMailboxStats(mailboxes, campIndex, eventsByMailbox = new Map(), portalRepliesByMailbox = new Map()) {
  // First pass: count mailboxes per campaign (for even-split fallback) and
  // accumulate campaign-level totals needed for reply-rate scaling.
  for (const m of mailboxes) {
    for (const cid of (m.campaign_ids || [])) {
      const c = campIndex.get(cid);
      if (c) c.mailbox_count++;
    }
  }

  // Second pass: assign sent/bounce from email_events where available,
  // then derive replies — preferring the portal's REAL per-mailbox reply count,
  // falling back to the campaign-rate × sent estimate only when the portal has none.
  for (const m of mailboxes) {
    const ev = eventsByMailbox.get(m.email);
    // Real human replies for THIS mailbox from the classified portal data.
    const portalReplies = portalRepliesByMailbox.get((m.email || '').toLowerCase());

    // PRIMARY source = Bison's sender-emails API counts (lifetime, authoritative,
    // independent of the email_sent webhook that Bison stopped firing ~2026-06-15).
    // Use these whenever present; webhook events only fill the 3-way bounce split.
    if ((m.api_sent || 0) > 0 || (m.api_replied || 0) > 0 || (m.api_bounced || 0) > 0) {
      m.attributed_sent    = m.api_sent || 0;
      m.attributed_replies = (portalReplies != null && portalReplies > 0) ? portalReplies : (m.api_replied || 0);
      m.attributed_bounces = m.api_bounced || 0;
      // Borrow the hard/block/soft split from webhook events if we have it.
      if (ev) { m.bounces_hard = ev.bounces_hard; m.bounces_block = ev.bounces_block; m.bounces_soft = ev.bounces_soft; }
      m.stats_source = 'bison_api';
      const s0 = m.attributed_sent;
      m.reply_rate  = s0 > 0 ? m.attributed_replies / s0 : 0;
      m.bounce_rate = s0 > 0 ? m.attributed_bounces / s0 : 0;
      continue;
    }

    if (ev && ev.sent > 0) {
      // Real sent + bounce counts from webhooks.
      m.attributed_sent    = ev.sent;
      m.attributed_bounces = ev.bounces;
      // 3-way split from the classifier (real, not estimated). Only set on the
      // webhook path — the even-split fallback has no per-event reason to classify.
      m.bounces_hard  = ev.bounces_hard;
      m.bounces_block = ev.bounces_block;
      m.bounces_soft  = ev.bounces_soft;
      if (portalReplies != null) {
        // TRUE per-mailbox reply count from the portal (best source).
        m.attributed_replies = portalReplies;
      } else {
        // Fallback: scale campaign reply rate to this mailbox's actual send volume.
        let campSent = 0, campReplies = 0;
        for (const cid of (m.campaign_ids || [])) {
          const c = campIndex.get(cid);
          if (!c) continue;
          campSent    += c.sent;
          campReplies += c.replies;
        }
        const campReplyRate = campSent > 0 ? campReplies / campSent : 0;
        m.attributed_replies = Math.round(ev.sent * campReplyRate);
      }
    } else {
      // No webhook data — fall back to even-split across campaign mailboxes.
      let sent = 0, replies = 0, bounces = 0;
      for (const cid of (m.campaign_ids || [])) {
        const c = campIndex.get(cid);
        if (!c || !c.mailbox_count) continue;
        sent    += c.sent    / c.mailbox_count;
        replies += c.replies / c.mailbox_count;
        bounces += c.bounces / c.mailbox_count;
      }
      m.attributed_sent    = Math.round(sent);
      m.attributed_replies = Math.round(replies);
      m.attributed_bounces = Math.round(bounces);
    }
    const s = m.attributed_sent;
    const r = m.attributed_replies;
    const b = m.attributed_bounces;
    m.reply_rate  = s > 0 ? r / s : 0;
    m.bounce_rate = s > 0 ? b / s : 0;
  }
}

// Pull auth + blacklist data from the domain_health table.
async function attachDomainHealth(pgdb, mailboxes) {
  if (!pgdb) return;
  const domains = Array.from(new Set(mailboxes.map(m => m.domain).filter(Boolean)));
  if (!domains.length) return;
  const r = await pgdb.query(
    `SELECT domain, spf, dkim, dmarc, blacklists, score, status FROM domain_health WHERE domain = ANY($1::text[])`,
    [domains]
  );
  const byDom = new Map();
  for (const row of r.rows) byDom.set(row.domain, row);
  for (const m of mailboxes) {
    const dh = byDom.get(m.domain);
    if (!dh) continue;
    const parseJsonb = v => (typeof v === 'string' ? JSON.parse(v || 'null') : v);
    const spf   = parseJsonb(dh.spf)   || {};
    const dkim  = parseJsonb(dh.dkim)  || {};
    const dmarc = parseJsonb(dh.dmarc) || {};
    const bl    = parseJsonb(dh.blacklists) || [];
    m.auth = {
      spf_present:   !!spf.present,
      spf_strict:    !!spf.strict,
      spf_raw:       spf.raw || null,
      dkim_present:  !!dkim.present,
      dkim_selector: dkim.selector || null,
      dkim_raw:      dkim.raw || null,
      dmarc_present: !!dmarc.present,
      dmarc_policy:  dmarc.policy || null,
      dmarc_raw:     dmarc.raw || null,
    };
    m.blacklist_count = Array.isArray(bl) ? bl.length : 0;
    m.domain_score    = typeof dh.score === 'number' ? dh.score : null;
    m.domain_notes    = dh.notes || null;
    m.domain_status   = dh.status || null;
  }
}

// Decide which mailboxes need attention — surface them in the UI so the
// team has a single triage list instead of skimming the full table.
function computeAttentionFlags(m) {
  const flags = [];
  const status  = (m.status || '').toUpperCase();
  const warmup  = (m.warmup_status || '').toUpperCase();
  if (status && status !== 'ACTIVE' && status !== 'PAUSED') flags.push({ level: 'critical', msg: `Disconnected (${status.toLowerCase()})` });
  if (m.auth && !m.auth.spf_present)        flags.push({ level: 'critical', msg: 'Missing SPF' });
  if (m.auth && !m.auth.dkim_present)       flags.push({ level: 'critical', msg: 'Missing DKIM' });
  if (m.auth && !m.auth.dmarc_present)      flags.push({ level: 'warning',  msg: 'Missing DMARC' });
  // p=none is the recommended policy for cold outreach — not an attention item.
  if (m.blacklist_count)                    flags.push({ level: 'critical', msg: `Blacklisted on ${m.blacklist_count}` });
  if (warmup !== 'ACTIVE' && status === 'ACTIVE') flags.push({ level: 'warning', msg: 'Warmup not running' });
  if (m.attributed_sent >= 100) {
    if (m.bounce_rate > 0.05) flags.push({ level: 'critical', msg: `High bounce rate ${(m.bounce_rate*100).toFixed(1)}%` });
    if (m.reply_rate  < 0.01) flags.push({ level: 'warning',  msg: `Low reply rate ${(m.reply_rate*100).toFixed(2)}%` });
  }
  return flags;
}

// Compute aggregate stats grouped by an arbitrary key function. The
// per-mailbox attribution (attributed_sent etc.) must already be on each
// row — attachMailboxStats() does that before we call this.
function groupMailboxStats(mailboxes, keyFn) {
  const groups = {};
  for (const m of mailboxes) {
    const k = keyFn(m);
    if (!k) continue;
    if (!groups[k]) groups[k] = {
      key: k, count: 0,
      active: 0, paused: 0, disconnected: 0,
      warmup_active: 0,
      total_daily_limit: 0,
      avg_daily_limit: 0,
      total_campaigns: 0,
      // Performance rollups
      total_sent: 0, total_replies: 0, total_bounces: 0,
      reply_rate: 0, bounce_rate: 0,
      // Health rollups
      auth_clean: 0, blacklist_listed: 0,
      attention_count: 0,
      // Cost rollups
      total_monthly_cost: 0,
    };
    const g = groups[k];
    g.count++;
    const status = (m.status || '').toUpperCase();
    if (status === 'ACTIVE')        g.active++;
    else if (status === 'PAUSED')   g.paused++;
    else if (status)                g.disconnected++;
    if ((m.warmup_status || '').toUpperCase() === 'ACTIVE') g.warmup_active++;
    if (typeof m.daily_limit === 'number') g.total_daily_limit += m.daily_limit;
    g.total_campaigns += m.campaigns_count || 0;
    g.total_sent    += m.attributed_sent    || 0;
    g.total_replies += m.attributed_replies || 0;
    g.total_bounces += m.attributed_bounces || 0;
    if (m.auth && m.auth.spf_present && m.auth.dkim_present && m.auth.dmarc_present) g.auth_clean++;
    if (m.blacklist_count) g.blacklist_listed++;
    if (Array.isArray(m.attention) && m.attention.length) g.attention_count++;
    g.total_monthly_cost += m.unit_cost || 0;
  }
  for (const k of Object.keys(groups)) {
    const g = groups[k];
    g.avg_daily_limit = g.count ? Math.round(g.total_daily_limit / g.count) : 0;
    g.active_pct = g.count ? Math.round((g.active / g.count) * 100) : 0;
    g.warmup_pct = g.count ? Math.round((g.warmup_active / g.count) * 100) : 0;
    g.reply_rate  = g.total_sent > 0 ? g.total_replies / g.total_sent : 0;
    g.bounce_rate = g.total_sent > 0 ? g.total_bounces / g.total_sent : 0;
    g.auth_clean_pct       = g.count ? Math.round((g.auth_clean / g.count) * 100) : 0;
    g.blacklist_listed_pct = g.count ? Math.round((g.blacklist_listed / g.count) * 100) : 0;
  }
  return Object.values(groups).sort((a, b) => b.count - a.count);
}

app.get('/api/mailboxes', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    // Period window for the per-mailbox stats (matches the page's Today/7d/…/60d
    // buttons). 0/absent = all-time. Previously the table was ALWAYS all-time
    // regardless of the selected period — an accuracy bug this fixes.
    const days = Math.max(0, Math.min(365, parseInt(req.query.days, 10) || 0));
    const meta = pgdb ? await pgdb.listMailboxMeta() : [];
    const metaByEmail = new Map(meta.map(m => [m.email, m]));
    const merged = mergeMailboxesWithMeta(_mailboxCache.mailboxes, metaByEmail)
      .filter(m => !m.ignored_at);

    // Attach per-mailbox monthly unit cost so the dashboard can show $/mo
    // and so the Finance page totals stay consistent with what's visible
    // here.
    const pricingRows = pgdb ? await pgdb.listMailboxPricing() : [];
    const prices = pricingMap(pricingRows);
    for (const m of merged) m.unit_cost = mailboxUnitCost(m, prices);

    // Query per-mailbox stats from webhook events and per-campaign bounce
    // corrections in parallel — both queries are independent.
    const [eventsByMailbox, dbBounceByCampaign, portalRepliesByMailbox] = await Promise.all([
      buildMailboxStatsFromEvents(pgdb, days),
      pgdb ? pgdb.query(`
        SELECT campaign_id, COUNT(*)::int AS bounces
        FROM email_events
        WHERE event_type = 'bounce'
          AND campaign_id IS NOT NULL
        GROUP BY campaign_id
      `).then(r => new Map(r.rows.map(row => [row.campaign_id, row.bounces])))
        .catch(() => new Map())
        : Promise.resolve(new Map()),
      buildPortalRepliesByMailbox(pgdb, days),
    ]);

    // Attribute per-mailbox sent/replies/bounces — prefers the portal's REAL
    // per-mailbox reply count, then real webhook sent/bounce, then even-split.
    attachMailboxStats(merged, buildCampaignIndex(dbBounceByCampaign), eventsByMailbox, portalRepliesByMailbox);

    // Inherit SPF/DKIM/DMARC + blacklist status from the domain_health table.
    await attachDomainHealth(pgdb, merged);

    // Compute per-mailbox attention flags from the combined data.
    for (const m of merged) m.attention = computeAttentionFlags(m);

    // Stats grouped by supplier (user-assigned), by type (auto/manual), and
    // by supplier × type so the user can compare "Maildoso Google" vs
    // "Mithun Google" vs "Maildoso Microsoft" etc. at a glance.
    const bySupplier   = groupMailboxStats(merged, m => m.supplier || 'Unassigned');
    const byType       = groupMailboxStats(merged, m => m.type);
    const byClient     = groupMailboxStats(merged, m => m.workspace_name || 'Unassigned');
    const bySupplierType = groupMailboxStats(merged, m =>
      `${m.supplier || 'Unassigned'} · ${m.type || 'smtp'}`
    );

    const needs_attention = merged.filter(m => Array.isArray(m.attention) && m.attention.length).length;

    res.json({
      mailboxes: merged,
      stats: { bySupplier, byType, byClient, bySupplierType },
      summary: {
        total: merged.length,
        needs_attention,
      },
      suppliers: SUPPLIERS_ALLOWED,
      types: TYPES_ALLOWED,
      lastRun: _mailboxCache.lastRun,
      running: _mailboxCache.running,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


app.post('/api/mailboxes/refresh', requireSession, (req, res) => {
  if (_mailboxCache.running) return res.json({ ok: true, message: 'Already refreshing' });
  refreshMailboxCache().catch(() => {});
  res.json({ ok: true, message: 'Mailbox refresh started' });
});

// Diagnostic: per-workspace mailbox counts from the last cache refresh + which
// workspaces FAILED to fetch (e.g. auth/401) so the total is short. Answers
// "Bison shows N but admin shows fewer — which workspaces are missing?".
app.get('/api/mailboxes/refresh-status', requireSession, (req, res) => {
  const byTeam = {};
  for (const m of (_mailboxCache.mailboxes || [])) {
    const k = (m.workspace_name || m.bison_team_id || m.workspace_id || '?');
    byTeam[k] = (byTeam[k] || 0) + 1;
  }
  res.json({
    total: (_mailboxCache.mailboxes || []).length,
    lastRun: _mailboxCache.lastRun,
    running: _mailboxCache.running,
    perWorkspace: byTeam,
    failedTeams: _mailboxCache.failedTeams || [],
  });
});

// Pull the LIVE supplier from PlusVibe tags — the real source of truth. Supplier
// tags are set in PlusVibe (mailbox tags), but the mailbox_meta table admin-legacy
// reads can be stale. This scans the live roster (_mailboxCache, which already
// carries each account's PV `tags`), matches any tag against SUPPLIERS_ALLOWED
// (case-insensitive), and reports the true per-supplier breakdown + untagged +
// per-workspace counts. This is what should drive supplier/costing, not the DB.
app.get('/api/mailboxes/pv-supplier-tags', requireSession, (req, res) => {
  const roster = _mailboxCache.mailboxes || [];
  const allowedLower = new Map(SUPPLIERS_ALLOWED.map(s => [s.toLowerCase(), s]));

  const bySupplier = {};        // canonical supplier → count
  const byWorkspace = {};       // workspace → { supplier → count }
  const untaggedByWorkspace = {};
  const multiTagged = [];       // mailboxes carrying >1 supplier tag (ambiguous)
  let untagged = 0, total = roster.length;

  for (const m of roster) {
    const tagNames = Array.isArray(m.tags)
      ? m.tags.map(t => (typeof t === 'string' ? t : (t?.name || ''))).filter(Boolean)
      : [];
    // Which of this mailbox's tags are supplier tags?
    const matched = [...new Set(
      tagNames.map(t => allowedLower.get(t.trim().toLowerCase())).filter(Boolean)
    )];
    const ws = m.workspace_name || m.workspace_id || '(none)';
    if (matched.length === 0) {
      untagged++;
      untaggedByWorkspace[ws] = (untaggedByWorkspace[ws] || 0) + 1;
      continue;
    }
    if (matched.length > 1) multiTagged.push({ email: m.email, workspace: ws, suppliers: matched });
    // Count under each matched supplier (usually exactly one).
    for (const sup of matched) {
      bySupplier[sup] = (bySupplier[sup] || 0) + 1;
      if (!byWorkspace[ws]) byWorkspace[ws] = {};
      byWorkspace[ws][sup] = (byWorkspace[ws][sup] || 0) + 1;
    }
  }

  res.json({
    source: 'plusvibe-live-tags',
    lastRun: _mailboxCache.lastRun,
    total,
    allowed_suppliers: SUPPLIERS_ALLOWED,
    by_supplier: bySupplier,
    untagged,
    untagged_by_workspace: untaggedByWorkspace,
    by_workspace: byWorkspace,
    multi_tagged: multiTagged, // non-empty ⇒ these have >1 supplier tag in PV
  });
});

// Audit: how many live mailboxes carry each supplier tag (incl. UNTAGGED and
// any typo'd variants that won't match SUPPLIERS_ALLOWED). Use this to confirm
// every "Google Generic" mailbox actually landed on that exact string —
// mismatched strings get $0 unit cost and aren't excluded from domain cost.
app.get('/api/mailboxes/supplier-audit', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    const meta = pgdb ? await pgdb.listMailboxMeta() : [];
    const metaByEmail = new Map(meta.map(m => [m.email, m]));
    const merged = mergeMailboxesWithMeta(_mailboxCache.mailboxes || [], metaByEmail);

    const counts = {};        // supplier string → count
    let untagged = 0;
    for (const m of merged) {
      const s = m.supplier;
      if (!s) { untagged++; continue; }
      counts[s] = (counts[s] || 0) + 1;
    }
    // Flag any tag that isn't an exact allowed supplier (typos/variants).
    const unrecognised = Object.keys(counts).filter(s => !SUPPLIERS_ALLOWED.includes(s));

    res.json({
      total: merged.length,
      allowed_suppliers: SUPPLIERS_ALLOWED,
      by_supplier: counts,
      untagged,
      unrecognised_tags: unrecognised, // non-empty ⇒ these won't be costed correctly
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Assign supplier / type to a single mailbox.
app.put('/api/mailboxes/:email', requireSession, async (req, res) => {
  try {
    const email = decodeURIComponent(req.params.email || '').toLowerCase();
    if (!email.includes('@')) return res.status(400).json({ error: 'Invalid email' });
    const { supplier, mailbox_type, notes } = req.body || {};
    if (supplier && !SUPPLIERS_ALLOWED.includes(supplier)) return res.status(400).json({ error: 'Invalid supplier' });
    if (mailbox_type && !TYPES_ALLOWED.includes(mailbox_type)) return res.status(400).json({ error: 'Invalid type' });
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const row = await pgdb.upsertMailboxMeta(email, { supplier, mailbox_type, notes });
    res.json({ ok: true, row });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Bulk-assign supplier or type across many mailboxes at once.
// Find every Bison mailbox carrying a tag named "winnr" (case-insensitive),
// across all workspaces. EXCLUDES any mailbox whose DOMAIN contains bluehawk,
// hayes, or bybo — these are the BlueHawk/Hayes/Bybo sets that must NOT change.
// (NB: exclusion is by mailbox domain, NOT workspace name — BlueHawk lives inside
//  "Winnr Batch A" and Hayes inside "Winnr Batch B", so a workspace-level skip
//  would miss them.)
//   GET  /api/mailboxes/winnr-tagged                 → dry-run (list + count)
//   GET  /api/mailboxes/winnr-tagged?apply=10        → set daily_limit=10 on all
//   GET  /api/mailboxes/winnr-tagged?tag=WINNR%20Generic&apply=5  → other tag
// ?tag defaults to "winnr". Read-only by default; only mutates when ?apply=<int>.
const WINNR_TAG_EXCLUDE_DOMAINS = ['bluehawk', 'hayes', 'bybo'];
app.get('/api/mailboxes/winnr-tagged', requireSession, async (req, res) => {
  try {
    const tagName = (req.query.tag || 'winnr').toString().trim().toLowerCase();
    const applyLimit = req.query.apply != null ? parseInt(req.query.apply, 10) : null;
    if (applyLimit != null && (!Number.isInteger(applyLimit) || applyLimit < 0 || applyLimit > 1000)) {
      return res.status(400).json({ error: 'apply must be an integer 0–1000' });
    }
    // A mailbox is excluded if its domain contains any excluded brand.
    const isExcludedMailbox = email => {
      const domain = (email.split('@')[1] || '').toLowerCase();
      return WINNR_TAG_EXCLUDE_DOMAINS.some(x => domain.includes(x));
    };

    const perWorkspace = [];
    let totalMatched = 0, totalExcluded = 0, totalUpdated = 0;
    const errors = [];

    for (const team of BISON_TEAMS) {
      // ByboDigital is excluded as a whole workspace (its mailboxes aren't all on
      // a bybo* domain, so a domain filter wouldn't catch them).
      if ((team.name || '').toLowerCase().includes('bybo')) {
        perWorkspace.push({ workspace: team.name, team_id: team.team_id, skipped: 'excluded workspace', matched: 0 });
        continue;
      }
      try {
        // 1) find the requested tag id in this workspace (exact name, case-insensitive)
        const tagsResp = await bisonReq('/api/tags', { wsId: team.team_id });
        const tags = Array.isArray(tagsResp) ? tagsResp : (tagsResp?.data ?? []);
        const winnrTag = tags.find(t => (t.name || '').trim().toLowerCase() === tagName);
        if (!winnrTag) {
          perWorkspace.push({ workspace: team.name, team_id: team.team_id, no_tag: true, matched: 0 });
          continue;
        }
        // 2) page sender-emails filtered by that tag id; split into target vs excluded
        const target = [];   // will receive the daily-limit change
        const excluded = []; // bluehawk/hayes/bybo — left untouched
        let prevSig = '';
        for (let page = 1; page <= 300; page++) {
          const resp = await bisonReq('/api/sender-emails', {
            wsId: team.team_id,
            params: { per_page: 100, page, tag_ids: [winnrTag.id] },
          });
          const list = Array.isArray(resp) ? resp : (resp?.data ?? []);
          if (!list.length) break;
          const sig = list.map(a => a.id ?? a.email ?? '').join(',');
          if (sig === prevSig) break;
          prevSig = sig;
          for (const a of list) {
            if (a.id == null) continue;
            const email = (a.email || a.email_address || '').toLowerCase();
            const row = { id: a.id, email, daily_limit: a.daily_limit ?? null };
            if (isExcludedMailbox(email)) excluded.push(row);
            else target.push(row);
          }
        }
        totalMatched  += target.length;
        totalExcluded += excluded.length;

        // 3) apply daily-limit to the TARGET set only (never the excluded brands)
        let updated = 0;
        if (applyLimit != null && target.length) {
          const ids = target.map(m => m.id);
          await bisonReq('/api/sender-emails/daily-limits/bulk', {
            method: 'PATCH', wsId: team.team_id,
            body: { sender_email_ids: ids, daily_limit: applyLimit },
          });
          updated = ids.length;
          totalUpdated += updated;
        }
        perWorkspace.push({
          workspace: team.name, team_id: team.team_id, tag_id: winnrTag.id,
          matched: target.length, excluded: excluded.length, updated,
          mailboxes: target.map(m => m.email),
          excluded_mailboxes: excluded.map(m => m.email),
        });
      } catch (e) {
        errors.push({ workspace: team.name, team_id: team.team_id, error: e.message });
      }
    }

    res.json({
      tag: tagName,
      mode: applyLimit != null ? `applied daily_limit=${applyLimit}` : 'dry-run',
      excluded_domains: WINNR_TAG_EXCLUDE_DOMAINS,
      total_matched: totalMatched,
      total_excluded: totalExcluded,
      total_updated: totalUpdated,
      workspaces: perWorkspace,
      errors,
    });
  } catch (err) {
    console.error('[winnr-tagged]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// GET variant: audit by the 34 WINNR_GENERIC_ROOTS domains — no payload needed.
// Scans every workspace, finds every mailbox on a Winnr Generic root domain, and
// reports which carry the "winnr generic" tag vs which don't. Answers "where are
// the missing CSV mailboxes" from a plain browser GET.
//   GET /api/mailboxes/winnr-generic-audit
app.get('/api/mailboxes/winnr-generic-audit', requireSession, async (req, res) => {
  try {
    const onGenericDomain = email => WINNR_GENERIC_ROOTS.has(winnrRootOf((email.split('@')[1] || '')));
    const byRoot = {}; // root -> { total, tagged, untagged, untagged_emails[] }
    const scanErrors = [];
    let total = 0, tagged = 0, untagged = 0;

    for (const team of BISON_TEAMS) {
      try {
        let prevSig = '';
        for (let page = 1; page <= 300; page++) {
          const resp = await bisonReq('/api/sender-emails', { wsId: team.team_id, params: { per_page: 100, page } });
          const list = Array.isArray(resp) ? resp : (resp?.data ?? []);
          if (!list.length) break;
          const sig = list.map(a => a.id ?? a.email ?? '').join(',');
          if (sig === prevSig) break;
          prevSig = sig;
          for (const a of list) {
            const email = (a.email || a.email_address || '').toLowerCase();
            if (!email || !onGenericDomain(email)) continue;
            const root = winnrRootOf(email.split('@')[1] || '');
            const tags = Array.isArray(a.tags) ? a.tags.map(t => (t.name || '').trim().toLowerCase()) : [];
            const hasGeneric = tags.includes('winnr generic');
            const b = byRoot[root] = byRoot[root] || { total: 0, tagged: 0, untagged: 0, untagged_emails: [], workspace: team.name };
            b.total++; total++;
            if (hasGeneric) { b.tagged++; tagged++; }
            else { b.untagged++; untagged++; b.untagged_emails.push({ email, tags: a.tags ? a.tags.map(t=>t.name) : [], workspace: team.name }); }
          }
        }
      } catch (e) {
        scanErrors.push({ workspace: team.name, team_id: team.team_id, error: e.message });
      }
    }

    // roots present in CSV but with ZERO mailboxes found in Bison at all
    const missingRoots = [...WINNR_GENERIC_ROOTS].filter(r => !byRoot[r]).sort();

    res.json({
      total_on_generic_domains: total,
      tagged_winnr_generic: tagged,
      on_domain_but_untagged: untagged,
      roots_with_no_mailboxes_in_bison: missingRoots,
      per_root: byRoot,
      scan_errors: scanErrors,
    });
  } catch (err) {
    console.error('[winnr-generic-audit]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Read-only diagnostic: given a list of emails (e.g. the Winnr CSV), report for
// each whether it exists in Bison, in which workspace, and what tags it carries.
// Used to find why N CSV mailboxes aren't showing under a tag.
//   POST /api/mailboxes/tag-audit  { emails: ["a@x.com", ...] }
app.post('/api/mailboxes/tag-audit', requireSession, async (req, res) => {
  try {
    const emails = (req.body?.emails || []).map(e => String(e).trim().toLowerCase()).filter(Boolean);
    if (!emails.length) return res.status(400).json({ error: 'No emails provided' });
    const wanted = new Set(emails);

    // Build email -> { workspace, tags[] } by scanning every workspace's full roster.
    const found = new Map();
    const scanErrors = [];
    for (const team of BISON_TEAMS) {
      try {
        let prevSig = '';
        for (let page = 1; page <= 300; page++) {
          const resp = await bisonReq('/api/sender-emails', { wsId: team.team_id, params: { per_page: 100, page } });
          const list = Array.isArray(resp) ? resp : (resp?.data ?? []);
          if (!list.length) break;
          const sig = list.map(a => a.id ?? a.email ?? '').join(',');
          if (sig === prevSig) break;
          prevSig = sig;
          for (const a of list) {
            const email = (a.email || a.email_address || '').toLowerCase();
            if (!wanted.has(email)) continue;
            const tags = Array.isArray(a.tags) ? a.tags.map(t => t.name).filter(Boolean) : [];
            found.set(email, { workspace: team.name, team_id: team.team_id, id: a.id, tags });
          }
        }
      } catch (e) {
        scanErrors.push({ workspace: team.name, team_id: team.team_id, error: e.message });
      }
    }

    // Classify each requested email
    const inBisonUntaggedGeneric = [], inBisonWithGeneric = [], notInBison = [];
    for (const email of emails) {
      const hit = found.get(email);
      if (!hit) { notInBison.push(email); continue; }
      const hasGeneric = hit.tags.some(t => (t || '').trim().toLowerCase() === 'winnr generic');
      if (hasGeneric) inBisonWithGeneric.push({ email, ...hit });
      else inBisonUntaggedGeneric.push({ email, workspace: hit.workspace, tags: hit.tags });
    }

    res.json({
      requested: emails.length,
      in_bison_with_generic_tag: inBisonWithGeneric.length,
      in_bison_missing_generic_tag: inBisonUntaggedGeneric.length,
      not_in_bison: notInBison.length,
      detail: {
        missing_generic_tag: inBisonUntaggedGeneric,
        not_in_bison: notInBison,
      },
      scan_errors: scanErrors,
    });
  } catch (err) {
    console.error('[tag-audit]', err.message);
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/mailboxes/bulk-tag', requireSession, async (req, res) => {
  try {
    const { emails, field, value } = req.body || {};
    if (!Array.isArray(emails) || !emails.length) return res.status(400).json({ error: 'No emails' });
    if (!['supplier', 'mailbox_type'].includes(field)) return res.status(400).json({ error: 'Invalid field' });
    if (field === 'supplier' && value && !SUPPLIERS_ALLOWED.includes(value)) return res.status(400).json({ error: 'Invalid supplier' });
    if (field === 'mailbox_type' && value && !TYPES_ALLOWED.includes(value)) return res.status(400).json({ error: 'Invalid type' });
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const r = await pgdb.bulkSetMailboxField(emails.map(e => e.toLowerCase()), field, value || null);
    res.json({ ok: true, ...r });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Bulk-assign by domain — accepts a list of domains and tags every mailbox
// on any of those domains. Used when you know "everything @winnr-domain is
// Winnr" and don't want to click through individual rows.
app.post('/api/mailboxes/bulk-tag-by-domain', requireSession, async (req, res) => {
  try {
    const { domains, field, value } = req.body || {};
    if (!Array.isArray(domains) || !domains.length) return res.status(400).json({ error: 'No domains' });
    if (!['supplier', 'mailbox_type'].includes(field)) return res.status(400).json({ error: 'Invalid field' });
    if (field === 'supplier' && value && !SUPPLIERS_ALLOWED.includes(value)) return res.status(400).json({ error: 'Invalid supplier' });
    if (field === 'mailbox_type' && value && !TYPES_ALLOWED.includes(value)) return res.status(400).json({ error: 'Invalid type' });
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });

    const wanted = new Set(domains.map(d => d.toLowerCase().trim()));
    const emails = (_mailboxCache.mailboxes || [])
      .filter(m => wanted.has(m.domain))
      .map(m => m.email);
    if (!emails.length) return res.json({ ok: true, changed: 0, matched: 0, message: 'No mailboxes match those domains in the current cache.' });
    const r = await pgdb.bulkSetMailboxField(emails, field, value || null);
    res.json({ ok: true, matched: emails.length, ...r });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// One-shot supplier assignment from a structured payload. Use this to
// import a big block of "these domains are Winnr, these emails are
// Maildoso, default is Mithun" assignments in a single round-trip.
// Body shape:
// {
//   supplierDomains: { Winnr: ["x.co.uk", ...], Inboxing: [...] },
//   supplierEmails:  { Maildoso: ["james@x", ...] },
//   defaultSupplier: "Mithun"   // applied to every remaining mailbox that
//                               // isn't already tagged
// }
app.post('/api/mailboxes/assign-suppliers', requireSession, async (req, res) => {
  try {
    const { supplierDomains = {}, supplierEmails = {}, defaultSupplier = null } = req.body || {};
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });

    const allMailboxes = _mailboxCache.mailboxes || [];
    const assigned = new Map();   // email → supplier (first-match wins, in priority order)

    // 1) Explicit email assignments — highest precedence.
    for (const [supplier, emails] of Object.entries(supplierEmails)) {
      for (const e of (emails || [])) {
        const k = e.toLowerCase().trim();
        if (k && !assigned.has(k)) assigned.set(k, supplier);
      }
    }
    // 2) Domain assignments — fill in anything not already explicit.
    for (const [supplier, domains] of Object.entries(supplierDomains)) {
      const wanted = new Set((domains || []).map(d => d.toLowerCase().trim()));
      for (const m of allMailboxes) {
        if (wanted.has(m.domain) && !assigned.has(m.email)) assigned.set(m.email, supplier);
      }
    }
    // 3) Default supplier — every untagged mailbox in the cache.
    if (defaultSupplier) {
      for (const m of allMailboxes) {
        if (!assigned.has(m.email)) assigned.set(m.email, defaultSupplier);
      }
    }

    // 4) Clear supplier for any mailbox not assigned and no default set.
    // Always clear from DB (don't rely on cache having supplier field).
    const toClear = [];
    if (!defaultSupplier) {
      for (const m of allMailboxes) {
        if (!assigned.has(m.email)) toClear.push(m.email);
      }
      if (toClear.length) await pgdb.bulkSetMailboxField(toClear, 'supplier', null);
    }

    // Group by supplier and run one bulk write per group.
    const bySupplier = {};
    for (const [email, sup] of assigned) {
      (bySupplier[sup] ||= []).push(email);
    }
    const result = {};
    for (const [sup, emails] of Object.entries(bySupplier)) {
      const r = await pgdb.bulkSetMailboxField(emails, 'supplier', sup);
      result[sup] = { matched: emails.length, changed: r.changed };
    }
    res.json({ ok: true, totalAssigned: assigned.size, cleared: toClear.length, result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Bulk set billing date + renewal day for a selection of mailboxes.
// Accepts: { emails?, domains?, supplier?, billing_start_date, billing_day }
// If emails not supplied, resolves from domains/supplier against the live cache.
app.post('/api/mailboxes/bulk-billing', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    let { emails, domains, supplier, billing_start_date, billing_day } = req.body || {};
    if (!billing_start_date) return res.status(400).json({ error: 'billing_start_date required (YYYY-MM-DD)' });
    billing_day = parseInt(billing_day || new Date(billing_start_date).getDate());

    // Resolve email list from domains/supplier if not explicitly given.
    if (!Array.isArray(emails) || !emails.length) {
      const all = _mailboxCache.mailboxes || [];
      const wantedDomains = new Set((domains || []).map(d => d.toLowerCase().trim()));
      emails = all.filter(m => {
        if (supplier && (m.supplier || '') !== supplier) return false;
        if (wantedDomains.size && !wantedDomains.has(m.domain)) return false;
        return true;
      }).map(m => m.email);
    }
    if (!emails.length) return res.json({ ok: true, changed: 0, message: 'No mailboxes matched' });

    const r = await pgdb.bulkSetBilling(emails, billing_start_date, billing_day);
    console.log(`[mailboxes] billing set for ${r.changed} mailboxes: start=${billing_start_date} day=${billing_day}`);
    res.json({ ok: true, ...r });
  } catch (err) {
    console.error('[mailboxes] bulk-billing error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Per-row billing import from spreadsheet: [{email, billing_start_date}]
app.post('/api/mailboxes/bulk-billing-rows', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const { rows } = req.body || {};
    if (!Array.isArray(rows) || !rows.length) return res.status(400).json({ error: 'rows array required' });
    for (const row of rows) {
      if (!row.email || !row.billing_start_date) return res.status(400).json({ error: 'each row needs email + billing_start_date' });
    }
    const r = await pgdb.bulkSetBillingRows(rows);
    console.log(`[mailboxes] per-row billing import: ${r.changed} rows updated`);
    res.json({ ok: true, ...r });
  } catch (err) {
    console.error('[mailboxes] bulk-billing-rows error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Hide mailboxes from the dashboard without touching PlusVibe.
// Sets ignored_at so they're filtered out of GET /api/mailboxes.
app.post('/api/mailboxes/bulk-remove', requireSession, async (req, res) => {
  try {
    const pgdb = app.locals.pgDb;
    if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
    const { emails } = req.body || {};
    if (!Array.isArray(emails) || !emails.length) return res.status(400).json({ error: 'emails array required' });
    const lower = emails.map(e => e.toLowerCase());
    const placeholders = lower.map((_, i) => `($${i + 1}, NOW())`).join(', ');
    const { rowCount } = await pgdb.query(
      `INSERT INTO mailbox_meta (email, ignored_at)
       VALUES ${placeholders}
       ON CONFLICT (email) DO UPDATE SET ignored_at = NOW()`,
      lower
    );
    console.log(`[mailboxes] bulk-remove: ${lower.length} mailboxes hidden`);
    res.json({ ok: true, removed: lower.length });
  } catch (err) {
    console.error('[mailboxes] bulk-remove error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/mailboxes/enable-warmup', requireSession, async (req, res) => {
  try {
    const { emails } = req.body || {};
    if (!Array.isArray(emails) || !emails.length) return res.status(400).json({ error: 'emails array required' });

    const cache = _mailboxCache?.mailboxes || [];
    const byWorkspace = {};
    const missing = [];
    for (const email of emails) {
      const m = cache.find(x => x.email === email);
      if (!m || !m.account_id || !m.workspace_id) { missing.push(email); continue; }
      if (!byWorkspace[m.workspace_id]) byWorkspace[m.workspace_id] = [];
      byWorkspace[m.workspace_id].push(m.account_id);
    }

    const results = [];
    for (const [workspace_id, ids] of Object.entries(byWorkspace)) {
      const r = await pvApi('/account/bulk-update-warmup', {
        method: 'PATCH', wsId: workspace_id,
        body: { workspace_id, ids, warmup_status: 'ACTIVE' },
      });
      results.push({ workspace_id, count: ids.length, result: r });
    }

    const enabled = results.reduce((s, r) => s + r.count, 0);
    console.log(`[mailboxes] enable-warmup: ${enabled} accounts updated, ${missing.length} skipped`);
    res.json({ ok: true, enabled, missing, results });
  } catch (err) {
    console.error('[mailboxes] enable-warmup error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

