app.get('/api/pv/workspaces', requireSession, async (req, res) => {
  // Source the client list from the local clients table — the live PlusVibe API
  // key is deprecated, and Bison's /api/workspaces only returns the token's own
  // team (not all clients). The clients table has every client keyed by its
  // PlusVibe workspace_id (used for the filter, cooldown, and PV push).
  try {
    if (db && db.prepare) {
      const rows = db.prepare(
        `SELECT workspace_id, workspace_name FROM clients
          WHERE workspace_id IS NOT NULL AND workspace_id != '' ORDER BY workspace_name`
      ).all();
      if (rows.length) {
        return res.json({ workspaces: rows.map(r => ({ _id: r.workspace_id, name: r.workspace_name })) });
      }
    }
    // Fallback: Bison workspaces if the clients table is empty.
    const data = listBisonWorkspaces();
    const workspaces = Array.isArray(data) ? data : (data?.data || []);
    res.json({ workspaces: workspaces.map(w => ({ _id: String(w.id), name: w.name })) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ── Performance/Actions compatibility shim ───────────────────
// performance.html and actions.html were written against the (now deprecated)
// PlusVibe browser API. Rather than rewrite their rendering logic, these routes
// reproduce the exact response shapes those pages already parse, but sourced
// from EmailBison. The pages call /api/perfshim/* same-origin with the session
// cookie; we map their PlusVibe workspace_id -> Bison team_id via BISON_TEAMS.
// Every route degrades to an empty-but-valid shape (never a 500) so the pages
// keep rendering even when Bison errors or a workspace isn't mapped to a team.
function perfshimTeamId(workspace_id) {
  const team = BISON_TEAMS.find(t => t.pv === String(workspace_id));
  return team ? team.team_id : null;
}

// 0. GET /workspaces — the list actions.html / performance.html load on init.
// Returns a bare array of { id, name } keyed by PV workspace_id (t.pv), which is
// the id the page then passes back as ?workspace_id= to every other perfshim
// route (mapped to a Bison team via perfshimTeamId) and matches /api/client-status.
// Without this the page 404s on init and shows "Failed to load clients".
app.get('/api/perfshim/workspaces', requireSession, (req, res) => {
  try {
    res.json(BISON_TEAMS.map(t => ({ id: t.pv, name: t.name })));
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// 1. GET /account/email-stats — summed totals for a workspace + date range.
// Source: Bison line-area-chart-stats (stateful: bisonReq wsId switches the
// workspace first), pivoted via pivotBisonStats and summed via aggPvEmailStats.
// Returns { header: { ...totals } } which aggEmailStats() reads directly.
app.get('/api/perfshim/account/email-stats', requireSession, async (req, res) => {
  const { workspace_id, start_date, end_date } = req.query;
  const empty = { header: { total_sent_count: 0, total_reply_count: 0, total_ooo_reply_count: 0, total_pos_reply_count: 0, total_bounce_count: 0, total_contacted_count: 0 } };
  try {
    const wsId = perfshimTeamId(workspace_id);
    if (!wsId) return res.json(empty);
    // Bison's line-area-chart-stats OMITS the current incomplete day on a
    // single-day (start==end) query — so "today" reads 0 even when sends
    // happened (this is why the health scan showed 0 sent for clients that
    // sent today). Fetch one day wider and slice back to the requested window
    // so today is accurate. Same workaround the Stats page uses.
    let fetchStart = start_date;
    if (start_date && start_date === end_date) {
      const d = new Date(start_date + 'T00:00:00Z');
      d.setUTCDate(d.getUTCDate() - 1);
      fetchStart = d.toISOString().slice(0, 10);
    }
    const bStats = await pvApi('/account/email-stats', {
      wsId,
      params: { start_date: fetchStart, end_date },
    });
    const pivoted = pivotBisonStats(bStats);
    // keep only rows inside the REQUESTED window (drop the extra padding day).
    const rows = Object.values(pivoted).filter(r => r.date >= start_date && r.date <= end_date);
    const agg = aggPvEmailStats(rows); // { sent, replies, oooReplies, posReplies, bounces, contacted }
    res.json({ header: {
      total_sent_count:      agg.sent,
      total_reply_count:     agg.replies,
      total_ooo_reply_count: agg.oooReplies,
      total_pos_reply_count: agg.posReplies,
      total_bounce_count:    agg.bounces,
      total_contacted_count: agg.contacted,
    } });
  } catch (err) {
    console.warn('[perfshim] email-stats failed for ws', workspace_id, '-', err.message);
    res.json(empty);
  }
});

// 2. GET /analytics/campaign/stats — array of campaigns for renderCampaigns()/agg().
// Source: Bison /api/campaigns mapped to the PV campaign-stat field names.
app.get('/api/perfshim/analytics/campaign/stats', requireSession, async (req, res) => {
  const { workspace_id } = req.query;
  try {
    const wsId = perfshimTeamId(workspace_id);
    if (!wsId) return res.json([]);
    const data = await pvApi('/campaign/list', { wsId });
    const arr = Array.isArray(data) ? data : (data?.data || data?.campaigns || []);
    const list = arr.map(c => ({
      camp_name:            c.name,
      name:                 c.name,
      status:               c.status,
      sent_count:           c.emails_sent || c.sent_count || 0,
      replied_count:        c.replied || c.replied_count || 0,
      ooo_reply_count:      0,
      positive_reply_count: 0,
      bounced_count:        c.bounced || c.bounced_count || 0,
      lead_contacted_count: c.total_leads_contacted || 0,
    }));
    res.json(list);
  } catch (err) {
    console.warn('[perfshim] campaign/stats failed for ws', workspace_id, '-', err.message);
    res.json([]);
  }
});

// 3. GET /account/list — sending accounts for renderSummary() capacity calc.
// Source: Bison /api/sender-emails. status connected -> 'ACTIVE'; daily_limit
// nested under payload (the page reads a.status === 'ACTIVE' and a.payload.daily_limit).
app.get('/api/perfshim/account/list', requireSession, async (req, res) => {
  const { workspace_id } = req.query;
  try {
    const wsId = perfshimTeamId(workspace_id);
    if (!wsId) return res.json([]);
    const list = await bisonListSenderEmails(wsId); // paginated — Bison caps ~15/page
    const accounts = list.map(a => {
      const connected = a.status === 'connected' || a.is_connected === true;
      const paused = a.status === 'paused';
      return {
        status: connected ? 'ACTIVE' : (paused ? 'PAUSED' : 'INACTIVE'),
        payload: { daily_limit: typeof a.daily_limit === 'number' ? a.daily_limit : 0 },
      };
    });
    res.json(accounts);
  } catch (err) {
    console.warn('[perfshim] account/list failed for ws', workspace_id, '-', err.message);
    res.json([]);
  }
});

// 4. GET /account/warmup-stats — { emailAcc: { inbox_percent, total_inboxes } }.
// total_inboxes = count of sender emails with warmup enabled (accurate).
// inbox_percent: Bison has no direct "inbox placement %" equivalent in the
// sender-emails payload, so we return 0 rather than fabricate a misleading
// number. renderSummary() shows '—' when inbox_percent is 0/absent.
app.get('/api/perfshim/account/warmup-stats', requireSession, async (req, res) => {
  const { workspace_id } = req.query;
  const empty = { emailAcc: { inbox_percent: 0, total_inboxes: 0 } };
  try {
    const wsId = perfshimTeamId(workspace_id);
    if (!wsId) return res.json(empty);
    const list = await bisonListSenderEmails(wsId); // paginated — Bison caps ~15/page
    const warming = list.filter(a => (a.warmup_enabled ?? a.warmup?.enabled) === true).length;
    res.json({ emailAcc: { inbox_percent: 0, total_inboxes: warming } });
  } catch (err) {
    console.warn('[perfshim] warmup-stats failed for ws', workspace_id, '-', err.message);
    res.json(empty);
  }
});

// 5. GET /lead/count/lead-status — { NOT_CONTACTED, CONTACTED, REPLIED, BOUNCED, COMPLETED }.
// Bison has no direct lead-status-count endpoint, so we derive what we can from
// campaign aggregates: CONTACTED = sum(total_leads_contacted), REPLIED = sum(replied),
// BOUNCED = sum(bounced). NOT_CONTACTED and COMPLETED have no Bison equivalent
// here, so they're 0 (accurate-or-zero, never fabricated).
app.get('/api/perfshim/lead/count/lead-status', requireSession, async (req, res) => {
  const { workspace_id } = req.query;
  const empty = { NOT_CONTACTED: 0, CONTACTED: 0, REPLIED: 0, BOUNCED: 0, COMPLETED: 0 };
  try {
    const wsId = perfshimTeamId(workspace_id);
    if (!wsId) return res.json(empty);
    const data = await pvApi('/campaign/list', { wsId });
    const arr = Array.isArray(data) ? data : (data?.data || data?.campaigns || []);
    const out = { ...empty };
    arr.forEach(c => {
      out.CONTACTED += c.total_leads_contacted || 0;
      out.REPLIED   += c.replied || c.replied_count || 0;
      out.BOUNCED   += c.bounced || c.bounced_count || 0;
    });
    res.json(out);
  } catch (err) {
    console.warn('[perfshim] lead-status failed for ws', workspace_id, '-', err.message);
    res.json(empty);
  }
});

// 6. GET /lead/workspace-leads — per-label lead listing (used by fetchLabeledLeads).
// Now Bison-backed via bisonWorkspaceLeads (label → filters[lead_campaign_status]).
app.get('/api/perfshim/lead/workspace-leads', requireSession, async (req, res) => {
  const { workspace_id, label, page, limit } = req.query;
  if (!workspace_id) return res.json([]);
  try {
    const leads = await bisonWorkspaceLeads(workspace_id, {
      label, page: parseInt(page) || 1, perPage: parseInt(limit) || 100,
    });
    res.json(leads);
  } catch { res.json([]); } // pages tolerate empty; never error the scan
});

app.get('/api/pv/campaigns', requireSession, async (req, res) => {
  const { workspace_id } = req.query;
  if (!workspace_id) return res.status(400).json({ error: 'Missing workspace_id' });
  try {
    // PlusVibe /campaign/list returns a bare array of {id,name,status,...}.
    const data = await pvApi('/campaign/list', { wsId: workspace_id });
    const arr = Array.isArray(data) ? data : (data?.data || data?.campaigns || []);
    const list = arr.map(c => ({
      id: c.id || c._id,
      name: c.name,          // contacts.html renders c.name in the dropdown
      camp_name: c.name,     // older callers expect camp_name
      status: c.status,
    }));
    res.json({ list });
  } catch (err) { res.status(502).json({ error: err.message }); }
});

// Return full contact rows for a list of ids. Lets the client gather a selection
// that spans MANY pages (e.g. "select all 500") before handing it to the Solar
// page — the grid only holds the visible page, so filtering it client-side
// truncated big selections. Capped to keep the response sane.
app.post('/api/contacts/by-ids', requireSession, async (req, res) => {
  const db = req.app.locals.pgDb;
  if (!db || !db.getContactsById) return res.status(500).json({ error: 'Contacts DB not available' });
  const ids = Array.isArray(req.body && req.body.ids) ? req.body.ids.filter(Boolean).slice(0, 10000) : [];
  if (!ids.length) return res.status(400).json({ error: 'ids[] required' });
  try {
    const contacts = await db.getContactsById(ids);
    res.json({ contacts, count: contacts.length });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Sendability check ─────────────────────────────────────
// The contacts list answers "who matches this filter". The push answers "who
// may we actually email". Those diverged: a filter could show 2,095 contacts
// while the push pushed 0, because the guards below live only in the push
// paths. That surprise is the whole reason this endpoint exists.
//
// It runs the SAME guard functions the push uses (buildCrossClientGuard,
// getDepartedEmails, the cooloff date, PUSHABLE_STATUSES) over a set of
// contacts and reports how many would survive, with a per-reason breakdown.
// Reusing the functions — rather than re-expressing the rules in SQL — is
// deliberate: it is the only way the two numbers cannot drift apart again.
app.post('/api/contacts/sendability', requireSession, async (req, res) => {
  const db = req.app.locals.pgDb;
  if (!db || !db.searchContacts) return res.status(500).json({ error: 'Contacts DB not available' });

  const body = req.body || {};
  const workspaceId   = String(body.workspace_id || '').trim();
  const workspaceName = String(body.workspace_name || '').trim();
  const campaignName  = String(body.campaign_name || '').trim();
  const filters       = body.filters && typeof body.filters === 'object' ? body.filters : {};
  // Loose mirrors the push flag: engine leads only need "not invalid".
  const loose = body.loose === true;
  // Mirrors the push modal's default pair; callers may pass their own buckets.
  const allowedStatuses = Array.isArray(body.allowedStatuses) && body.allowedStatuses.length
    ? body.allowedStatuses.map(x => String(x).toLowerCase())
    : ['safe', 'safe_catchall'];
  const pushableStatuses = new Set(allowedStatuses);

  // Sampling bound. A filter can match 200k rows; running the guards over all
  // of them on every keystroke would be its own outage. Check a bounded slice
  // and report the rate, so the UI can extrapolate honestly rather than lie
  // with a precise-looking number.
  const SAMPLE_CAP = Math.min(parseInt(body.sample || '5000', 10) || 5000, 20000);

  try {
    // NB: searchContacts' first arg is the contacts-DB TENANT scope, NOT the
    // PlusVibe workspace_id the guards target. Two separate mistakes lived
    // here: passing the PlusVibe id (matched no rows), then reading
    // req.workspaceId — which is set by setWorkspace middleware mounted on the
    // CONTACTS ROUTER only, so it is undefined in this file. Resolve it the
    // same way that middleware does, or the query scopes to undefined and the
    // badge reports "unknown" on a filter that plainly has rows.
    const tenantId = req.user?.workspace_id || req.headers['x-workspace-id'] || 'ottaly-global';
    const [contacts, total] = await Promise.all([
      db.searchContacts(tenantId, filters, SAMPLE_CAP, 0),
      db.getContactsCount(tenantId, filters),
    ]);

    const skipped = {
      unsafe: 0, dnc: 0, departed: 0, missingName: 0, alreadyInCampaign: 0,
      cooldownWorkspace: 0, verticalCollision: 0, burstGap: 0, densityCeiling: 0,
      snoozed: 0,
    };

    const crossClientGuard = buildCrossClientGuard(workspaceId, workspaceName);
    const campaignVertical = detectVertical((campaignName || '') + ' ' + (workspaceName || ''), workspaceId);
    const cooloffDate = sameClientCooloffDate();
    const today = new Date().toISOString().slice(0, 10);
    const targetCampLc = campaignName.toLowerCase();
    const departed = await getDepartedEmails(db);

    // When the caller is about to SELECT (not just display a count), it needs
    // the actual ids that pass — otherwise "select all" re-selects the blocked
    // ones and the push silently discards them again.
    const wantIds = body.return_ids === true;
    const sendableIds = [];
    let sendable = 0;
    for (const c of contacts) {
      // Deliverability. Mirrors the push: loose accepts anything not invalid,
      // strict accepts only the safe pair.
      const status = String(c.email_status || '').toLowerCase();
      if (loose) {
        if (status === 'invalid') { skipped.unsafe++; continue; }
      } else if (!pushableStatuses.has(status)) {
        skipped.unsafe++; continue;
      }
      if (c.do_not_contact) { skipped.dnc++; continue; }
      if (departed.has(String(c.email || '').toLowerCase())) { skipped.departed++; continue; }
      if (!loose && (!(c.first_name && c.first_name.trim()) || !(c.last_name && c.last_name.trim()))) {
        skipped.missingName++; continue;
      }

      // Already in this campaign (full history, then the legacy single field).
      let pushed = [];
      try {
        pushed = Array.isArray(c.pushed_campaigns) ? c.pushed_campaigns
               : JSON.parse(c.pushed_campaigns || '[]');
      } catch { pushed = []; }
      if (workspaceId && pushed.some(pc => pc.workspace_id === workspaceId
          && (targetCampLc && String(pc.campaign_name || '').toLowerCase() === targetCampLc))) {
        skipped.alreadyInCampaign++; continue;
      }
      if (targetCampLc && c.last_campaign_name
          && String(c.last_campaign_name).toLowerCase() === targetCampLc) {
        skipped.alreadyInCampaign++; continue;
      }

      // Same-client cooloff.
      if (workspaceId && cooloffDate) {
        let emailed = {};
        try {
          emailed = typeof c.emailed_workspaces === 'string'
            ? JSON.parse(c.emailed_workspaces || '{}') : (c.emailed_workspaces || {});
        } catch { emailed = {}; }
        const info = emailed[workspaceId];
        const stamp = info ? (info.pushed_at > info.last_sent ? info.pushed_at : info.last_sent) : '';
        if (stamp && stamp >= cooloffDate) { skipped.cooldownWorkspace++; continue; }
      }

      // Vertical snooze.
      if (campaignVertical) {
        let snoozes = [];
        try {
          snoozes = Array.isArray(c.snoozed_verticals) ? c.snoozed_verticals
                  : JSON.parse(c.snoozed_verticals || '[]');
        } catch { snoozes = []; }
        if (snoozes.some(s => s.vertical === campaignVertical && s.until >= today)) {
          skipped.snoozed++; continue;
        }
      }

      // Cross-client spacing (vertical collision → burst gap → density ceiling).
      if (!crossClientGuard(c, skipped)) continue;
      sendable++;
      if (wantIds) sendableIds.push(c.id);
    }

    const checked = contacts.length;
    // `estimated` = the sample rate applied to the true total. Flagged so the
    // UI can show "~" rather than implying an exact count it did not measure.
    const rate = checked > 0 ? sendable / checked : 0;
    const estimated = checked < total;

    res.json({
      total,
      checked,
      sendable,
      blocked: checked - sendable,
      sendableTotal: estimated ? Math.round(total * rate) : sendable,
      estimated,
      reasons: skipped,
      ...(wantIds ? { ids: sendableIds } : {}),
    });
  } catch (e) {
    console.error('[sendability]', e);
    res.status(500).json({ error: e.message });
  }
});

// ── Departed contacts ─────────────────────────────────────
// Addresses whose owner told us, in writing, that they have left the company
// ("I have now left Lifeplan Products Ltd"). Blocked on every push path, for
// every client and every vertical — unlike the other reply facts, this is not
// a judgement call: there is no campaign where mailing a dead mailbox is
// correct, and it is usually an auto-reply, so we would never see a bounce.
//
// Scoped to the EMAIL, never the domain: the company is still a good prospect,
// and the reply often names the replacement, who must stay mailable.
//
// This is a suppression, not a data change: contacts.do_not_contact is a bare
// boolean with no reason column, so writing to it would be indistinguishable
// from a bounce-driven DNC and impossible to undo selectively. Reading the
// facts at push time keeps it reversible — delete the fact and the address is
// live again.
let _departedCache = { at: 0, set: new Set() };
async function getDepartedEmails(pgdb) {
  if (!pgdb) return new Set();
  // A push is a burst of calls; 60s keeps them consistent without re-querying
  // 1k+ rows per path.
  if (Date.now() - _departedCache.at < 60000) return _departedCache.set;
  try {
    const r = await pgdb.query(
      `SELECT DISTINCT LOWER(lead_email) AS email FROM reply_facts WHERE attribute = 'person_left'`
    );
    _departedCache = { at: Date.now(), set: new Set(r.rows.map(x => x.email)) };
  } catch (err) {
    // Never fail a push because this lookup broke — but say so loudly, because
    // an empty set silently disables the block.
    console.error('[departed] lookup failed, NOT blocking departed contacts:', err.message);
    return new Set();
  }
  return _departedCache.set;
}

// ── PlusVibe — push contacts to campaign ──────────────────
app.post('/api/pv/push-contacts', requireSession, async (req, res) => {
  const { workspace_id, campaign_id, contact_ids } = req.body;
  if (!workspace_id || !campaign_id || !Array.isArray(contact_ids) || contact_ids.length === 0) {
    return res.status(400).json({ error: 'workspace_id, campaign_id and contact_ids required' });
  }
  try {
    const db = req.app.locals.pgDb;
    if (!db) return res.status(500).json({ error: 'Database not available' });

    // Fetch all contact details (batch query)
    const allContacts = await db.getContactsById(contact_ids);
    if (allContacts.length === 0) return res.status(404).json({ error: 'No contacts found' });

    // Same dedup/cooldown filter as /verify-and-push — per-workspace
    // 60-day cooldown + per-campaign skip. Verification is the caller's
    // job on this path (this endpoint is 'push without verify').
    const cooloffDate = sameClientCooloffDate();
    const campaignNameLc = (req.body.campaign_name || '').toString().trim().toLowerCase();
    const skipped = { unsafe: 0, dnc: 0, cooldownWorkspace: 0, verticalCollision: 0, burstGap: 0, densityCeiling: 0, alreadyInCampaign: 0, missingEnrichment: 0, missingName: 0 };
    const crossClientGuard = buildCrossClientGuard(workspace_id, req.body.workspace_name || '');
    // Status gate. The user picks which verification-result buckets to push via
    // the modal (allowed_statuses). Validate against the known vocabulary; default
    // to the safe pair when absent so existing callers are unchanged. NULL/empty
    // email_status is never pushable regardless of selection.
    const KNOWN_STATUSES = ['safe', 'safe_catchall', 'unknown', 'risky', 'invalid'];
    const reqStatuses = Array.isArray(req.body.allowed_statuses)
      ? req.body.allowed_statuses.map(s => String(s).toLowerCase()).filter(s => KNOWN_STATUSES.includes(s))
      : [];
    const PUSHABLE_STATUSES = new Set(reqStatuses.length ? reqStatuses : ['safe', 'safe_catchall']);
    const departed = await getDepartedEmails(db);
    const contacts = allContacts.filter(c => {
      if (!PUSHABLE_STATUSES.has((c.email_status || '').toLowerCase())) { skipped.unsafe++; return false; }
      if (c.do_not_contact) { skipped.dnc++; return false; }
      if (departed.has(String(c.email || '').toLowerCase())) { skipped.departed = (skipped.departed || 0) + 1; return false; }
      // Bison requires non-empty first_name AND last_name (422s otherwise), and a
      // nameless contact shouldn't be cold-emailed anyway — skip and report.
      if (!(c.first_name && c.first_name.trim()) || !(c.last_name && c.last_name.trim())) {
        skipped.missingName++; return false;
      }
      if ((!c.keywords || c.keywords.trim() === '') || (!c.industry || c.industry.trim() === '')) {
        skipped.missingEnrichment++; return false;
      }
      if (campaignNameLc && c.last_campaign_name
          && c.last_campaign_name.toLowerCase() === campaignNameLc) {
        skipped.alreadyInCampaign++; return false;
      }
      if (workspace_id) {
        const emailed = typeof c.emailed_workspaces === 'string'
          ? JSON.parse(c.emailed_workspaces || '{}')
          : (c.emailed_workspaces || {});
        const lastSent = emailed[workspace_id]?.last_sent;
        if (cooloffDate && lastSent && lastSent >= cooloffDate) { skipped.cooldownWorkspace++; return false; }
      }
      // Cross-client spacing: same vertical, then any client inside 30 days.
      if (!crossClientGuard(c, skipped)) return false;
      return true;
    });
    console.log(`[push-contacts] filtered ${allContacts.length} → ${contacts.length}`, skipped);
    if (contacts.length === 0) {
      return res.json({ success: true, pushed: 0, total: 0, skipped });
    }

    const leads = contacts.map(c => {
      const raw = typeof c.raw_data === 'string' ? JSON.parse(c.raw_data || '{}') : (c.raw_data || {});

      return {
        // Native PlusVibe fields — go at top level so they populate the
        // matching form fields (and resolve {{merge_tag}} in templates).
        email: c.email,
        first_name: c.first_name || '',
        last_name: c.last_name || '',
        phone_number: c.phone || '',
        company_name: c.company_name || '',
        company_website: c.company_domain || '',
        address_line: c.company_address || raw['Company Address'] || raw['Address Line'] || raw.Address || '',
        // Company is the default location target (per spec): native city/state/
        // country carry COMPANY location so {{city}}/{{state}}/{{country}}
        // resolve to the company. Person is exposed via {{person_*}} custom vars.
        city: c.company_city || c.city || raw['Company City'] || raw.City || '',
        state: c.company_county || c.company_state || c.state || raw['Company State'] || '',
        country: c.company_country || c.country || raw['Company Country'] || raw.Country || '',
        job_title: c.job_title || '',
        department: c.department || '',
        industry: raw.Industry || c.industry || '',
        linkedin_person_url: c.linkedin_url || '',
        linkedin_company_url: c.company_linkedin_url || '',
        custom_variables: {
          job_title_cleaned: c.job_title_cleaned || '',
          seniority: c.seniority || '',
          sub_departments: c.sub_departments || '',
          company_city: c.company_city || raw['Company City'] || '',
          company_state: c.company_state || raw['Company State'] || '',
          company_country: c.company_country || raw['Company Country'] || '',
          num_employees: c.num_employees || raw['Employees'] || '',
          corporate_phone: c.corporate_phone || '',
          company_phone: c.company_phone || raw['Company Phone'] || '',
          apollo_id: c.apollo_id || '',
          apollo_person_id: c.apollo_person_id || '',
          technologies: raw.Technologies || c.technologies || '',
          keywords: raw.Keywords || c.keywords || '',
          ...raw,
          // Location hierarchy last so clean normalised values win over raw.
          ...locationCustomVars(c)
        }
      };
    });

    // Reserve BEFORE pushing. The stamp used to run after the push and was
    // fire-and-forget, so two concurrent pushes to different workspaces both
    // read pre-stamp state and both passed the cross-client guard — which is
    // how one contact reached seven workspaces in five days. Stamping first
    // and awaiting it makes the guard authoritative.
    //
    // Deliberate trade-off: if the PlusVibe call then fails, these contacts
    // stay reserved and sit out the cooldown despite never being emailed. We
    // lose a few leads rather than risk emailing someone twice.
    const pushedIds = contacts.map(c => c.id).filter(Boolean);
    if (pushedIds.length && db.stampPushedCampaign) {
      try {
        await db.stampPushedCampaign(pushedIds, workspace_id, campaign_id, req.body.campaign_name || '');
      } catch (err) {
        console.error('[push-contacts] reserve failed, aborting push:', err.message);
        return res.status(500).json({ error: 'Could not reserve contacts before push: ' + err.message });
      }
    }

    const BATCH = 100;
    let pushed = 0;
    for (let i = 0; i < leads.length; i += BATCH) {
      const batch = leads.slice(i, i + BATCH);
      // PlusVibe: top-level native fields (no custom_variables for industry/city/etc.)
      var pvLeadPayload = batch
        .filter(function(l){ return l.first_name && String(l.first_name).trim() && l.last_name && String(l.last_name).trim(); })
        .map(function(l) {
          return {
            email: l.email,
            first_name: l.first_name || null,
            last_name:  l.last_name  || null,
            job_title:  l.job_title  || l.title || null,
            company_name:        l.company_name || l.company || null,
            phone_number:        l.phone_number || null,
            city:                l.city         || null,
            state:               l.state        || null,
            country:             l.country      || null,
            industry:            l.industry     || null,
            linkedin_person_url: l.linkedin_person_url  || null,
            linkedin_company_url:l.linkedin_company_url || null,
            company_website:     l.company_website      || null,
            department:          l.department           || null,
            address_line:        l.address_line         || null,
          };
        })
        .map(function(l){
          var s = sanitizePvLead(l);
          if (s.reason) console.warn('[pv-push] ' + s.reason);
          return s.lead;
        });
      if (!pvLeadPayload.length) { continue; }
      // PlusVibe batch add + campaign assignment in one call.
      try {
        await pvApi('/lead/add', { method: 'POST', wsId: workspace_id, body: { workspace_id, campaign_id, leads: pvLeadPayload } });
        pushed += pvLeadPayload.length;
      } catch (e) { console.warn('[pv-push] lead add failed:', e.message); }
    }

    res.json({ success: true, pushed, total: leads.length, skipped });
  } catch (err) {
    console.error('[PV Push]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// ── Push to EmailBison (reuses the existing bisonFetch/bisonSwitch helpers) ──
// Separate path from PlusVibe (PV endpoint above unchanged). Bison 2-step:
// create/update leads → import-by-ids into the campaign, after switch-workspace.

// Free / consumer / generic email domains that should never appear in a B2B
// outbound campaign. Reacher can't catch spam traps on aged domains like email.com.
// This list gates both the push-to-Bison path and the import classifier.
const FREE_EMAIL_DOMAINS = new Set([
  // Big consumer webmail
  'gmail.com','googlemail.com',
  'yahoo.com','yahoo.co.uk','yahoo.fr','yahoo.de','yahoo.es','yahoo.it',
  'hotmail.com','hotmail.co.uk','hotmail.fr','hotmail.de','hotmail.es',
  'outlook.com','outlook.co.uk',
  'live.com','live.co.uk',
  'msn.com',
  'icloud.com','me.com','mac.com',
  'aol.com','aim.com',
  'protonmail.com','proton.me',
  'zoho.com',
  'mail.com','email.com','usa.com','post.com',   // mail.com group — spam trap risk
  // UK consumer
  'btinternet.com','btopenworld.com',
  'sky.com','talk21.com','talktalk.net',
  'ntlworld.com','virgin.net','virginmedia.com',
  'blueyonder.co.uk',
  // Common free/disposable
  'yopmail.com','mailinator.com','guerrillamail.com','10minutemail.com',
  'throwaway.email','tempmail.com','temp-mail.org','dispostable.com',
  'sharklasers.com','guerrillamailblock.com','grr.la','spam4.me',
  // Generic catch-alls that appear in B2B lists but aren't companies
  'example.com','test.com','sample.com',
]);

function isFreeDomain(email) {
  const domain = (email || '').split('@')[1] || '';
  return FREE_EMAIL_DOMAINS.has(domain.toLowerCase());
}

// Push solar-enriched prospects to PlusVibe, attaching selected solar fields as
// custom_variables so they can be used as {{merge_fields}} in the campaign.
//   body: { workspace_id, campaign_id, prospects:[{email,first_name,last_name,company_name,...solarFields}],
//           fields:[ 'owns_building','max_panels_fit','max_system_kwp','est_annual_kwh',... ] }
// The `fields` array is the tickbox selection — only these solar keys are sent.
// Freehold re-qualification — keeps solar_status honest as ownership changes.
//
// WHY THIS EXISTS SEPARATELY FROM THE SWEEP BELOW: the sweep only ever fills
// gaps (`AND ccod_owns_building IS NULL`) so it cannot correct a row that was
// already stamped. Contacts qualified before the freehold rule landed
// (01479d6 / ce0789c) carry solar_status='qualified' alongside
// ccod_owns_building='no' — 1,078 of them at the time of writing. A leaseholder
// cannot sign a 25-year rooftop PPA, so those are not prospects, and anyone
// working that list is emailing people who cannot buy.
//
// Cheap by construction: ownership is an offline CCOD lookup, so this spends NO
// Google roof quota. It only rewrites solar_status/solar_stop_reason — the
// measured roof figures (solar_max_kwp etc.) are left intact so a contact that
// later becomes a freeholder does not need re-metering.
//
//   GET /api/solar/cron/requalify?secret=$CRON_SECRET[&dry=1][&limit=N]
// Guarded by CRON_SECRET when set; also callable by an admin session for a
// manual run. dry=1 reports what would change without writing.
app.get('/api/solar/cron/requalify', async (req, res) => {
  const secret = process.env.CRON_SECRET;
  const s = decodeSession(req);
  const okSession = s?.role === 'admin' || s?.role === 'manager' || req.headers['x-admin-key'] === ADMIN_KEY;
  const okSecret = secret && req.query.secret === secret;
  if (!okSecret && !okSession) return res.status(403).json({ error: 'forbidden (CRON_SECRET or sign in)' });

  const db = req.app.locals.pgDb;
  if (!db) return res.status(503).json({ error: 'DB unavailable' });
  const dry = req.query.dry === '1' || req.query.dry === 'true';
  const limit = Math.min(100000, Math.max(1, parseInt(req.query.limit, 10) || 100000));

  try {
    // Demote: qualified, but ownership says they do not hold the freehold.
    // 'unclear'/'no_postcode' are deliberately NOT demoted — absence of a
    // verdict is not evidence of tenancy, and demoting on it would silently
    // delete prospects the CCOD index simply has no title for.
    const sel = await db.query(
      `SELECT id FROM contacts
        WHERE solar_status = 'qualified' AND ccod_owns_building = 'no'
        LIMIT $1`, [limit]);
    const ids = (sel.rows || sel).map(r => r.id);

    if (!dry && ids.length) {
      await db.query(
        `UPDATE contacts
            SET solar_status = 'disqualified', solar_stop_reason = 'tenant'
          WHERE id = ANY($1::uuid[])`, [ids]);
    }

    const after = await db.query(
      `SELECT COUNT(*) FILTER (WHERE solar_status = 'qualified')                              AS qualified,
              COUNT(*) FILTER (WHERE solar_status = 'qualified' AND ccod_owns_building = 'yes') AS qualified_freehold
         FROM contacts`);
    const a = (after.rows || after)[0] || {};

    const result = {
      ok: true, dry, demoted: ids.length,
      qualified_now: Number(a.qualified || 0),
      qualified_freehold: Number(a.qualified_freehold || 0),
      ran_at: new Date().toISOString(),
    };
    console.log('[solar-requalify]', JSON.stringify(result));
    res.json(result);
  } catch (e) {
    console.error('[solar-requalify]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// Self-running: the correction above is only useful if it happens without
// anyone remembering to trigger it, since ownership drifts as the CCOD index is
// refreshed monthly and new contacts are qualified continuously. Runs in-process
// like the other recurring jobs (postmaster, mailbox stats) — no external cron
// needed, though the endpoint stays callable for a manual or cron-job.org run.
// Free to repeat: offline lookups only, and a no-op once nothing is stale.
async function requalifySolarFreehold() {
  const db = app.locals.pgDb;
  if (!db) return;
  try {
    const sel = await db.query(
      `SELECT id FROM contacts
        WHERE solar_status = 'qualified' AND ccod_owns_building = 'no' LIMIT 100000`);
    const ids = (sel.rows || sel).map(r => r.id);
    if (!ids.length) return;
    await db.query(
      `UPDATE contacts SET solar_status = 'disqualified', solar_stop_reason = 'tenant'
        WHERE id = ANY($1::uuid[])`, [ids]);
    console.log(`[solar-requalify] demoted ${ids.length} leaseholder(s) from qualified`);
  } catch (e) { console.error('[solar-requalify]', e.message); }
}
// Once at startup (after 3 min, so the DB and CCOD index are up) then daily.
setTimeout(() => { requalifySolarFreehold().catch(() => {}); }, 3 * 60 * 1000);
setInterval(() => { requalifySolarFreehold().catch(() => {}); }, 24 * 60 * 60 * 1000);

// DB-wide (or per-workspace) OWNERSHIP sweep. Runs the offline CCOD + optional
// Companies House ownership check across contacts and writes ccod_* columns.
// NO Google/roof calls — safe and free to run on the whole database.
//   body: { workspace_id? , limit? , only_unchecked? }  (streams NDJSON progress)
// GET /api/solar/ownership-sweep/status
// The sweep streams NDJSON to whoever started it, so refreshing the page loses
// the progress display — the run itself carries on server-side, but it looks
// like it vanished. Progress is recorded in contacts.ccod_checked_at, so it can
// be read back independently of any connection.
app.get('/api/solar/ownership-sweep/status', requireSession, async (req, res) => {
  const db = req.app.locals.pgDb;
  if (!db) return res.status(503).json({ error: 'Database not available' });
  try {
    const r = await db.query(`
      SELECT
        COUNT(*) FILTER (WHERE company_name <> '' AND company_address <> '') AS candidates,
        COUNT(*) FILTER (WHERE ccod_checked_at IS NOT NULL)                  AS checked,
        COUNT(*) FILTER (WHERE ccod_checked_at > now() - interval '5 minutes') AS last_5min,
        COUNT(*) FILTER (WHERE ccod_owns_building = 'yes')                   AS owns,
        COUNT(*) FILTER (WHERE ccod_owns_building = 'no')                    AS tenant,
        COUNT(*) FILTER (WHERE ccod_owns_building = 'unclear')               AS unclear,
        MAX(ccod_checked_at)                                                 AS last_checked_at
      FROM contacts`);
    const s = r.rows[0] || {};
    const perMin = Number(s.last_5min || 0) / 5;
    const remaining = Math.max(0, Number(s.candidates || 0) - Number(s.checked || 0));
    res.json({
      ...s,
      running: Number(s.last_5min || 0) > 0,
      per_minute: Math.round(perMin),
      // Only meaningful while it is actually moving.
      eta_hours: perMin > 0 ? Math.round((remaining / perMin / 60) * 10) / 10 : null,
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// A sweep over 846k contacts runs for hours, and until now nothing could stop
// it — the only way out was restarting the container, which also killed
// anything else mid-flight. Module-scoped so the flag outlives the request that
// set it, since the sweep's own request may already be disconnected.
let _sweepStop = false;
let _sweepRunning = false;

app.post('/api/solar/ownership-sweep/stop', requireSession, (req, res) => {
  _sweepStop = true;
  res.json({ ok: true, was_running: _sweepRunning });
});

app.post('/api/solar/ownership-sweep', requireSession, async (req, res) => {
  const db = req.app.locals.pgDb;
  if (!db) return res.status(500).json({ error: 'Database not available' });
  // Refuse to start a second sweep on top of a running one: two workers writing
  // the same rows just doubles the load and confuses the progress figures.
  if (_sweepRunning) {
    return res.status(409).json({ error: 'A sweep is already running. Stop it first.' });
  }
  _sweepStop = false;
  _sweepRunning = true;
  res.on('close', () => { /* client gone; the sweep continues by design */ });
  const { ownershipOnly } = require('./lib/solar/enrich');
  const { workspace_id, limit, only_unchecked } = req.body || {};

  // Pull candidate contacts: those with a company + some address, optionally
  // scoped to a workspace, optionally only ones not yet checked.
  const where = [`(company_name IS NOT NULL AND company_name != '')`,
                 `(company_address IS NOT NULL AND company_address != '')`];
  const params = [];
  if (workspace_id) { params.push(workspace_id); where.push(`workspace_id = $${params.length}`); }
  if (only_unchecked) where.push(`ccod_checked_at IS NULL`);
  // Default to effectively "no cap" so a full-DB sweep covers every contact
  // (the table is ~600k). An explicit smaller limit still scopes the run.
  const lim = Math.min(Number(limit) || 5000000, 5000000);
  params.push(lim);

  res.writeHead(200, { 'Content-Type': 'application/x-ndjson', 'Cache-Control': 'no-store' });

  let rows;
  try {
    const q = await db.query(
      `SELECT id, company_name, company_domain, ch_company_number, ch_verified_at, company_address
       FROM contacts WHERE ${where.join(' AND ')} LIMIT $${params.length}`, params);
    rows = q.rows || q;
  } catch (e) { res.write(JSON.stringify({ error: e.message }) + '\n'); return res.end(); }

  const tally = { total: rows.length, owns: 0, tenant: 0, unclear: 0, no_postcode: 0, other: 0, multi: 0 };
  let done = 0;
  // Bounded concurrency. The CCOD lookup is offline (SQLite, microseconds); the
  // only I/O left is the occasional Companies House call, which now fires solely
  // when a freehold title exists at the postcode. At 6 the sweep ran at ~45
  // rows/min — 13 days for the full 831k. Raising this is safe because the
  // work is overwhelmingly local, and SWEEP_CONCURRENCY allows backing off
  // without a redeploy if CH starts rate-limiting.
  const CONC = Math.max(1, Math.min(64, parseInt(process.env.SWEEP_CONCURRENCY, 10) || 24));
  let cursor = 0;
  async function worker() {
    while (cursor < rows.length && !_sweepStop) {
      const c = rows[cursor++];
      let r;
      try {
        r = await ownershipOnly({
          company_name: c.company_name, company_domain: c.company_domain,
          company_reg: c.ch_company_number, company_address: c.company_address,
          // Once the CH-verify job has run, a NULL reg is authoritative ("no
          // confident CH match") — don't let the crude name->reg fallback re-guess.
          ch_verified: !!c.ch_verified_at,
        });
      } catch { r = { owns_building: 'error', building_owner: null, site_count: null }; }

      try {
        // The company-data engine is the SOURCE OF TRUTH for ccod_owns_building
        // (authoritative CH-registered-postcode + officer/PSC derivation). This older
        // Apollo-address sweep must only FILL GAPS for contacts the engine hasn't
        // stamped — never overwrite a stamped value, or it degrades the good data the
        // Contacts "owns building" filter and Solar now rely on.
        await db.query(
          `UPDATE contacts SET ccod_owns_building=$1, ccod_building_owner=$2, ccod_site_count=$3, ccod_checked_at=NOW()
             WHERE id=$4 AND ccod_owns_building IS NULL`,
          [r.owns_building, r.building_owner, r.site_count, c.id]);
      } catch (e) { /* keep going; report at end */ }

      if (r.owns_building === 'yes') { tally.owns++; if ((r.site_count || 0) > 1) tally.multi++; }
      else if (r.owns_building === 'no') tally.tenant++;
      else if (r.owns_building === 'unclear') tally.unclear++;
      else if (r.owns_building === 'no_postcode') tally.no_postcode++;
      else tally.other++;

      done++;
      if (done % 25 === 0 || done === rows.length) res.write(JSON.stringify({ progress: done, ...tally }) + '\n');
    }
  }
  await Promise.all(Array.from({ length: Math.min(CONC, rows.length) }, worker));
  // Always clear, including on stop, or the next sweep is refused as "already
  // running" for the life of the process.
  _sweepRunning = false;
  const stopped = _sweepStop;
  _sweepStop = false;
  res.write(JSON.stringify({ done: true, stopped, ...tally }) + '\n');
  res.end();
});

app.post('/api/solar/push-to-pv', requireSession, async (req, res) => {
  const { workspace_id, campaign_id, prospects, fields } = req.body || {};
  if (!workspace_id || !campaign_id || !Array.isArray(prospects) || !prospects.length) {
    return res.status(400).json({ error: 'workspace_id, campaign_id and prospects[] required' });
  }
  const selected = Array.isArray(fields) ? fields : [];

  // Human-friendly variable names for the campaign editor.
  const VAR_LABELS = {
    owns_building: 'owns_building',
    building_owner: 'building_owner',
    max_panels_fit: 'solar_panel_count',
    max_system_kwp: 'solar_system_kwp',
    est_annual_kwh: 'solar_annual_kwh',
    roof_area_m2: 'roof_area_m2',
    ppa_eligible: 'ppa_eligible',
    has_solar: 'existing_solar',
    imagery_date: 'roof_imagery_date',
    maps_url: 'roof_maps_link',
  };

  try {
    const leads = prospects
      .filter((p) => p.email && p.first_name && p.last_name)
      .map((p) => {
        const custom = {};
        for (const key of selected) {
          if (p[key] == null || p[key] === '') continue;
          custom[VAR_LABELS[key] || key] = String(p[key]);
        }
        // Match PlusVibe's accepted /lead/add schema (same as the Contacts push's
        // toLead). Prior bugs: phone_number was null (PV requires a STRING → use '');
        // `website`/`linkedin_url` are NOT allowed top-level (the allowed field is
        // `company_website`). Empty strings for optional fields, not null.
        const lead = {
          email: p.email,
          first_name: p.first_name,
          last_name: p.last_name,
          company_name: p.company_name || '',
          job_title: p.job_title || '',
          phone_number: p.phone ? String(p.phone) : '',
          company_website: p.company_domain || '',
          custom_variables: custom,
        };
        return sanitizePvLead(lead).lead; // email local-part + phone coercion, like the Contacts push
      });

    if (!leads.length) return res.status(400).json({ error: 'No prospects with email + first/last name' });

    let pushed = 0;
    for (let i = 0; i < leads.length; i += 100) {
      const batch = leads.slice(i, i + 100);
      const body = { workspace_id, campaign_id, leads: batch };
      try {
        await pvApi('/lead/import', { method: 'POST', wsId: workspace_id, body });
      } catch {
        await pvApi('/lead/add', { method: 'POST', wsId: workspace_id, body });
      }
      pushed += batch.length;
    }
    res.json({ ok: true, pushed, skipped: prospects.length - pushed, variables_sent: selected.map((k) => VAR_LABELS[k] || k) });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// One-shot: flag all existing contacts whose email is on a free/consumer domain.
// Safe to run multiple times (WHERE email_status != 'invalid' guards it).
app.post('/api/admin/flag-free-domain-contacts', requireAdmin, async (req, res) => {
  const pgdb = req.app.locals.pgDb;
  if (!pgdb) return res.status(503).json({ error: 'DB unavailable' });
  try {
    const domainList = [...FREE_EMAIL_DOMAINS].map(d => `%@${d}`);
    // Build: email ILIKE '%@gmail.com' OR email ILIKE '%@email.com' …
    const conditions = domainList.map((_, i) => `email ILIKE $${i + 1}`).join(' OR ');
    const { rowCount } = await pgdb.query(
      `UPDATE contacts
          SET email_status = 'invalid', do_not_contact = true, updated_at = NOW()
        WHERE (${conditions})
          AND (email_status IS DISTINCT FROM 'invalid' OR do_not_contact IS DISTINCT FROM true)`,
      domainList
    );
    // Also log what we found (for the peter.parker audit)
    const found = await pgdb.query(
      `SELECT email, workspace_id, created_at FROM contacts WHERE (${conditions}) ORDER BY created_at LIMIT 500`,
      domainList
    );
    console.log(`[flag-free-domains] flagged ${rowCount} contacts; sample:`, found.rows.slice(0, 10).map(r => r.email));
    res.json({ ok: true, flagged: rowCount, sample: found.rows.slice(0, 50) });
  } catch (err) {
    console.error('[flag-free-domains]', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Shared contact→pushable filter (same rules as the PV path). Pure function.
// `departed` is passed in rather than looked up here so this stays synchronous:
// an empty set means "no block", so the caller must fetch it via
// getDepartedEmails().
function filterPushableContacts(allContacts, { cooldownWorkspaceId, campaignName, allowedStatuses, pushWorkspaceId, workspaceName, departed = new Set() }) {
  const cooloffDate = sameClientCooloffDate();
  const campaignNameLc = (campaignName || '').toString().trim().toLowerCase();
  const skipped = { unsafe: 0, dnc: 0, freeDomain: 0, cooldownWorkspace: 0, verticalCollision: 0, burstGap: 0, densityCeiling: 0, alreadyInCampaign: 0, missingEnrichment: 0, missingName: 0 };
  // Guard against the workspace actually being pushed to; cooldownWorkspaceId
  // is optional on this path, so fall back to it only when no target is given.
  const crossClientGuard = buildCrossClientGuard(pushWorkspaceId || cooldownWorkspaceId || '', workspaceName || '');
  // Caller-chosen verification buckets; default to the safe pair when absent.
  const KNOWN_STATUSES = ['safe', 'safe_catchall', 'unknown', 'risky', 'invalid'];
  const validStatuses = Array.isArray(allowedStatuses)
    ? allowedStatuses.map(s => String(s).toLowerCase()).filter(s => KNOWN_STATUSES.includes(s))
    : [];
  const PUSHABLE_STATUSES = new Set(validStatuses.length ? validStatuses : ['safe', 'safe_catchall']);
  const contacts = allContacts.filter(c => {
    if (isFreeDomain(c.email)) { skipped.freeDomain++; return false; }
    if (!PUSHABLE_STATUSES.has((c.email_status || '').toLowerCase())) { skipped.unsafe++; return false; }
    if (c.do_not_contact) { skipped.dnc++; return false; }
    if (departed.has(String(c.email || '').toLowerCase())) { skipped.departed = (skipped.departed || 0) + 1; return false; }
    // Bison requires non-empty first_name AND last_name (422s otherwise).
    if (!(c.first_name && c.first_name.trim()) || !(c.last_name && c.last_name.trim())) {
      skipped.missingName++; return false;
    }
    if ((!c.keywords || c.keywords.trim() === '') || (!c.industry || c.industry.trim() === '')) {
      skipped.missingEnrichment++; return false;
    }
    if (campaignNameLc && c.last_campaign_name && c.last_campaign_name.toLowerCase() === campaignNameLc) {
      skipped.alreadyInCampaign++; return false;
    }
    if (cooldownWorkspaceId) {
      const emailed = typeof c.emailed_workspaces === 'string'
        ? JSON.parse(c.emailed_workspaces || '{}')
        : (c.emailed_workspaces || {});
      const lastSent = emailed[cooldownWorkspaceId]?.last_sent;
      if (lastSent && lastSent >= cooloffDate) { skipped.cooldownWorkspace++; return false; }
    }
    // Cross-client spacing: same vertical, then any client inside 30 days.
    if (!crossClientGuard(c, skipped)) return false;
    return true;
  });
  return { contacts, skipped };
}

// Map an Ottaly contact to a PlusVibe lead (top-level native fields — NO custom_variables for native fields).
function contactToBisonLead(c) {
  const raw = typeof c.raw_data === 'string' ? JSON.parse(c.raw_data || '{}') : (c.raw_data || {});
  return {
    email:               c.email,
    first_name:          c.first_name || '',
    last_name:           c.last_name  || '',
    job_title:           c.job_title  || '',
    company_name:        c.company_name || '',
    phone_number:        c.phone || null,
    company_website:     c.company_domain || null,
    industry:            raw.Industry || c.industry || null,
    linkedin_person_url: c.linkedin_url || null,
    linkedin_company_url:c.company_linkedin_url || null,
    city:                c.company_city || c.city || null,
    state:               c.company_county || c.company_state || c.state || null,
    country:             c.company_country || c.country || null,
    address_line:        null,
    department:          null,
  };
}

// GET /api/bison/workspaces — PlusVibe workspaces for the push dropdown.
app.get('/api/bison/workspaces', requireSession, (req, res) => {
  res.json({ workspaces: PV_WORKSPACES.map(t => ({ id: t.pv, name: t.name, pv_workspace_id: t.pv })) });
});

// GET /api/bison/campaigns?ws_id=  — live PlusVibe campaigns for a workspace.
app.get('/api/bison/campaigns', requireSession, async (req, res) => {
  const wsId = String(req.query.ws_id || '');
  if (!wsId) return res.status(400).json({ error: 'ws_id required' });
  try {
    const data = await pvApi('/campaign/list', { wsId });
    if (req.query.raw) return res.json({ raw: data });
    const list = Array.isArray(data) ? data : (data?.data || data?.campaigns || []);
    res.json({ campaigns: list.map(c => ({ id: String(c._id || c.id), name: c.name, status: c.status })) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/bison/create-campaign  — create a new campaign in PlusVibe.
// body: { ws_id, name }
app.post('/api/bison/create-campaign', requireSession, async (req, res) => {
  const name = String(req.body.name || '').trim();
  const wsId = String(req.body.ws_id || '').trim();
  if (!wsId || !name) return res.status(400).json({ error: 'ws_id and a non-empty name are required' });
  if (!getPvKey()) return res.status(500).json({ error: 'PlusVibe API key not configured — set it in admin settings' });
  try {
    // PlusVibe create campaign: POST /campaign/add/campaign { workspace_id, camp_name }
    // → { status: 'success', id: '<new campaign id>' }
    const resp = await pvApi('/campaign/add/campaign', { method: 'POST', wsId, body: { workspace_id: wsId, camp_name: name } });
    const cid = resp?.id || resp?.data?.id || resp?._id || '';
    if (!cid) throw new Error('PlusVibe did not return a campaign id');
    res.json({ ok: true, campaign: { id: String(cid), name, status: 'DRAFT' }, warnings: [] });
  } catch (err) {
    res.status(502).json({ error: err.message || 'Failed to create campaign' });
  }
});

// POST /api/bison/push-contacts
// body: { ws_id, campaign_id, contact_ids, campaign_name?, cooldown_workspace_id? }
app.post('/api/bison/push-contacts', requireSession, async (req, res) => {
  const { ws_id, campaign_id, contact_ids } = req.body;
  if (!ws_id || !campaign_id || !Array.isArray(contact_ids) || contact_ids.length === 0) {
    return res.status(400).json({ error: 'ws_id, campaign_id and contact_ids required' });
  }
  if (!getPvKey()) return res.status(500).json({ error: 'PlusVibe API key not configured — set it in admin settings' });
  try {
    const pgDb = req.app.locals.pgDb;
    if (!pgDb || !pgDb.getContactsById) return res.status(500).json({ error: 'Contacts DB not available' });
    const allContacts = await pgDb.getContactsById(contact_ids);
    if (allContacts.length === 0) return res.status(404).json({ error: 'No contacts found' });

    const cooldownWorkspaceId = req.body.cooldown_workspace_id || null;
    // Guard and stamp must agree on which workspace this push belongs to, or
    // a contact could be checked against one key and recorded under another.
    // ws_id is the fallback: the stamp used to be skipped entirely when no
    // cooldown_workspace_id was sent, leaving those pushes invisible to every
    // downstream cooldown.
    const guardWorkspaceId = cooldownWorkspaceId || ws_id;
    const { contacts, skipped } = filterPushableContacts(allContacts, {
      cooldownWorkspaceId, campaignName: req.body.campaign_name,
      allowedStatuses: req.body.allowed_statuses,
      pushWorkspaceId: guardWorkspaceId, workspaceName: req.body.workspace_name || '',
      departed: await getDepartedEmails(req.app.locals.pgDb),
    });
    console.log(`[pv-push] filtered ${allContacts.length} → ${contacts.length}`, skipped);
    if (contacts.length === 0) return res.json({ success: true, pushed: 0, total: 0, skipped });

    // Reserve before pushing — see the note on /api/pv/push-contacts. Awaiting
    // this is what makes the cross-client guard authoritative under concurrency.
    const pushedIds = contacts.map(c => c.id).filter(Boolean);
    if (pushedIds.length && guardWorkspaceId && pgDb.stampPushedCampaign) {
      try {
        await pgDb.stampPushedCampaign(pushedIds, guardWorkspaceId, String(campaign_id), req.body.campaign_name || '');
      } catch (err) {
        console.error('[pv-push] reserve failed, aborting push:', err.message);
        return res.status(500).json({ error: 'Could not reserve contacts before push: ' + err.message });
      }
    }

    // Push leads to PlusVibe /lead/add — batch { workspace_id, campaign_id, leads }
    // (top-level native fields; campaign assignment happens in the same call).
    let pushed = 0;
    for (let i = 0; i < contacts.length; i += 100) {
      const slice = contacts.slice(i, i + 100);
      const leads = slice.map(contactToBisonLead).filter(l => l.first_name && l.last_name);
      if (!leads.length) continue;
      try {
        await pvApi('/lead/add', { method: 'POST', wsId: ws_id, body: { workspace_id: ws_id, campaign_id, leads } });
        pushed += leads.length;
      } catch (e) { console.warn('[pv-push] lead add failed:', e.message); }
    }

    res.json({ success: true, pushed, total: contacts.length, skipped });
  } catch (err) {
    console.error('[PV Push]', err.message);
    res.status(500).json({ error: err.message });
  }
});

