// ── Reply facts ─────────────────────────────────────────────────
// What a lead actually told us in a reply. Company-level facts (premises,
// supplier, ceased trading) are looked up by DOMAIN so one reply covers every
// colleague; person_left is looked up by EMAIL so it only silences that
// individual. Every row carries the sentence it came from — a fact with no
// quote is not trustworthy enough to filter on.
app.get('/api/contacts/facts', requireSession, async (req, res) => {
  try {
    const dbPg = req.app.locals.pgDb;
    if (!dbPg) return res.status(503).json({ error: 'Database unavailable' });
    const email = String(req.query.email || '').trim().toLowerCase();
    if (!email) return res.status(400).json({ error: 'email required' });
    const domain = email.split('@')[1] || '';
    const r = await dbPg.query(
      `SELECT attribute, value, vertical, confidence, quote, observed_at, extractor,
              (LOWER(lead_email) = $1) AS is_this_person
         FROM reply_facts
        WHERE company_domain = $2 OR LOWER(lead_email) = $1
        ORDER BY observed_at DESC`,
      [email, domain]
    );
    // person_left about a colleague must not read as a fact about this contact.
    const rows = r.rows.filter(f => f.attribute !== 'person_left' || f.is_this_person);
    res.json({ facts: rows });
  } catch (err) {
    console.error('[contacts/facts] error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Distinct attribute/value/vertical combinations, so the filter UI can offer
// exactly what exists rather than a hardcoded list that drifts.
app.get('/api/contacts/fact-options', requireSession, async (req, res) => {
  try {
    const dbPg = req.app.locals.pgDb;
    if (!dbPg) return res.status(503).json({ error: 'Database unavailable' });
    const r = await dbPg.query(
      `SELECT attribute, value, vertical, COUNT(*)::int AS n,
              COUNT(DISTINCT company_domain)::int AS companies
         FROM reply_facts
        GROUP BY attribute, value, vertical
        ORDER BY attribute, n DESC`
    );
    res.json({ options: r.rows });
  } catch (err) {
    console.error('[contacts/fact-options] error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/contacts/verified-today', requireSession, async (req, res) => {
  try {
    const dbPg = req.app.locals.pgDb;
    if (!dbPg) return res.status(503).json({ error: 'Database unavailable' });
    const result = await dbPg.query(`
      SELECT
        COUNT(*)                                                          AS total,
        COUNT(*) FILTER (WHERE email_status IN ('safe','safe_catchall')) AS safe,
        COUNT(*) FILTER (WHERE email_status = 'invalid')                 AS invalid,
        COUNT(*) FILTER (WHERE email_status = 'risky')                   AS risky,
        COUNT(*) FILTER (WHERE email_status = 'unknown')                 AS unknown
      FROM contacts
      WHERE email_verified_at::timestamptz >= NOW() - INTERVAL '24 hours'
    `);
    const row = result.rows[0];
    res.json({
      total:   +row.total,
      safe:    +row.safe,
      invalid: +row.invalid,
      risky:   +row.risky,
      unknown: +row.unknown,
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/contacts/push-jobs', requireSession, (req, res) => {
  // Queue shows in-flight + paused + FAILED jobs only. A job that completed
  // successfully or was cancelled is removed from view — only unsuccessful ones
  // stick around so they can be seen/retried. (verify-only CSV jobs are kept
  // while their download is still available so the ⬇ CSV button works.)
  const KEEP = new Set(['verifying','pushing','n2b_verifying','pausing','paused','failed','error']);
  const jobs = [...pushJobs.values()]
    .filter(j => {
      if (KEEP.has(j.status)) return true;
      // A verify-only job that finished but still has a CSV to grab stays.
      if (j.status === 'completed' && j.verifyOnly && (j.safe_ids?.length || 0) > 0) return true;
      return false; // completed-success + cancelled → hidden
    })
    .sort((a, b) => b.created_at - a.created_at)
    .slice(0, 20);
  res.json({ jobs });
});

// Push HISTORY — every finished job, newest first. The queue above deliberately
// hides completed jobs, so this is the only place to answer "I pushed 3,000
// contacts, why did only 900 arrive?" after the fact.
//
// Merges two sources: rows persisted to SQLite when a job finished (survives
// restarts), plus anything still in memory that hasn't been written yet, so a
// job that is mid-run still shows up rather than vanishing until it completes.
app.get('/api/contacts/push-history', requireSession, (req, res) => {
  const limit = Math.min(parseInt(req.query.limit) || 50, 200);
  const out = [];
  try {
    const sq = req.app.locals.sqliteDb;
    if (sq) {
      initPausedJobsTable(sq);
      const rows = sq.prepare(
        `SELECT * FROM push_job_history ORDER BY finished_at DESC LIMIT ?`
      ).all(limit);
      for (const r of rows) {
        let skipped = {};
        try { skipped = JSON.parse(r.skipped_json || '{}') || {}; } catch {}
        out.push({
          id: r.id, source: 'history',
          workspace_id: r.workspace_id, workspace_name: r.workspace_name,
          campaign_id: r.campaign_id, campaign_name: r.campaign_name,
          started_at: r.started_at, finished_at: r.finished_at,
          status: r.status,
          requested: r.requested, verified: r.verified, pushed: r.pushed,
          safe: r.safe, risky: r.risky, invalid: r.invalid,
          unknown: r.unknown, safe_catchall: r.safe_catchall,
          skipped_total: r.skipped_total, skipped, error: r.error,
        });
      }
    }
  } catch (e) {
    console.warn('[push-history] read failed:', e.message);
  }
  // In-memory jobs not yet persisted (still running, or written pre-upgrade).
  const seen = new Set(out.map(j => j.id));
  for (const j of pushJobs.values()) {
    if (seen.has(j.id)) continue;
    // Live jobs stamp created_at as epoch ms (not started_at, and jobs restored
    // from paused_push_jobs on boot carry neither) -- normalise to ISO so the UI
    // has one date field to render. paused_at is the best available fallback for
    // a restored job.
    const startedIso = j.started_at
      || (typeof j.created_at === 'number' ? new Date(j.created_at).toISOString() : null)
      || j.paused_at
      || null;
    out.push({
      id: j.id, source: 'live',
      workspace_id: j.workspace_id, workspace_name: j.workspace_name,
      campaign_id: j.campaign_id, campaign_name: j.campaign_name,
      started_at: startedIso, finished_at: null,
      status: j.status,
      requested: j.requested || j.total || 0,
      verified: j.verified || 0, pushed: j.pushed || 0,
      safe: j.safe, risky: j.risky, invalid: j.invalid,
      unknown: j.unknown, safe_catchall: j.safe_catchall,
      // `job.skipped` means TWO different things depending on the phase, and
      // conflating them made the UI report 1,425 contacts as rejected when they
      // had merely been skipped past re-verification:
      //   * a NUMBER during verify  = contacts with a still-fresh verdict, so
      //     Reacher didn't re-check them. They are NOT dropped from the push.
      //   * an OBJECT once pushing  = the real per-gate rejection breakdown.
      // Keep them in separate fields so the UI can label each correctly.
      skipped_total: (j.skipped && typeof j.skipped === 'object')
        ? Object.values(j.skipped).reduce((a, v) => a + (Number(v) || 0), 0)
        : 0,
      skipped: (j.skipped && typeof j.skipped === 'object') ? j.skipped : {},
      already_verified: (j.skipped && typeof j.skipped === 'object')
        ? 0 : (Number(j.skipped) || 0),
      to_verify: Number(j.toVerify || 0),
      error: j.error || null,
    });
  }
  out.sort((a, b) => String(b.finished_at || b.started_at || '')
                     .localeCompare(String(a.finished_at || a.started_at || '')));
  res.json({ jobs: out.slice(0, limit) });
});

